import { Controller, Get } from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse } from '@nestjs/swagger';
import { Public } from './common';
import { DatabaseService } from './modules/database';
import { RedisService } from './modules/redis';
import { QdrantService } from './modules/qdrant';

interface HealthStatus {
  status: 'healthy' | 'degraded' | 'unhealthy';
  timestamp: string;
  version: string;
  services: {
    database: boolean;
    redis: boolean;
    qdrant: boolean;
  };
}

@ApiTags('Health')
@Controller()
export class HealthController {
  constructor(
    private readonly database: DatabaseService,
    private readonly redis: RedisService,
    private readonly qdrant: QdrantService,
  ) {}

  @Public()
  @Get('health')
  @ApiOperation({ summary: 'Health check endpoint' })
  @ApiResponse({ status: 200, description: 'Service health status' })
  async health(): Promise<HealthStatus> {
    const [dbHealth, redisHealth, qdrantHealth] = await Promise.all([
      this.database.healthCheck().catch(() => false),
      this.redis.healthCheck().catch(() => false),
      this.qdrant.healthCheck().catch(() => false),
    ]);

    const allHealthy = dbHealth && redisHealth && qdrantHealth;
    const anyHealthy = dbHealth || redisHealth || qdrantHealth;

    return {
      status: allHealthy ? 'healthy' : anyHealthy ? 'degraded' : 'unhealthy',
      timestamp: new Date().toISOString(),
      version: process.env.npm_package_version || '1.0.0',
      services: {
        database: dbHealth,
        redis: redisHealth,
        qdrant: qdrantHealth,
      },
    };
  }

  @Public()
  @Get()
  @ApiOperation({ summary: 'Root endpoint' })
  @ApiResponse({ status: 200, description: 'API info' })
  root() {
    return {
      name: 'Studyield API',
      version: process.env.npm_package_version || '1.0.0',
      documentation: '/api/docs',
    };
  }
}

import { NestFactory } from '@nestjs/core';
import { ValidationPipe, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import { IoAdapter } from '@nestjs/platform-socket.io';
import { AppModule } from './app.module';
import * as bodyParser from 'body-parser';

async function bootstrap() {
  const logger = new Logger('Bootstrap');

  const app = await NestFactory.create(AppModule, {
    rawBody: true, // Required for Stripe webhooks
  });

  // Increase payload size limit to 50MB
  app.use(bodyParser.json({ limit: '50mb' }));
  app.use(bodyParser.urlencoded({ limit: '50mb', extended: true }));

  const configService = app.get(ConfigService);

  // API prefix
  const apiPrefix = configService.get<string>('API_PREFIX', 'api/v1');
  app.setGlobalPrefix(apiPrefix);

  // CORS — reflect request origin for dev flexibility
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  app.use((req: any, res: any, next: any) => {
    res.header('Access-Control-Allow-Origin', req.headers.origin || '*');
    res.header('Access-Control-Allow-Methods', 'GET,HEAD,PUT,PATCH,POST,DELETE,OPTIONS');
    res.header(
      'Access-Control-Allow-Headers',
      'Origin,X-Requested-With,Content-Type,Accept,Authorization',
    );
    res.header('Access-Control-Allow-Credentials', 'true');
    res.header('Access-Control-Max-Age', '86400');
    if (req.method === 'OPTIONS') {
      return res.status(200).end();
    }
    next();
  });

  // Validation Pipe
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
      transformOptions: {
        enableImplicitConversion: true,
      },
    }),
  );

  // WebSocket adapter
  app.useWebSocketAdapter(new IoAdapter(app));

  // Swagger Documentation
  const swaggerConfig = new DocumentBuilder()
    .setTitle('Studyield API')
    .setDescription('AI-powered learning platform API')
    .setVersion('1.0.0')
    .addBearerAuth()
    .addTag('Health', 'Health check endpoints')
    .addTag('Auth', 'Authentication endpoints')
    .addTag('Users', 'User management')
    .addTag('Study Sets', 'Study set management')
    .addTag('Documents', 'Document management')
    .addTag('Flashcards', 'Flashcard management with SRS')
    .addTag('Knowledge Base', 'RAG knowledge base')
    .addTag('Chat', 'RAG-powered chat')
    .addTag('Quiz', 'AI-generated quizzes')
    .addTag('Exam Clone', 'Exam style cloning')
    .addTag('Problem Solver', 'Multi-agent problem solving')
    .addTag('Knowledge Graph', 'Entity-relation mapping')
    .addTag('Teach-Back', 'Feynman technique evaluation')
    .addTag('Research', 'Deep research mode')
    .addTag('Code Sandbox', 'Python code execution')
    .addTag('Learning Paths', 'AI-generated study routes')
    .addTag('Subscription', 'Stripe billing')
    .addTag('Analytics', 'Usage analytics')
    .addTag('Notifications', 'Notification management')
    .build();

  const document = SwaggerModule.createDocument(app, swaggerConfig);
  SwaggerModule.setup(`${apiPrefix}/docs`, app, document, {
    swaggerOptions: {
      persistAuthorization: true,
    },
  });

  // Start server
  const port = configService.get<number>('PORT', 3010);
  await app.listen(port);

  logger.log(`🚀 Application is running on: http://localhost:${port}`);
  logger.log(`📚 Swagger documentation: http://localhost:${port}/${apiPrefix}/docs`);
  logger.log(`🔌 WebSocket server ready`);
}

bootstrap();

