import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { Type } from 'class-transformer';
import { IsInt, IsOptional, Max, Min } from 'class-validator';

export class PaginationDto {
  @ApiPropertyOptional({ default: 1, minimum: 1 })
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @IsOptional()
  page?: number = 1;

  @ApiPropertyOptional({ default: 20, minimum: 1, maximum: 100 })
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(100)
  @IsOptional()
  limit?: number = 20;

  get offset(): number {
    return ((this.page || 1) - 1) * (this.limit || 20);
  }
}

export class PaginatedResponseDto<T> {
  @ApiProperty()
  data: T[];

  @ApiProperty()
  total: number;

  @ApiProperty()
  page: number;

  @ApiProperty()
  limit: number;

  @ApiProperty()
  totalPages: number;

  @ApiProperty()
  hasMore: boolean;

  constructor(data: T[], total: number, page: number, limit: number) {
    this.data = data;
    this.total = total;
    this.page = page;
    this.limit = limit;
    this.totalPages = Math.ceil(total / limit);
    this.hasMore = page < this.totalPages;
  }
}

import {
  ExceptionFilter,
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { Response } from 'express';

export interface ErrorResponse {
  statusCode: number;
  message: string;
  error: string;
  timestamp: string;
  path: string;
  details?: unknown;
}

@Catch()
export class HttpExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(HttpExceptionFilter.name);

  catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const request = ctx.getRequest();

    let status = HttpStatus.INTERNAL_SERVER_ERROR;
    let message = 'Internal server error';
    let error = 'Internal Server Error';
    let details: unknown = undefined;

    if (exception instanceof HttpException) {
      status = exception.getStatus();
      const exceptionResponse = exception.getResponse();

      if (typeof exceptionResponse === 'string') {
        message = exceptionResponse;
      } else if (typeof exceptionResponse === 'object') {
        const resp = exceptionResponse as Record<string, unknown>;
        message = (resp.message as string) || message;
        error = (resp.error as string) || error;
        details = resp.details;

        if (Array.isArray(resp.message)) {
          message = resp.message.join(', ');
          details = resp.message;
        }
      }
    } else if (exception instanceof Error) {
      message = exception.message;
      this.logger.error(`Unhandled exception: ${exception.message}`, exception.stack);
    }

    const errorResponse: ErrorResponse = {
      statusCode: status,
      message,
      error,
      timestamp: new Date().toISOString(),
      path: request.url,
    };

    if (details) {
      errorResponse.details = details;
    }

    response.status(status).json(errorResponse);
  }
}

import { ArgumentsHost, Catch, Logger } from '@nestjs/common';
import { BaseWsExceptionFilter, WsException } from '@nestjs/websockets';
import { Socket } from 'socket.io';

@Catch(WsException)
export class WsExceptionFilter extends BaseWsExceptionFilter {
  private readonly logger = new Logger(WsExceptionFilter.name);

  catch(exception: WsException, host: ArgumentsHost) {
    const client: Socket = host.switchToWs().getClient();
    const error = exception.getError();

    const errorResponse = {
      event: 'error',
      data: {
        message: typeof error === 'string' ? error : (error as { message: string }).message,
        timestamp: new Date().toISOString(),
      },
    };

    this.logger.warn(`WebSocket error for client ${client.id}: ${errorResponse.data.message}`);
    client.emit('error', errorResponse.data);
  }
}

import { Logger } from '@nestjs/common';
import {
  WebSocketGateway,
  SubscribeMessage,
  MessageBody,
  ConnectedSocket,
} from '@nestjs/websockets';
import { Socket } from 'socket.io';
import { BaseGateway } from './base.gateway';

@WebSocketGateway({
  namespace: 'app',
  cors: {
    origin: process.env.CORS_ORIGINS?.split(',') || [
      'http://localhost:3010',
      'http://localhost:5189',
    ],
    credentials: true,
  },
})
export class AppGateway extends BaseGateway {
  protected readonly logger = new Logger(AppGateway.name);

  @SubscribeMessage('ping')
  handlePing(@ConnectedSocket() _client: Socket): { event: string; data: string } {
    return { event: 'pong', data: 'pong' };
  }

  @SubscribeMessage('subscribe')
  handleSubscribe(
    @MessageBody() data: { channel: string },
    @ConnectedSocket() client: Socket,
  ): { event: string; data: { subscribed: string } } {
    const user = this.getUserFromSocket(client);
    if (!user) {
      return { event: 'error', data: { subscribed: '' } };
    }

    const allowedPrefixes = ['study-set:', 'conversation:', 'quiz:'];
    const isAllowed = allowedPrefixes.some((prefix) => data.channel.startsWith(prefix));

    if (!isAllowed) {
      return { event: 'error', data: { subscribed: '' } };
    }

    this.joinRoom(client, data.channel);
    return { event: 'subscribed', data: { subscribed: data.channel } };
  }

  @SubscribeMessage('unsubscribe')
  handleUnsubscribe(
    @MessageBody() data: { channel: string },
    @ConnectedSocket() client: Socket,
  ): { event: string; data: { unsubscribed: string } } {
    this.leaveRoom(client, data.channel);
    return { event: 'unsubscribed', data: { unsubscribed: data.channel } };
  }

  notifyUser(
    userId: string,
    notification: {
      type: string;
      title: string;
      message: string;
      id?: string;
      link?: string | null;
      createdAt?: string;
    },
  ) {
    this.emitToUser(userId, 'notification', notification);
  }

  notifyChannel(channel: string, event: string, data: unknown) {
    this.emitToRoom(channel, event, data);
  }
}

import { Logger, UseFilters, UseGuards } from '@nestjs/common';
import {
  OnGatewayConnection,
  OnGatewayDisconnect,
  OnGatewayInit,
  WebSocketServer,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { WsAuthGuard } from '../guards/ws-auth.guard';
import { WsExceptionFilter } from '../filters/ws-exception.filter';

@UseGuards(WsAuthGuard)
@UseFilters(WsExceptionFilter)
export abstract class BaseGateway
  implements OnGatewayInit, OnGatewayConnection, OnGatewayDisconnect
{
  protected abstract readonly logger: Logger;

  @WebSocketServer()
  protected server: Server;

  afterInit(_server: Server) {
    this.logger.log('WebSocket gateway initialized');
  }

  handleConnection(client: Socket) {
    const userId = client.data.user?.sub;
    this.logger.log(`Client connected: ${client.id} (user: ${userId || 'unauthenticated'})`);

    if (userId) {
      client.join(`user:${userId}`);
    }
  }

  handleDisconnect(client: Socket) {
    const userId = client.data.user?.sub;
    this.logger.log(`Client disconnected: ${client.id} (user: ${userId || 'unauthenticated'})`);
  }

  protected emitToUser(userId: string, event: string, data: unknown) {
    this.server.to(`user:${userId}`).emit(event, data);
  }

  protected emitToRoom(room: string, event: string, data: unknown) {
    this.server.to(room).emit(event, data);
  }

  protected broadcast(event: string, data: unknown) {
    this.server.emit(event, data);
  }

  protected joinRoom(client: Socket, room: string) {
    client.join(room);
    this.logger.debug(`Client ${client.id} joined room: ${room}`);
  }

  protected leaveRoom(client: Socket, room: string) {
    client.leave(room);
    this.logger.debug(`Client ${client.id} left room: ${room}`);
  }

  protected getUserFromSocket(client: Socket): { sub: string; email: string; role: string } | null {
    return client.data.user || null;
  }
}

