import { ExecutionContext, Injectable, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { AuthGuard } from '@nestjs/passport';
import { IS_PUBLIC_KEY } from '../decorators/public.decorator';

@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  constructor(private reflector: Reflector) {
    super();
  }

  canActivate(context: ExecutionContext) {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    if (isPublic) {
      return true;
    }

    return super.canActivate(context);
  }

  handleRequest<TUser = unknown>(err: Error | null, user: TUser, _info: unknown): TUser {
    if (err || !user) {
      throw err || new UnauthorizedException('Invalid or expired token');
    }
    return user;
  }
}

import { Injectable, CanActivate, ExecutionContext, ForbiddenException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PLAN_FEATURE_KEY, PlanFeatureMeta } from '../decorators/plan-feature.decorator';
import { SubscriptionService } from '../../modules/subscription/subscription.service';

@Injectable()
export class PlanGuard implements CanActivate {
  constructor(
    private readonly reflector: Reflector,
    private readonly subscriptionService: SubscriptionService,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const meta = this.reflector.getAllAndOverride<PlanFeatureMeta>(PLAN_FEATURE_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    // No @PlanFeature metadata → endpoint is not gated
    if (!meta) {
      return true;
    }

    // Determine user ID based on context type (HTTP or WS)
    let userId: string | undefined;

    const ctxType = context.getType();
    if (ctxType === 'http') {
      const request = context.switchToHttp().getRequest();
      userId = request.user?.sub;
    } else if (ctxType === 'ws') {
      const client = context.switchToWs().getClient();
      userId = client.data?.user?.sub;
    }

    if (!userId) {
      throw new ForbiddenException({
        message: 'Authentication required',
        upgrade: false,
      });
    }

    const isPro = await this.subscriptionService.isPro(userId);
    if (isPro) {
      return true;
    }

    throw new ForbiddenException({
      message: `This feature requires a Pro plan`,
      upgrade: true,
      feature: meta.feature,
    });
  }
}

import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_KEY, Role } from '../decorators/roles.decorator';
import { JwtPayload } from '../decorators/current-user.decorator';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride<Role[]>(ROLES_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    if (!requiredRoles || requiredRoles.length === 0) {
      return true;
    }

    const request = context.switchToHttp().getRequest();
    const user = request.user as JwtPayload;

    if (!user) {
      return false;
    }

    return requiredRoles.some((role) => user.role === role);
  }
}

import { CanActivate, ExecutionContext, Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { JwtService } from '@nestjs/jwt';
import { WsException } from '@nestjs/websockets';
import { Socket } from 'socket.io';
import { JwtPayload } from '../decorators/current-user.decorator';

@Injectable()
export class WsAuthGuard implements CanActivate {
  private readonly logger = new Logger(WsAuthGuard.name);

  constructor(
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const client: Socket = context.switchToWs().getClient();
    const token = this.extractToken(client);

    this.logger.debug(`Auth check - token exists: ${!!token}, client: ${client.id}`);

    if (!token) {
      this.logger.warn(`No token provided for client ${client.id}`);
      throw new WsException('Unauthorized');
    }

    try {
      const payload = await this.jwtService.verifyAsync<JwtPayload>(token, {
        secret: this.configService.get<string>('JWT_ACCESS_SECRET'),
      });
      this.logger.debug(`Token verified successfully for user: ${payload.sub}`);
      client.data.user = payload;
      return true;
    } catch (error) {
      this.logger.error(
        `Token verification failed for client ${client.id}: ${(error as Error).message}`,
      );

      throw new WsException('Invalid token');
    }
  }

  private extractToken(client: Socket): string | null {
    const authToken = client.handshake.auth?.token;
    const authHeader = client.handshake.headers?.authorization;

    this.logger.debug(
      `extractToken - auth.token: ${authToken ? 'present' : 'missing'}, authorization header: ${authHeader ? 'present' : 'missing'}`,
    );

    const auth = authToken || authHeader;
    if (!auth) return null;

    if (typeof auth === 'string' && auth.startsWith('Bearer ')) {
      return auth.slice(7);
    }

    return auth as string;
  }
}

import { Injectable, NestInterceptor, ExecutionContext, CallHandler } from '@nestjs/common';
import { Observable } from 'rxjs';

function snakeToCamel(str: string): string {
  return str.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase());
}

function camelToSnake(str: string): string {
  return str.replace(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`);
}

function transformKeys(obj: unknown, transformer: (key: string) => string): unknown {
  if (obj === null || obj === undefined) {
    return obj;
  }

  if (Array.isArray(obj)) {
    return obj.map((item) => transformKeys(item, transformer));
  }

  if (obj instanceof Date) {
    return obj;
  }

  if (typeof obj === 'object') {
    const transformed: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(obj as Record<string, unknown>)) {
      const newKey = transformer(key);
      transformed[newKey] = transformKeys(value, transformer);
    }
    return transformed;
  }

  return obj;
}

@Injectable()
export class CamelCaseInterceptor implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    // Don't transform incoming requests - mobile already sends camelCase
    // DTOs expect camelCase, so leave request.body as-is

    // Don't transform outgoing responses either - keep camelCase for mobile
    return next.handle();
  }
}

export class CamelCaseTransformer {
  static toCamelCase<T>(obj: unknown): T {
    return transformKeys(obj, snakeToCamel) as T;
  }

  static toSnakeCase<T>(obj: unknown): T {
    return transformKeys(obj, camelToSnake) as T;
  }
}

import { Injectable, NestInterceptor, ExecutionContext, CallHandler, Logger } from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';

@Injectable()
export class LoggingInterceptor implements NestInterceptor {
  private readonly logger = new Logger('HTTP');

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest();
    const { method, url, ip } = request;
    const userAgent = request.get('user-agent') || '';
    const userId = request.user?.sub || 'anonymous';

    const now = Date.now();

    return next.handle().pipe(
      tap({
        next: () => {
          const response = context.switchToHttp().getResponse();
          const { statusCode } = response;
          const duration = Date.now() - now;

          this.logger.log(
            `${method} ${url} ${statusCode} ${duration}ms - ${userId} - ${ip} - ${userAgent}`,
          );
        },
        error: (error) => {
          const duration = Date.now() - now;
          const statusCode = error.status || 500;

          this.logger.error(
            `${method} ${url} ${statusCode} ${duration}ms - ${userId} - ${ip} - ${error.message}`,
          );
        },
      }),
    );
  }
}

