  @ApiResponse({ status: 201, description: 'Mind map generated' })
  async generateMindMap(@CurrentUser() user: JwtPayload, @Body() dto: GenerateMindMapDto) {
    if (!dto.content || dto.content.trim().length < 50) {
      throw new BadRequestException('Content must be at least 50 characters long');
    }

    const prompt = `Based on this content, generate a mind map structure:

Title: ${dto.title}
Content: ${dto.content.substring(0, 5000)}

Create a hierarchical mind map with:
1. Central topic (main concept)
2. Main branches (3-6 key topics)
3. Sub-branches for each main branch (2-4 subtopics each)

Use different colors for visual distinction.

Return JSON:
{
  "centralTopic": {
    "id": "central",
    "label": "${dto.title}",
    "color": "#8b5cf6"
  },
  "branches": [
    {
      "id": "branch1",
      "label": "Key Topic 1",
      "color": "#10b981",
      "children": [
        {"id": "sub1", "label": "Subtopic", "color": "#34d399"}
      ]
    }
  ]
}`;

    const result = await this.aiService.completeJson<{
      centralTopic: { id: string; label: string; color: string };
      branches: Array<{
        id: string;
        label: string;
        color: string;
        children: Array<{ id: string; label: string; color: string }>;
      }>;
    }>([
      { role: 'system', content: 'Generate mind map structure as JSON.' },
      { role: 'user', content: prompt },
    ]);

    // Save to history if requested (default true)
    if (dto.saveToHistory !== false) {
      try {
        await this.aiService.saveMindMapToHistory({
          userId: user.sub,
          title: dto.title,
          content: dto.content.substring(0, 1000),
          mindMapData: result,
          studySetId: dto.studySetId,
          noteId: dto.noteId,
        });
      } catch (error) {
        // Log but don't fail the request
        this.logger.error('Failed to save mind map to history:', error);
      }
    }

    return result;
  }

  @Get('mind-maps')
  @ApiOperation({ summary: 'Get mind map history' })
  @ApiResponse({ status: 200, description: 'Mind map history' })
  async getMindMapHistory(@CurrentUser() user: JwtPayload) {
    return this.aiService.getMindMapHistory(user.sub);
  }

  @Get('mind-maps/:id')
  @ApiOperation({ summary: 'Get specific mind map by ID' })
  @ApiResponse({ status: 200, description: 'Mind map found' })
  async getMindMap(@CurrentUser() user: JwtPayload, @Param('id') id: string) {
    return this.aiService.getMindMapById(id, user.sub);
  }

  @Delete('mind-maps/:id')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiOperation({ summary: 'Delete mind map from history' })
  @ApiResponse({ status: 204, description: 'Mind map deleted' })
  async deleteMindMap(@CurrentUser() user: JwtPayload, @Param('id') id: string) {
    await this.aiService.deleteMindMap(id, user.sub);
  }

  @Post('generate-quiz')
  @ApiOperation({ summary: 'Generate quiz questions from content using AI' })
  @ApiResponse({ status: 201, description: 'Quiz generated' })
  async generateQuiz(
    @CurrentUser() user: JwtPayload,
    @Body()
    dto: { content: string; count?: number; type?: 'multiple_choice' | 'true_false' | 'mixed' },
  ): Promise<{
    questions: Array<{
      question: string;
      type: 'multiple_choice' | 'true_false';
      options: string[];
      correctAnswer: string;
      explanation: string;
    }>;
  }> {
    if (!dto.content || dto.content.trim().length < 50) {
      throw new BadRequestException('Content must be at least 50 characters long');
    }

    const count = Math.min(Math.max(dto.count || 10, 5), 30);
    const type = dto.type || 'mixed';

    const typeInstructions = {
      multiple_choice: 'All questions should be multiple choice with 4 options.',
      true_false: 'All questions should be true/false format.',
      mixed: 'Mix multiple choice (70%) and true/false (30%) questions.',
    };

    const systemPrompt = `You are an expert quiz creator. Generate ${count} quiz questions from the given content.

${typeInstructions[type]}

Rules:
1. Questions should test understanding, not just memorization
2. For multiple choice: provide exactly 4 options (A, B, C, D)
3. For true/false: provide options ["True", "False"]
4. Include a brief explanation for each correct answer
5. Vary difficulty levels

Output format: Return a JSON object with a "questions" array containing objects with:
- question: string
- type: "multiple_choice" or "true_false"
- options: array of strings
- correctAnswer: the correct option string
- explanation: brief explanation of the answer`;

    try {
      const result = await this.aiService.completeJson<{
        questions: Array<{
          question: string;
          type: 'multiple_choice' | 'true_false';
          options: string[];
          correctAnswer: string;
          explanation: string;
        }>;
      }>(
        [
          { role: 'system', content: systemPrompt },
          {
            role: 'user',
            content: `Generate quiz questions from this content:\n\n${dto.content.slice(0, 8000)}`,
          },
        ],
        { temperature: 0.7, maxTokens: 4000 },
      );

      return { questions: result.questions.slice(0, count) };
    } catch (error) {
      throw new BadRequestException('Failed to generate quiz. Please try again.');
    }
  }
}

import { Global, Module } from '@nestjs/common';
import { AiService } from './ai.service';
import { AiController } from './ai.controller';
import { EmbeddingService } from './embedding.service';

@Global()
@Module({
  controllers: [AiController],
  providers: [AiService, EmbeddingService],
  exports: [AiService, EmbeddingService],
})
export class AiModule {}

/**
 * AI Service
 *
 * Uses OpenRouter as the unified gateway for all LLM providers.
 * OpenRouter provides a single API compatible with OpenAI SDK
 * to access models from OpenAI, Anthropic, Google, DeepSeek, and more.
 */

import {
  Injectable,
  Logger,
  BadRequestException,
  OnModuleInit,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import OpenAI from 'openai';
import { DatabaseService } from '../database/database.service';
import { v4 as uuidv4 } from 'uuid';

// Default models
const DEFAULT_MODEL = 'openai/gpt-4o-mini';
const DEFAULT_VISION_MODEL = 'openai/gpt-4o';

export interface ChatMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export interface CompletionOptions {
  model?: string;
  temperature?: number;
  maxTokens?: number;
  topP?: number;
  stream?: boolean;
  responseFormat?: { type: 'json_object' | 'text' };
}

export interface CompletionResponse {
  content: string;
  model: string;
  usage: {
    promptTokens: number;
    completionTokens: number;
    totalTokens: number;
  };
}

export interface TranscriptionResponse {
  text: string;
  duration?: number;
  language?: string;
}

@Injectable()
export class AiService implements OnModuleInit {
  private readonly logger = new Logger(AiService.name);

  // OpenRouter client (PRIMARY gateway for all models)
  private openRouterClient: OpenAI | null = null;

  // Direct OpenAI client (fallback only)
  private openaiClient: OpenAI | null = null;

  constructor(
    private readonly configService: ConfigService,
    private readonly db: DatabaseService,
  ) {}

  async onModuleInit() {
    await this.initializeClients();
  }

  private async initializeClients() {
    // Initialize OpenRouter (PRIMARY gateway for all models)
    const openRouterKey = this.configService.get<string>('OPENROUTER_API_KEY');

    if (openRouterKey && !openRouterKey.includes('your-')) {
      this.openRouterClient = new OpenAI({
        apiKey: openRouterKey,
        baseURL: 'https://openrouter.ai/api/v1',
        defaultHeaders: {
          'HTTP-Referer': this.configService.get<string>('FRONTEND_URL', 'http://localhost:5189'),
          'X-Title': 'Studyield',
        },
        timeout: 120000,
      });
      this.logger.log('OpenRouter client initialized (unified gateway for all models)');
    }

    // Initialize direct OpenAI (FALLBACK only for OpenAI models)
    const openaiKey = this.configService.get<string>('OPENAI_API_KEY');
    if (openaiKey && !openaiKey.includes('your-')) {
      this.openaiClient = new OpenAI({
        apiKey: openaiKey,
        timeout: 120000,
      });
      this.logger.log('OpenAI direct client initialized (fallback)');
    }

    // Log status
    if (!this.openRouterClient && !this.openaiClient) {
      this.logger.warn('No AI clients available! Set OPENROUTER_API_KEY or OPENAI_API_KEY in .env');
    }
  }

  private getClient(): OpenAI {
    // Primary: Use OpenRouter for everything (unified gateway)
    if (this.openRouterClient) {
      return this.openRouterClient;
    }

    // Fallback: Direct OpenAI
    if (this.openaiClient) {
      return this.openaiClient;
    }

    throw new BadRequestException(
      'No AI API key configured. Set OPENROUTER_API_KEY or OPENAI_API_KEY in .env file.',
    );
  }

  private getModel(type: 'text' | 'vision' = 'text'): string {
    // When using OpenRouter, use provider/model format
    if (this.openRouterClient) {
      return type === 'vision'
        ? this.configService.get('OPENROUTER_VISION_MODEL', DEFAULT_VISION_MODEL)
        : this.configService.get('OPENROUTER_DEFAULT_MODEL', DEFAULT_MODEL);
    }

    // Direct OpenAI - use model name without provider prefix
    return type === 'vision'
      ? this.configService.get('OPENAI_VISION_MODEL', 'gpt-4o')
      : this.configService.get('OPENAI_MODEL', 'gpt-4o-mini');
  }

  async complete(
    messages: ChatMessage[],
    options: CompletionOptions = {},
  ): Promise<CompletionResponse> {
    const client = this.getClient();
    const model = options.model || this.getModel('text');

    try {
      const response = await client.chat.completions.create({
        model,
        messages,
        temperature: options.temperature ?? 0.7,
        max_tokens: options.maxTokens ?? 2048,
        top_p: options.topP ?? 1,
        ...(options.responseFormat && { response_format: options.responseFormat }),
      });

      const choice = response.choices[0];

      return {
        content: choice.message.content || '',
        model: response.model,
        usage: {
          promptTokens: response.usage?.prompt_tokens || 0,
          completionTokens: response.usage?.completion_tokens || 0,
          totalTokens: response.usage?.total_tokens || 0,
        },
      };
    } catch (error: unknown) {
      const err = error as Error;
      this.logger.error(`AI completion failed: ${err.message}`);

      // Try fallback to direct OpenAI if OpenRouter fails
      if (this.openRouterClient && this.openaiClient) {
        this.logger.warn('Attempting fallback to direct OpenAI...');
        return this.completeFallback(messages, options);
      }

      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      throw new BadRequestException(`AI completion failed: ${errorMessage}`);
    }
  }

  private async completeFallback(
    messages: ChatMessage[],
    options: CompletionOptions = {},
  ): Promise<CompletionResponse> {
    if (!this.openaiClient) {
      throw new BadRequestException('No fallback client available');
    }

    const model = options.model?.replace(/^[^/]+\//, '') || 'gpt-4o-mini';

    const response = await this.openaiClient.chat.completions.create({
      model,
      messages,
      temperature: options.temperature ?? 0.7,
      max_tokens: options.maxTokens ?? 2048,
      top_p: options.topP ?? 1,
      ...(options.responseFormat && { response_format: options.responseFormat }),
    });

    const choice = response.choices[0];

    return {
      content: choice.message.content || '',
      model: response.model,
      usage: {
        promptTokens: response.usage?.prompt_tokens || 0,
        completionTokens: response.usage?.completion_tokens || 0,
        totalTokens: response.usage?.total_tokens || 0,
      },
    };
  }

  async generateWithVision(params: {
    prompt: string;
    imageData: string;
    mimeType: string;
    temperature?: number;
    maxTokens?: number;
  }): Promise<string> {
    try {
      const client = this.getClient();
      const model = this.getModel('vision');

      const response = await client.chat.completions.create({
        model,
        messages: [
          {
            role: 'user',
            content: [
              {
                type: 'text',
                text: params.prompt,
              },
              {
                type: 'image_url',
                image_url: {
                  url: `data:${params.mimeType};base64,${params.imageData}`,
                },
              },
            ],
          },
        ],
        temperature: params.temperature ?? 0.3, // Low temperature for accuracy
        max_tokens: params.maxTokens ?? 1000,
      });

      return response.choices[0]?.message?.content || '';
    } catch (error) {
      this.logger.error('Vision generation failed', error);
      throw new BadRequestException(`Vision AI failed: ${error.message}`);
    }
  }

  async completeJson<T>(messages: ChatMessage[], options: CompletionOptions = {}): Promise<T> {
    const response = await this.complete(messages, {
      ...options,
      responseFormat: { type: 'json_object' },
    });

    try {
      // Clean up response if it has markdown code blocks
      let content = response.content.trim();
      if (content.startsWith('```json')) content = content.slice(7);
      else if (content.startsWith('```')) content = content.slice(3);
      if (content.endsWith('```')) content = content.slice(0, -3);

      return JSON.parse(content.trim()) as T;
    } catch (error) {
      this.logger.error(`Failed to parse JSON response: ${response.content}`);
      throw new BadRequestException('Failed to parse AI response as JSON');
    }
  }

  async *streamComplete(
    messages: ChatMessage[],
    options: CompletionOptions = {},
  ): AsyncGenerator<{ content: string; done: boolean }> {
    const client = this.getClient();
    const model = options.model || this.getModel('text');

    const stream = await client.chat.completions.create({
      model,
      messages,
      temperature: options.temperature ?? 0.7,
      max_tokens: options.maxTokens ?? 2048,
      stream: true,
    });

    for await (const chunk of stream) {
      const content = chunk.choices[0]?.delta?.content || '';
      const done = chunk.choices[0]?.finish_reason === 'stop';
      yield { content, done };
    }
  }

  buildSystemPrompt(template: string, variables: Record<string, string>): string {
    let prompt = template;
    for (const [key, value] of Object.entries(variables)) {
      prompt = prompt.replace(new RegExp(`{{${key}}}`, 'g'), value);
    }
    return prompt;
  }

  async generateWithRetry(
    messages: ChatMessage[],
    options: CompletionOptions = {},
    maxRetries = 3,
  ): Promise<CompletionResponse> {
    let lastError: Error | null = null;

    for (let i = 0; i < maxRetries; i++) {
      try {
        return await this.complete(messages, options);
      } catch (error) {
        lastError = error as Error;
        this.logger.warn(`AI completion attempt ${i + 1} failed, retrying...`);
        await new Promise((resolve) => setTimeout(resolve, 1000 * (i + 1)));
      }
    }

    throw lastError;
  }

  estimateTokens(text: string): number {
    return Math.ceil(text.length / 4);
  }

  /**
   * Transcribe audio using OpenAI Whisper API
   * Note: Whisper requires direct OpenAI client (not available via OpenRouter)
   */
  async transcribeAudio(
    audioBuffer: Buffer,
    filename: string,
    mimeType: string,
  ): Promise<TranscriptionResponse> {
    if (!this.openaiClient) {
      throw new BadRequestException(
        'Audio transcription requires OpenAI API key. Set OPENAI_API_KEY in .env file.',
      );
    }

    try {
      // Use OpenAI SDK's toFile helper which handles Buffer properly
      const file = await OpenAI.toFile(audioBuffer, filename, { type: mimeType });

      const response = await this.openaiClient.audio.transcriptions.create({
        file,
        model: 'whisper-1',
        response_format: 'verbose_json',
      });

      return {
        text: response.text,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        duration: (response as any).duration,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        language: (response as any).language,
      };
    } catch (error: unknown) {
      const err = error as Error;
      this.logger.error(`Audio transcription failed: ${err.message}`);
      throw new BadRequestException(`Audio transcription failed: ${err.message}`);
    }
  }

  isAvailable(): boolean {
    return this.openRouterClient !== null || this.openaiClient !== null;
  }

  getAvailableProviders(): string[] {
    const providers: string[] = [];
    if (this.openRouterClient) {
      providers.push('openrouter', 'openai', 'anthropic', 'google', 'deepseek');
    } else if (this.openaiClient) {
      providers.push('openai');
    }
    return providers;
  }

  // ═══════════════════════════════════════════
  // Mind Map History
  // ═══════════════════════════════════════════

  async saveMindMapToHistory(params: {
    userId: string;
    title: string;
    content: string;
    mindMapData: unknown;
    studySetId?: string;
    noteId?: string;
  }) {
    const id = uuidv4();

    await this.db.query(
      `INSERT INTO mind_maps (id, user_id, study_set_id, note_id, title, content_snapshot, mind_map_data, created_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, NOW())`,
      [
        id,
        params.userId,
        params.studySetId || null,
        params.noteId || null,
        params.title,
        params.content,
        JSON.stringify(params.mindMapData),
      ],
    );

    this.logger.log(`Mind map saved to history: ${id}`);
    return { id };
  }

  async getMindMapHistory(userId: string) {
    const results = await this.db.queryMany(
      `SELECT id, title, study_set_id, note_id, created_at
       FROM mind_maps
       WHERE user_id = $1
       ORDER BY created_at DESC
       LIMIT 50`,
      [userId],
    );

    return results.map((r) => ({
      id: (r as { id: string }).id,
      title: (r as { title: string }).title,
      studySetId: (r as { study_set_id: string | null }).study_set_id,
      noteId: (r as { note_id: string | null }).note_id,
      createdAt: (r as { created_at: Date }).created_at,
    }));
  }

  async getMindMapById(id: string, userId: string) {
    const result = await this.db.queryOne(`SELECT * FROM mind_maps WHERE id = $1`, [id]);

    if (!result) {
      throw new NotFoundException('Mind map not found');
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const r = result as any;
    if (r.user_id !== userId) {
      throw new ForbiddenException('Access denied');
    }

    return {
      id: r.id,
      title: r.title,
      contentSnapshot: r.content_snapshot,
      mindMapData:
        typeof r.mind_map_data === 'string' ? JSON.parse(r.mind_map_data) : r.mind_map_data,
      studySetId: r.study_set_id,
      noteId: r.note_id,
      createdAt: r.created_at,
    };
  }

  async deleteMindMap(id: string, userId: string) {
    const result = await this.db.queryOne(
      `DELETE FROM mind_maps WHERE id = $1 AND user_id = $2 RETURNING id`,
      [id, userId],
    );

    if (!result) {
      throw new NotFoundException('Mind map not found or access denied');
    }

    this.logger.log(`Mind map deleted: ${id}`);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

export interface EmbeddingResult {
  vector: number[];
  tokens: number;
}

@Injectable()
export class EmbeddingService {
  private readonly logger = new Logger(EmbeddingService.name);
  private readonly apiKey: string;
  private readonly baseUrl: string;
  private readonly embeddingModel: string;
  private readonly vectorDimension: number;

  constructor(private readonly configService: ConfigService) {
    this.apiKey = this.configService.get<string>('OPENROUTER_API_KEY', '');
    this.baseUrl = this.configService.get<string>(
      'OPENROUTER_BASE_URL',
      'https://openrouter.ai/api/v1',
    );
    this.embeddingModel = this.configService.get<string>(
      'OPENROUTER_EMBEDDING_MODEL',
      'openai/text-embedding-3-small',
    );
    this.vectorDimension = 1536;
  }

  getVectorDimension(): number {
    return this.vectorDimension;
  }

  async embed(text: string): Promise<EmbeddingResult> {
    const response = await fetch(`${this.baseUrl}/embeddings`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${this.apiKey}`,
        'Content-Type': 'application/json',
        'HTTP-Referer': 'https://studyield.com',
        'X-Title': 'Studyield',
      },
      body: JSON.stringify({
        model: this.embeddingModel,
        input: text,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      this.logger.error(`Embedding failed: ${error}`);
      throw new Error(`Embedding failed: ${response.status}`);
    }

    const data = await response.json();

    return {
      vector: data.data[0].embedding,
      tokens: data.usage?.total_tokens || 0,
    };
  }

  async embedBatch(texts: string[]): Promise<EmbeddingResult[]> {
    if (texts.length === 0) return [];

    const response = await fetch(`${this.baseUrl}/embeddings`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${this.apiKey}`,
        'Content-Type': 'application/json',
        'HTTP-Referer': 'https://studyield.com',
        'X-Title': 'Studyield',
      },
      body: JSON.stringify({
        model: this.embeddingModel,
        input: texts,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      this.logger.error(`Batch embedding failed: ${error}`);
      throw new Error(`Batch embedding failed: ${response.status}`);
    }

    const data = await response.json();
    const tokensPerText = Math.ceil((data.usage?.total_tokens || 0) / texts.length);

    return data.data.map((item: { embedding: number[] }) => ({
      vector: item.embedding,
      tokens: tokensPerText,
    }));
  }

  async embedWithChunking(texts: string[], batchSize = 100): Promise<EmbeddingResult[]> {
    const results: EmbeddingResult[] = [];

    for (let i = 0; i < texts.length; i += batchSize) {
      const batch = texts.slice(i, i + batchSize);
      const batchResults = await this.embedBatch(batch);
      results.push(...batchResults);

      this.logger.debug(
        `Embedded batch ${Math.floor(i / batchSize) + 1}/${Math.ceil(texts.length / batchSize)}`,
      );
    }

    return results;
  }

  cosineSimilarity(a: number[], b: number[]): number {
    if (a.length !== b.length) {
      throw new Error('Vectors must have the same dimension');
    }

    let dotProduct = 0;
    let normA = 0;
    let normB = 0;

    for (let i = 0; i < a.length; i++) {
      dotProduct += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }

    return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
  }

  async findMostSimilar(
    query: string,
    candidates: Array<{ id: string; text: string }>,
    topK = 5,
  ): Promise<Array<{ id: string; text: string; similarity: number }>> {
    const queryEmbedding = await this.embed(query);
    const candidateEmbeddings = await this.embedBatch(candidates.map((c) => c.text));

    const results = candidates.map((candidate, index) => ({
      id: candidate.id,
      text: candidate.text,
      similarity: this.cosineSimilarity(queryEmbedding.vector, candidateEmbeddings[index].vector),
    }));

    return results.sort((a, b) => b.similarity - a.similarity).slice(0, topK);
  }
}

export * from './ai.module';
export * from './ai.service';
export * from './embedding.service';

import { Controller, Get, Post, Body, UseGuards } from '@nestjs/common';
import { ApiTags, ApiOperation, ApiBearerAuth } from '@nestjs/swagger';
import { AnalyticsService } from './analytics.service';
import { JwtAuthGuard } from '../../common/guards/jwt-auth.guard';
import { CurrentUser, JwtPayload, Public, PlanFeature } from '../../common';

@ApiTags('Analytics')
@Controller('analytics')
@UseGuards(JwtAuthGuard)
@ApiBearerAuth()
export class AnalyticsController {
  constructor(private readonly analyticsService: AnalyticsService) {}

  @Get('me')
  @PlanFeature('advanced_analytics') // Removed for development testing
  @ApiOperation({ summary: 'Get user analytics' })
  async getUserAnalytics(@CurrentUser() user: JwtPayload) {
    return this.analyticsService.getUserAnalytics(user.sub);
  }

  @Get('me/activity')
  // @PlanFeature('advanced_analytics') // Removed for development testing
