import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  UseGuards,
  UseInterceptors,
  UploadedFile,
  HttpCode,
  HttpStatus,
  BadRequestException,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import {
  ApiTags,
  ApiOperation,
  ApiResponse,
  ApiBearerAuth,
  ApiConsumes,
  ApiBody,
} from '@nestjs/swagger';
import { DocumentsService, UpdateDocumentDto } from './documents.service';
import { StorageService } from '../storage/storage.service';
import { JwtAuthGuard } from '../../common/guards/jwt-auth.guard';
import { CurrentUser, JwtPayload } from '../../common';
import { PaginationDto, PaginatedResponseDto } from '../../common/dto/pagination.dto';
import { SubscriptionService } from '../subscription/subscription.service';

const ALLOWED_MIME_TYPES = [
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'text/plain',
  'text/markdown',
  'image/png',
  'image/jpeg',
];

const MAX_FILE_SIZE_FREE = 10 * 1024 * 1024; // 10MB
const MAX_FILE_SIZE_PRO = 100 * 1024 * 1024; // 100MB

@ApiTags('Documents')
@Controller('documents')
@UseGuards(JwtAuthGuard)
@ApiBearerAuth()
export class DocumentsController {
  constructor(
    private readonly documentsService: DocumentsService,
    private readonly storageService: StorageService,
    private readonly subscriptionService: SubscriptionService,
  ) {}

  @Post()
  @ApiOperation({ summary: 'Upload a new document' })
  @ApiConsumes('multipart/form-data')
  @ApiBody({
    schema: {
      type: 'object',
      properties: {
        file: { type: 'string', format: 'binary' },
        studySetId: { type: 'string' },
        title: { type: 'string' },
      },
    },
  })
  @ApiResponse({ status: 201, description: 'Document uploaded' })
  @UseInterceptors(FileInterceptor('file'))
  async upload(
    @CurrentUser() user: JwtPayload,
    @UploadedFile() file: Express.Multer.File,
    @Body('studySetId') studySetId: string,
    @Body('title') title?: string,
  ) {
    if (!file) {
      throw new BadRequestException('File is required');
    }

    if (!ALLOWED_MIME_TYPES.includes(file.mimetype)) {
      throw new BadRequestException('File type not allowed');
    }

    const isPro = await this.subscriptionService.isPro(user.sub);
    const maxSize = isPro ? MAX_FILE_SIZE_PRO : MAX_FILE_SIZE_FREE;
    if (file.size > maxSize) {
      throw new BadRequestException(
        isPro
          ? 'File size exceeds 100MB limit'
          : 'Free plan allows up to 10MB per file. Upgrade to Pro for 100MB uploads.',
      );
    }

    // Check storage quota
    await this.subscriptionService.checkStorageQuota(user.sub, file.size);

    const { url } = await this.storageService.upload(file.buffer, file.originalname, {
      contentType: file.mimetype,
      folder: `documents/${user.sub}`,
    });

    return this.documentsService.create(user.sub, {
      studySetId,
      title: title || file.originalname,
      fileName: file.originalname,
      fileUrl: url,
      fileSize: file.size,
      mimeType: file.mimetype,
    });
  }

  @Get()
  @ApiOperation({ summary: 'Get user documents' })
  @ApiResponse({ status: 200, description: 'Documents list' })
  async findMine(@CurrentUser() user: JwtPayload, @Query() pagination: PaginationDto) {
    const { data, total } = await this.documentsService.findByUser(
      user.sub,
      pagination.page,
      pagination.limit,
    );
    return new PaginatedResponseDto(data, total, pagination.page || 1, pagination.limit || 20);
  }

  @Get('study-set/:studySetId')
  @ApiOperation({ summary: 'Get documents by study set' })
  @ApiResponse({ status: 200, description: 'Documents list' })
  async findByStudySet(@Param('studySetId') studySetId: string) {
    return this.documentsService.findByStudySet(studySetId);
  }

  @Get(':id')
  @ApiOperation({ summary: 'Get document by ID' })
  @ApiResponse({ status: 200, description: 'Document' })
  @ApiResponse({ status: 404, description: 'Document not found' })
  async findOne(@CurrentUser() user: JwtPayload, @Param('id') id: string) {
    return this.documentsService.findByIdWithAccess(id, user.sub);
  }

  @Get(':id/download-url')
  @ApiOperation({ summary: 'Get signed download URL' })
  @ApiResponse({ status: 200, description: 'Download URL' })
  async getDownloadUrl(@CurrentUser() user: JwtPayload, @Param('id') id: string) {
    const url = await this.documentsService.getDownloadUrl(id, user.sub);
    return { url };
  }

  @Put(':id')
  @ApiOperation({ summary: 'Update document' })
  @ApiResponse({ status: 200, description: 'Document updated' })
  async update(
    @CurrentUser() user: JwtPayload,
    @Param('id') id: string,
    @Body() dto: UpdateDocumentDto,
  ) {
    return this.documentsService.update(id, user.sub, dto);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiOperation({ summary: 'Delete document' })
  @ApiResponse({ status: 204, description: 'Document deleted' })
  async delete(@CurrentUser() user: JwtPayload, @Param('id') id: string) {
    await this.documentsService.delete(id, user.sub);
  }
}

import { Injectable, Logger, NotFoundException, ForbiddenException } from '@nestjs/common';
import { v4 as uuidv4 } from 'uuid';
import { DatabaseService } from '../database/database.service';
import { StorageService } from '../storage/storage.service';

export interface Document {
  id: string;
  studySetId: string;
  userId: string;
  title: string;
  fileName: string;
  fileUrl: string;
  fileSize: number;
  mimeType: string;
  pageCount: number | null;
  extractedText: string | null;
  processingStatus: 'pending' | 'processing' | 'completed' | 'failed';
  createdAt: Date;
  updatedAt: Date;
}

export interface CreateDocumentDto {
  studySetId: string;
  title: string;
  fileName: string;
  fileUrl: string;
  fileSize: number;
  mimeType: string;
}

export interface UpdateDocumentDto {
  title?: string;
  extractedText?: string;
  pageCount?: number;
  processingStatus?: 'pending' | 'processing' | 'completed' | 'failed';
}

@Injectable()
export class DocumentsService {
  private readonly logger = new Logger(DocumentsService.name);

  constructor(
    private readonly db: DatabaseService,
    private readonly storageService: StorageService,
  ) {}

  async create(userId: string, dto: CreateDocumentDto): Promise<Document> {
    const id = uuidv4();
    const now = new Date();

    const result = await this.db.queryOne<Document>(
      `INSERT INTO documents (id, study_set_id, user_id, title, file_name, file_url, file_size, mime_type, processing_status, created_at, updated_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'pending', $9, $10)
       RETURNING *`,
      [
        id,
        dto.studySetId,
        userId,
        dto.title,
        dto.fileName,
        dto.fileUrl,
        dto.fileSize,
        dto.mimeType,
        now,
        now,
      ],
    );

    this.logger.log(`Document created: ${id}`);
    return this.mapDocument(result!);
  }

  async findById(id: string): Promise<Document | null> {
    const result = await this.db.queryOne<Document>('SELECT * FROM documents WHERE id = $1', [id]);
    return result ? this.mapDocument(result) : null;
  }

  async findByIdWithAccess(id: string, userId: string): Promise<Document> {
    const document = await this.findById(id);
    if (!document) {
      throw new NotFoundException('Document not found');
    }
    if (document.userId !== userId) {
      throw new ForbiddenException('Access denied');
    }
    return document;
  }

  async findByStudySet(studySetId: string): Promise<Document[]> {
    const results = await this.db.queryMany<Document>(
      'SELECT * FROM documents WHERE study_set_id = $1 ORDER BY created_at DESC',
      [studySetId],
    );
    return results.map((r) => this.mapDocument(r));
  }

  async findByUser(
    userId: string,
    page = 1,
    limit = 20,
  ): Promise<{ data: Document[]; total: number }> {
    const offset = (page - 1) * limit;

    const [results, countResult] = await Promise.all([
      this.db.queryMany<Document>(
        `SELECT * FROM documents WHERE user_id = $1 ORDER BY created_at DESC LIMIT $2 OFFSET $3`,
        [userId, limit, offset],
      ),
      this.db.queryOne<{ count: string }>(
        'SELECT COUNT(*) as count FROM documents WHERE user_id = $1',
        [userId],
      ),
    ]);

    return {
      data: results.map((r) => this.mapDocument(r)),
      total: parseInt(countResult?.count || '0', 10),
    };
  }

  async update(id: string, userId: string, dto: UpdateDocumentDto): Promise<Document> {
    await this.findByIdWithAccess(id, userId);

    const updates: string[] = [];
    const values: unknown[] = [];
    let paramIndex = 1;

    if (dto.title !== undefined) {
      updates.push(`title = $${paramIndex++}`);
      values.push(dto.title);
    }
    if (dto.extractedText !== undefined) {
      updates.push(`extracted_text = $${paramIndex++}`);
      values.push(dto.extractedText);
    }
    if (dto.pageCount !== undefined) {
      updates.push(`page_count = $${paramIndex++}`);
      values.push(dto.pageCount);
    }
    if (dto.processingStatus !== undefined) {
      updates.push(`processing_status = $${paramIndex++}`);
      values.push(dto.processingStatus);
    }

    updates.push(`updated_at = $${paramIndex++}`);
    values.push(new Date());
    values.push(id);

    const result = await this.db.queryOne<Document>(
      `UPDATE documents SET ${updates.join(', ')} WHERE id = $${paramIndex} RETURNING *`,
      values,
    );

    return this.mapDocument(result!);
  }

  async updateProcessingStatus(
    id: string,
    status: 'pending' | 'processing' | 'completed' | 'failed',
    extractedText?: string,
    pageCount?: number,
  ): Promise<void> {
    const updates = ['processing_status = $1', 'updated_at = $2'];
    const values: unknown[] = [status, new Date()];
    let paramIndex = 3;

    if (extractedText !== undefined) {
      updates.push(`extracted_text = $${paramIndex++}`);
      values.push(extractedText);
    }
    if (pageCount !== undefined) {
      updates.push(`page_count = $${paramIndex++}`);
      values.push(pageCount);
    }

    values.push(id);

    await this.db.query(
      `UPDATE documents SET ${updates.join(', ')} WHERE id = $${paramIndex}`,
      values,
    );
  }

  async delete(id: string, userId: string): Promise<void> {
    const document = await this.findByIdWithAccess(id, userId);

    try {
      const key = document.fileUrl.split('/').pop();
      if (key) {
        await this.storageService.delete(key);
      }
    } catch (error) {
      this.logger.warn(`Failed to delete file from storage: ${error}`);
    }

    await this.db.query('DELETE FROM documents WHERE id = $1', [id]);
    this.logger.log(`Document deleted: ${id}`);
  }

  async getDownloadUrl(id: string, userId: string): Promise<string> {
    const document = await this.findByIdWithAccess(id, userId);
    const key = document.fileUrl.split('/').pop();
    if (!key) {
      throw new Error('Invalid file URL');
    }
    return this.storageService.getSignedDownloadUrl(key);
  }

  private mapDocument(row: unknown): Document {
    const r = row as Record<string, unknown>;
    return {
      id: r.id as string,
      studySetId: r.study_set_id as string,
      userId: r.user_id as string,
      title: r.title as string,
      fileName: r.file_name as string,
      fileUrl: r.file_url as string,
      fileSize: r.file_size as number,
      mimeType: r.mime_type as string,
      pageCount: r.page_count as number | null,
      extractedText: r.extracted_text as string | null,
      processingStatus: r.processing_status as Document['processingStatus'],
      createdAt: new Date(r.created_at as string),
      updatedAt: new Date(r.updated_at as string),
    };
  }
}

import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  UseGuards,
