  userId?: string;
  metadata?: Record<string, unknown>;
}

export interface EmailLog {
  id: string;
  userId?: string;
  to: string[];
  cc?: string[];
  bcc?: string[];
  from: string;
  subject: string;
  status: 'sent' | 'failed' | 'pending';
  messageId?: string;
  error?: string;
  sentAt?: Date;
  createdAt: Date;
  metadata?: Record<string, unknown>;
}

export interface EmailTemplate {
