@Injectable()
export class EmailService {
  private readonly logger = new Logger(EmailService.name);
  private readonly appUrl: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly sesService: SESService,
    private readonly db: DatabaseService,
  ) {
    this.appUrl = this.configService.get<string>('APP_URL', 'http://localhost:3000');
  }

  async sendEmail(
    options: EmailOptions,
  ): Promise<{ success: boolean; messageId?: string; error?: string }> {
    try {
      const { userId, metadata, ...emailOptions } = options;

      const to = Array.isArray(emailOptions.to) ? emailOptions.to : [emailOptions.to];
      const cc = emailOptions.cc
        ? Array.isArray(emailOptions.cc)
          ? emailOptions.cc
          : [emailOptions.cc]
        : undefined;
      const bcc = emailOptions.bcc
        ? Array.isArray(emailOptions.bcc)
          ? emailOptions.bcc
          : [emailOptions.bcc]
        : undefined;

      const result = await this.sesService.sendEmail({
        from: emailOptions.from,
        to,
        cc,
        bcc,
        subject: emailOptions.subject,
        text: emailOptions.text,
        html: emailOptions.html,
      });

      await this.logEmail({
        userId,
        to,
        cc,
        bcc,
        from:
          emailOptions.from ||
          this.configService.get('EMAIL_DEFAULT_FROM', 'noreply@studyield.com'),
        subject: emailOptions.subject,
        status: result.status,
        messageId: result.messageId,
        error: result.error,
        sentAt: result.status === 'sent' ? new Date() : undefined,
        metadata,
      });

      return {
        success: result.status === 'sent',
        messageId: result.messageId,
        error: result.error,
      };
    } catch (error) {
      this.logger.error(
        `Failed to send email: ${(error as Error).message}`,
        (error as Error).stack,
      );

      await this.logEmail({
        userId: options.userId,
        to: Array.isArray(options.to) ? options.to : [options.to],
        from: options.from || this.configService.get('EMAIL_DEFAULT_FROM', 'noreply@studyield.com'),
        subject: options.subject,
        status: 'failed',
        error: (error as Error).message,
        metadata: options.metadata,
      });

      throw error;
    }
  }

  async sendSimpleEmail(
    to: string | string[],
    subject: string,
    content: { text?: string; html?: string },
    options?: {
      from?: string;
      cc?: string | string[];
      bcc?: string | string[];
      userId?: string;
    },
  ) {
    return this.sendEmail({
      to,
      subject,
      text: content.text,
      html: content.html,
      from: options?.from,
      cc: options?.cc,
      bcc: options?.bcc,
      userId: options?.userId,
    });
  }

