    @CurrentUser() user: JwtPayload,
    @Param('questionId') questionId: string,
    @Body() dto: { note?: string },
  ) {
    await this.examCloneService.bookmarkQuestion(user.sub, questionId, dto.note);
    return { success: true };
  }

  @Delete('bookmarks/:questionId')
