import { Module } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
import { FirebaseService } from './firebase.service';

@Module({
  imports: [ConfigModule],
  providers: [FirebaseService],
  exports: [FirebaseService],
})
export class FirebaseModule {}

import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import * as admin from 'firebase-admin';

@Injectable()
export class FirebaseService implements OnModuleInit {
  private readonly logger = new Logger(FirebaseService.name);

  constructor(private readonly configService: ConfigService) {}

  onModuleInit() {
    try {
      const projectId = this.configService.get<string>('FIREBASE_PROJECT_ID');
      const privateKey = this.configService
        .get<string>('FIREBASE_PRIVATE_KEY')
        ?.replace(/\\n/g, '\n'); // Replace escaped newlines
      const clientEmail = this.configService.get<string>('FIREBASE_CLIENT_EMAIL');

      if (!projectId || !privateKey || !clientEmail) {
        this.logger.warn('Firebase credentials not configured. Push notifications will not work.');
        return;
      }

      admin.initializeApp({
        credential: admin.credential.cert({
          projectId,
          privateKey,
          clientEmail,
        }),
      });

      this.logger.log('✅ Firebase Admin SDK initialized');
    } catch (error) {
      this.logger.error('❌ Failed to initialize Firebase Admin SDK', error);
    }
  }

  /**
   * Send push notification to a single device
   */
  async sendToDevice(
    fcmToken: string,
    title: string,
    body: string,
    data?: Record<string, string>,
  ): Promise<boolean> {
    try {
      const message: admin.messaging.Message = {
        token: fcmToken,
        notification: {
          title,
          body,
        },
        data: data || {},
        android: {
          priority: 'high',
          notification: {
            sound: 'default',
            channelId: 'default',
          },
        },
        apns: {
          payload: {
            aps: {
              sound: 'default',
              badge: 1,
            },
          },
        },
      };

      const response = await admin.messaging().send(message);
      this.logger.debug(`✅ Push notification sent: ${response}`);
      return true;
    } catch (error) {
      this.logger.error(`❌ Failed to send push notification: ${error.message}`);
      return false;
    }
  }

  /**
   * Send push notification to multiple devices
   */
  async sendToMultipleDevices(
    fcmTokens: string[],
    title: string,
    body: string,
    data?: Record<string, string>,
  ): Promise<number> {
    try {
      const message: admin.messaging.MulticastMessage = {
        tokens: fcmTokens,
        notification: {
          title,
          body,
        },
        data: data || {},
        android: {
          priority: 'high',
          notification: {
            sound: 'default',
            channelId: 'default',
          },
        },
        apns: {
          payload: {
            aps: {
              sound: 'default',
              badge: 1,
            },
          },
        },
      };

      const response = await admin.messaging().sendEachForMulticast(message);
      this.logger.debug(`✅ Sent ${response.successCount}/${fcmTokens.length} push notifications`);
      return response.successCount;
    } catch (error) {
      this.logger.error(`❌ Failed to send multicast push notification: ${error.message}`);
      return 0;
    }
  }

  /**
   * Send push notification to a topic
   */
  async sendToTopic(
    topic: string,
    title: string,
    body: string,
    data?: Record<string, string>,
  ): Promise<boolean> {
    try {
      const message: admin.messaging.Message = {
        topic,
        notification: {
          title,
          body,
        },
        data: data || {},
        android: {
          priority: 'high',
        },
      };

      const response = await admin.messaging().send(message);
      this.logger.debug(`✅ Push notification sent to topic ${topic}: ${response}`);
      return true;
    } catch (error) {
      this.logger.error(`❌ Failed to send push notification to topic: ${error.message}`);
      return false;
    }
  }

  /**
   * Subscribe device to topic
   */
  async subscribeToTopic(fcmTokens: string[], topic: string): Promise<boolean> {
    try {
      await admin.messaging().subscribeToTopic(fcmTokens, topic);
      this.logger.debug(`✅ Subscribed ${fcmTokens.length} devices to topic: ${topic}`);
      return true;
    } catch (error) {
      this.logger.error(`❌ Failed to subscribe to topic: ${error.message}`);
      return false;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';

export interface TextChunk {
  content: string;
  index: number;
  startOffset: number;
  endOffset: number;
  metadata?: Record<string, unknown>;
}

export interface ChunkingOptions {
  chunkSize?: number;
  chunkOverlap?: number;
  separator?: string;
  preserveParagraphs?: boolean;
}

@Injectable()
export class ChunkingService {
  private readonly logger = new Logger(ChunkingService.name);

  chunk(text: string, options: ChunkingOptions = {}): TextChunk[] {
    const {
      chunkSize = 1000,
      chunkOverlap = 200,
      separator = '\n\n',
      preserveParagraphs = true,
    } = options;

    if (!text || text.trim().length === 0) {
      return [];
    }

    const chunks: TextChunk[] = [];

    if (preserveParagraphs) {
      const paragraphs = text.split(separator).filter((p) => p.trim().length > 0);
      let currentChunk = '';
      let currentStartOffset = 0;
      let chunkIndex = 0;
      let offset = 0;

      for (const paragraph of paragraphs) {
        const trimmedParagraph = paragraph.trim();

        if (currentChunk.length + trimmedParagraph.length + separator.length > chunkSize) {
          if (currentChunk.length > 0) {
            chunks.push({
              content: currentChunk.trim(),
              index: chunkIndex++,
              startOffset: currentStartOffset,
              endOffset: offset - separator.length,
            });

            const overlapStart = Math.max(0, currentChunk.length - chunkOverlap);
            currentChunk = currentChunk.substring(overlapStart);
            currentStartOffset = offset - currentChunk.length;
          }
        }

        if (trimmedParagraph.length > chunkSize) {
          const sentenceChunks = this.chunkBySentences(trimmedParagraph, chunkSize, chunkOverlap);
          for (const sentenceChunk of sentenceChunks) {
            chunks.push({
              content: sentenceChunk.content,
              index: chunkIndex++,
              startOffset: offset + sentenceChunk.startOffset,
              endOffset: offset + sentenceChunk.endOffset,
            });
          }
          offset += trimmedParagraph.length + separator.length;
          currentChunk = '';
          currentStartOffset = offset;
        } else {
          currentChunk += (currentChunk.length > 0 ? separator : '') + trimmedParagraph;
          offset += trimmedParagraph.length + separator.length;
        }
      }

      if (currentChunk.trim().length > 0) {
        chunks.push({
          content: currentChunk.trim(),
          index: chunkIndex,
          startOffset: currentStartOffset,
          endOffset: offset,
        });
      }
    } else {
      return this.chunkBySize(text, chunkSize, chunkOverlap);
    }

    this.logger.debug(`Text chunked into ${chunks.length} chunks`);
    return chunks;
  }

  private chunkBySentences(text: string, chunkSize: number, chunkOverlap: number): TextChunk[] {
    const sentenceRegex = /[^.!?]+[.!?]+/g;
    const sentences: string[] = [];
    let match;

    while ((match = sentenceRegex.exec(text)) !== null) {
      sentences.push(match[0].trim());
    }

    if (sentences.length === 0) {
      sentences.push(text);
    }

    const chunks: TextChunk[] = [];
    let currentChunk = '';
    let currentStartOffset = 0;
    let chunkIndex = 0;
    let offset = 0;

    for (const sentence of sentences) {
      if (currentChunk.length + sentence.length + 1 > chunkSize && currentChunk.length > 0) {
        chunks.push({
          content: currentChunk.trim(),
          index: chunkIndex++,
          startOffset: currentStartOffset,
          endOffset: offset,
        });

        const overlapStart = Math.max(0, currentChunk.length - chunkOverlap);
        currentChunk = currentChunk.substring(overlapStart);
        currentStartOffset = offset - currentChunk.length;
      }

      currentChunk += (currentChunk.length > 0 ? ' ' : '') + sentence;
      offset += sentence.length + 1;
    }

    if (currentChunk.trim().length > 0) {
      chunks.push({
        content: currentChunk.trim(),
        index: chunkIndex,
        startOffset: currentStartOffset,
        endOffset: offset,
      });
    }

    return chunks;
  }

  private chunkBySize(text: string, chunkSize: number, chunkOverlap: number): TextChunk[] {
    const chunks: TextChunk[] = [];
    let startOffset = 0;
    let chunkIndex = 0;

    while (startOffset < text.length) {
      const endOffset = Math.min(startOffset + chunkSize, text.length);
      const content = text.substring(startOffset, endOffset);

      chunks.push({
        content,
        index: chunkIndex++,
        startOffset,
        endOffset,
      });

      startOffset = endOffset - chunkOverlap;
      if (startOffset >= text.length - chunkOverlap) {
        break;
      }
    }

    return chunks;
  }

  estimateTokens(text: string): number {
    return Math.ceil(text.length / 4);
  }

  mergeChunks(chunks: TextChunk[], maxTokens: number): TextChunk[] {
    const merged: TextChunk[] = [];
    let currentContent = '';
    let currentStartOffset = 0;
    let mergedIndex = 0;

    for (const chunk of chunks) {
      const combinedTokens = this.estimateTokens(currentContent + '\n' + chunk.content);

      if (combinedTokens > maxTokens && currentContent.length > 0) {
        merged.push({
          content: currentContent,
          index: mergedIndex++,
          startOffset: currentStartOffset,
          endOffset: chunk.startOffset,
        });
        currentContent = chunk.content;
        currentStartOffset = chunk.startOffset;
      } else {
        currentContent += (currentContent.length > 0 ? '\n' : '') + chunk.content;
        if (merged.length === 0) {
          currentStartOffset = chunk.startOffset;
        }
      }
    }

    if (currentContent.length > 0) {
      merged.push({
        content: currentContent,
        index: mergedIndex,
        startOffset: currentStartOffset,
        endOffset: chunks[chunks.length - 1]?.endOffset || 0,
      });
    }

    return merged;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import pdfParse from 'pdf-parse';
import * as mammoth from 'mammoth';
import { StorageService } from '../storage/storage.service';

export interface ProcessedDocument {
  text: string;
  pageCount: number;
  metadata: Record<string, unknown>;
}

@Injectable()
export class DocumentProcessorService {
  private readonly logger = new Logger(DocumentProcessorService.name);

  constructor(private readonly storageService: StorageService) {}

  async processDocument(fileKey: string, mimeType: string): Promise<ProcessedDocument> {
    const buffer = await this.storageService.download(fileKey);

    switch (mimeType) {
      case 'application/pdf':
        return this.processPdf(buffer);
      case 'text/plain':
      case 'text/markdown':
        return this.processText(buffer);
      case 'application/msword':
      case 'application/vnd.openxmlformats-officedocument.wordprocessingml.document':
        return this.processDocx(buffer);
      default:
        throw new Error(`Unsupported document type: ${mimeType}`);
    }
  }

  private async processPdf(buffer: Buffer): Promise<ProcessedDocument> {
    try {
      const data = await pdfParse(buffer);

      return {
        text: data.text,
        pageCount: data.numpages,
        metadata: {
          info: data.info,
          version: data.version,
        },
      };
    } catch (error) {
      this.logger.error('PDF processing failed', error);
      throw new Error('Failed to process PDF');
    }
  }

  private async processText(buffer: Buffer): Promise<ProcessedDocument> {
    const text = buffer.toString('utf-8');

    return {
      text,
      pageCount: 1,
      metadata: {},
    };
  }

  private async processDocx(buffer: Buffer): Promise<ProcessedDocument> {
    try {
      const result = await mammoth.extractRawText({ buffer });
      const text = this.cleanText(result.value);

      // Extract any warnings/messages as metadata
      const warnings = result.messages.filter((m) => m.type === 'warning').map((m) => m.message);

      return {
        text,
        pageCount: this.estimatePageCount(text),
        metadata: {
          warnings: warnings.length > 0 ? warnings : undefined,
          format: 'docx',
        },
      };
    } catch (error) {
      this.logger.error('DOCX processing failed', error);
      throw new Error('Failed to process DOCX document');
    }
  }

  private estimatePageCount(text: string): number {
    // Estimate based on ~3000 characters per page (with typical margins)
    const charsPerPage = 3000;
    return Math.max(1, Math.ceil(text.length / charsPerPage));
  }

  async extractTextFromUrl(url: string): Promise<string> {
    try {
      const response = await fetch(url);
      const html = await response.text();

      const textContent = html
        .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
        .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
        .replace(/<[^>]*>/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();

      return textContent;
    } catch (error) {
      this.logger.error('URL text extraction failed', error);
      throw new Error('Failed to extract text from URL');
    }
  }

  cleanText(text: string): string {
    return text
      .replace(/\r\n/g, '\n')
      .replace(/\r/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .replace(/[ \t]+/g, ' ')
      .replace(/^\s+|\s+$/gm, '')
      .trim();
  }
}

