import { Global, Module } from '@nestjs/common';
import { QdrantService } from './qdrant.service';

@Global()
@Module({
  providers: [QdrantService],
  exports: [QdrantService],
})
export class QdrantModule {}

import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { QdrantClient } from '@qdrant/js-client-rest';

export interface VectorPoint {
  id: string;
  vector: number[];
  payload?: Record<string, unknown>;
}

export interface SearchResult {
  id: string;
  score: number;
  payload?: Record<string, unknown>;
}

export interface CollectionInfo {
  name: string;
  vectorSize: number;
  pointsCount: number;
}

@Injectable()
export class QdrantService implements OnModuleInit {
  private readonly logger = new Logger(QdrantService.name);
  private client: QdrantClient | null = null;
  private initialized = false;
  private initPromise: Promise<void> | null = null;
  private hostConfigured = false;
  private collectionPrefix: string;

  constructor(private readonly configService: ConfigService) {
    this.hostConfigured = !!this.configService.get<string>('QDRANT_HOST');
    this.collectionPrefix = this.configService.get<string>('QDRANT_COLLECTION_PREFIX', 'studyield');
  }

  async onModuleInit() {
    // Initialize Qdrant in background to not block app startup
    this.initializeQdrantAsync();
  }

  private initializeQdrantAsync(): void {
    if (!this.hostConfigured) {
      this.logger.warn('QDRANT_HOST not configured - Qdrant features disabled');
      return;
    }

    this.initPromise = this.initializeQdrant().catch((error) => {
      this.logger.error('Qdrant initialization failed:', error.message);
    });
  }

  private async initializeQdrant(): Promise<void> {
    const host = this.configService.get<string>('QDRANT_HOST', 'localhost');
    const port = this.configService.get<number>('QDRANT_PORT', 6333);
    const apiKey = this.configService.get<string>('QDRANT_API_KEY');

    let url: string;
    if (host.startsWith('http://') || host.startsWith('https://')) {
      url = port === 6333 ? host : `${host}:${port}`;
    } else {
      url = `http://${host}:${port}`;
    }

    this.logger.log(`Connecting to Qdrant at ${url}...`);

    const clientConfig: Record<string, unknown> = {
      url,
      checkCompatibility: false,
      timeout: 5000,
    };

    if (apiKey) {
      clientConfig.apiKey = apiKey;
    }

    this.client = new QdrantClient(clientConfig as ConstructorParameters<typeof QdrantClient>[0]);

    // Validate connection
    const collections = await this.client.getCollections();
    this.initialized = true;
    this.logger.log(`Qdrant connected. Found ${collections.collections.length} collections`);
  }

  isConfigured(): boolean {
    return this.initialized && this.client !== null;
  }

  async waitForInit(timeoutMs = 10000): Promise<boolean> {
    if (!this.hostConfigured) {
      return false;
    }

    if (this.initialized) {
      return true;
    }

    if (this.initPromise) {
      const timeout = new Promise<void>((resolve) => setTimeout(resolve, timeoutMs));
      await Promise.race([this.initPromise, timeout]);
    }

    return this.initialized;
  }

  private getCollectionName(name: string): string {
    return `${this.collectionPrefix}_${name}`;
  }

  async createCollection(name: string, vectorSize: number): Promise<void> {
    if (!this.client) {
      this.logger.warn(`Qdrant not available - skipping collection creation for ${name}`);
      return;
    }

    const collectionName = this.getCollectionName(name);
    try {
      await this.client.createCollection(collectionName, {
        vectors: {
          size: vectorSize,
          distance: 'Cosine',
        },
        optimizers_config: {
          default_segment_number: 2,
        },
        replication_factor: 1,
      });
      this.logger.log(`Collection ${collectionName} created`);
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      if (errorMessage.includes('already exists')) {
        this.logger.debug(`Collection ${collectionName} already exists`);
      } else {
        throw error;
      }
    }
  }

  async deleteCollection(name: string): Promise<void> {
    if (!this.client) return;

    const collectionName = this.getCollectionName(name);
    try {
      await this.client.deleteCollection(collectionName);
      this.logger.log(`Collection ${collectionName} deleted`);
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      if (!errorMessage.includes('not found')) {
        throw error;
      }
    }
  }

  async upsertPoints(collectionName: string, points: VectorPoint[]): Promise<void> {
    if (!this.client) {
      this.logger.warn('Qdrant not available - skipping upsert');
      return;
    }

    const fullName = this.getCollectionName(collectionName);
    await this.client.upsert(fullName, {
      wait: true,
      points: points.map((p) => ({
        id: p.id,
        vector: p.vector,
        payload: p.payload,
      })),
    });
  }

  async deletePoints(collectionName: string, ids: string[]): Promise<void> {
    if (!this.client) return;

    const fullName = this.getCollectionName(collectionName);
    await this.client.delete(fullName, {
      wait: true,
      points: ids,
    });
  }

  async search(
    collectionName: string,
    vector: number[],
    limit = 10,
    filter?: Record<string, unknown>,
  ): Promise<SearchResult[]> {
    if (!this.client) {
      this.logger.warn('Qdrant not available - returning empty search results');
      return [];
    }

    const fullName = this.getCollectionName(collectionName);
    const results = await this.client.search(fullName, {
      vector,
      limit,
      with_payload: true,
      filter: filter as Parameters<typeof this.client.search>[1]['filter'],
    });

    return results.map((r) => ({
      id: String(r.id),
      score: r.score,
      payload: r.payload as Record<string, unknown>,
    }));
  }

  async getPoint(collectionName: string, id: string): Promise<VectorPoint | null> {
    if (!this.client) return null;

    const fullName = this.getCollectionName(collectionName);
    try {
      const results = await this.client.retrieve(fullName, {
        ids: [id],
        with_payload: true,
        with_vector: true,
      });

      if (results.length === 0) return null;

      const point = results[0];
      return {
        id: String(point.id),
        vector: point.vector as number[],
        payload: point.payload as Record<string, unknown>,
      };
    } catch {
      return null;
    }
  }

  async getCollectionInfo(name: string): Promise<CollectionInfo | null> {
    if (!this.client) return null;

    const collectionName = this.getCollectionName(name);
    try {
      const info = await this.client.getCollection(collectionName);
      const vectors = info.config.params.vectors;
      let vectorSize = 0;
      if (typeof vectors === 'object' && vectors !== null && 'size' in vectors) {
        vectorSize = (vectors as { size: number }).size;
      }
      return {
        name: collectionName,
        vectorSize,
        pointsCount: info.points_count || 0,
      };
    } catch {
      return null;
    }
  }

  async upsertBatch(collectionName: string, points: VectorPoint[]): Promise<void> {
    if (!this.client) {
      this.logger.warn('Qdrant not available - skipping batch upsert');
      return;
    }

    const fullName = this.getCollectionName(collectionName);
    await this.client.upsert(fullName, {
      wait: true,
      points: points.map((p) => ({
        id: p.id,
        vector: p.vector,
        payload: p.payload,
      })),
    });
  }

  async searchWithPayloadFilter(
    collectionName: string,
    vector: number[],
    limit: number,
    filter: Array<{ key: string; match: { value: string } }>,
  ): Promise<SearchResult[]> {
    if (!this.client) {
      this.logger.warn('Qdrant not available - returning empty search results');
      return [];
    }

    const fullName = this.getCollectionName(collectionName);
    const qdrantFilter = {
      must: filter.map((f) => ({
        key: f.key,
        match: f.match,
      })),
    };

    const results = await this.client.search(fullName, {
      vector,
      limit,
      with_payload: true,
      filter: qdrantFilter as Parameters<typeof this.client.search>[1]['filter'],
    });

    return results.map((r) => ({
      id: String(r.id),
      score: r.score,
      payload: r.payload as Record<string, unknown>,
    }));
  }

  async deleteByFilter(collectionName: string, filter: Record<string, unknown>): Promise<void> {
    if (!this.client) {
      this.logger.warn('Qdrant not available - skipping delete');
      return;
    }

    const fullName = this.getCollectionName(collectionName);
    await this.client.delete(fullName, {
      wait: true,
      filter: filter as unknown as Parameters<typeof this.client.delete>[1] extends {
        filter?: infer F;
      }
        ? F
        : never,
    });
  }

  async healthCheck(): Promise<boolean> {
    if (!this.client) return false;

    try {
      await this.client.getCollections();
      return true;
    } catch {
      return false;
    }
  }
}

import { Global, Module } from '@nestjs/common';
import { QueueService } from './queue.service';

@Global()
@Module({
  providers: [QueueService],
  exports: [QueueService],
})
export class QueueModule {}

import { Injectable, Logger, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { Queue, Worker, Job, QueueEvents, JobsOptions } from 'bullmq';
import IORedis from 'ioredis';

export type JobProcessor<T = unknown, R = unknown> = (job: Job<T>) => Promise<R>;

export interface QueueConfig {
  name: string;
  processor: JobProcessor;
  concurrency?: number;
}

@Injectable()
export class QueueService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(QueueService.name);
  private connection: IORedis;
  private queues: Map<string, Queue> = new Map();
  private workers: Map<string, Worker> = new Map();
  private queueEvents: Map<string, QueueEvents> = new Map();

  constructor(private readonly configService: ConfigService) {}

  async onModuleInit() {
    this.connection = new IORedis({
      host: this.configService.get<string>('REDIS_HOST'),
      port: this.configService.get<number>('REDIS_PORT'),
      password: this.configService.get<string>('REDIS_PASSWORD') || undefined,
      maxRetriesPerRequest: null,
    });

    this.connection.on('error', (err) => {
      this.logger.error('BullMQ Redis connection error', err);
    });

    this.logger.log('BullMQ connection initialized');
  }

  async onModuleDestroy() {
    for (const worker of this.workers.values()) {
      await worker.close();
    }
    for (const events of this.queueEvents.values()) {
      await events.close();
    }
    for (const queue of this.queues.values()) {
      await queue.close();
    }
    await this.connection.quit();
    this.logger.log('BullMQ connections closed');
  }

  getQueue(name: string): Queue {
    if (!this.queues.has(name)) {
      const queue = new Queue(name, { connection: this.connection });
      this.queues.set(name, queue);
      this.logger.debug(`Queue ${name} created`);
    }
    return this.queues.get(name)!;
  }

  registerWorker<T = unknown, R = unknown>(
    queueName: string,
    processor: JobProcessor<T, R>,
    concurrency = 1,
  ): Worker<T, R> {
    if (this.workers.has(queueName)) {
      return this.workers.get(queueName) as Worker<T, R>;
    }

    const worker = new Worker<T, R>(queueName, processor, {
      connection: this.connection,
      concurrency,
    });

    worker.on('completed', (job) => {
      this.logger.debug(`Job ${job.id} in ${queueName} completed`);
    });

    worker.on('failed', (job, err) => {
      this.logger.error(`Job ${job?.id} in ${queueName} failed: ${err.message}`);
    });

    this.workers.set(queueName, worker);
    this.logger.log(`Worker registered for queue ${queueName} with concurrency ${concurrency}`);

    return worker;
  }

  async addJob<T = unknown>(
    queueName: string,
    name: string,
    data: T,
    options?: JobsOptions,
  ): Promise<Job<T>> {
    const queue = this.getQueue(queueName);
    const job = await queue.add(name, data, {
      removeOnComplete: 100,
      removeOnFail: 1000,
      ...options,
    });
    this.logger.debug(`Job ${job.id} added to ${queueName}`);
    return job;
  }

  async addBulkJobs<T = unknown>(
    queueName: string,
    jobs: Array<{ name: string; data: T; options?: JobsOptions }>,
  ): Promise<Job<T>[]> {
    const queue = this.getQueue(queueName);
    const result = await queue.addBulk(
      jobs.map((j) => ({
        name: j.name,
        data: j.data,
        opts: {
          removeOnComplete: 100,
          removeOnFail: 1000,
          ...j.options,
        },
      })),
    );
    this.logger.debug(`${result.length} jobs added to ${queueName}`);
    return result;
  }

  async getJob<T = unknown>(queueName: string, jobId: string): Promise<Job<T> | undefined> {
    const queue = this.getQueue(queueName);
    return queue.getJob(jobId) as Promise<Job<T> | undefined>;
  }

  async getJobState(queueName: string, jobId: string): Promise<string | null> {
    const job = await this.getJob(queueName, jobId);
    if (!job) return null;
    return job.getState();
  }

  async getJobProgress(queueName: string, jobId: string): Promise<number | null> {
    const job = await this.getJob(queueName, jobId);
    if (!job) return null;
    return job.progress as number;
  }

  async getQueueStats(queueName: string): Promise<{
    waiting: number;
    active: number;
    completed: number;
    failed: number;
    delayed: number;
  }> {
    const queue = this.getQueue(queueName);
    const [waiting, active, completed, failed, delayed] = await Promise.all([
      queue.getWaitingCount(),
      queue.getActiveCount(),
      queue.getCompletedCount(),
      queue.getFailedCount(),
      queue.getDelayedCount(),
    ]);
    return { waiting, active, completed, failed, delayed };
  }

  async removeJob(queueName: string, jobId: string): Promise<void> {
    const job = await this.getJob(queueName, jobId);
    if (job) {
      await job.remove();
      this.logger.debug(`Job ${jobId} removed from ${queueName}`);
    }
  }

  async pauseQueue(queueName: string): Promise<void> {
    const queue = this.getQueue(queueName);
    await queue.pause();
    this.logger.log(`Queue ${queueName} paused`);
  }

  async resumeQueue(queueName: string): Promise<void> {
    const queue = this.getQueue(queueName);
    await queue.resume();
    this.logger.log(`Queue ${queueName} resumed`);
  }

  async drainQueue(queueName: string): Promise<void> {
    const queue = this.getQueue(queueName);
    await queue.drain();
    this.logger.log(`Queue ${queueName} drained`);
  }

  subscribeToEvents(
    queueName: string,
    callbacks: {
      onCompleted?: (jobId: string, result: unknown) => void;
      onFailed?: (jobId: string, error: Error) => void;
      onProgress?: (jobId: string, progress: number) => void;
    },
  ): QueueEvents {
    if (!this.queueEvents.has(queueName)) {
      const events = new QueueEvents(queueName, { connection: this.connection });
      this.queueEvents.set(queueName, events);
    }

    const events = this.queueEvents.get(queueName)!;

    if (callbacks.onCompleted) {
      events.on('completed', ({ jobId, returnvalue }) => {
        callbacks.onCompleted!(jobId, returnvalue);
      });
    }

    if (callbacks.onFailed) {
      events.on('failed', ({ jobId, failedReason }) => {
        callbacks.onFailed!(jobId, new Error(failedReason));
      });
    }

    if (callbacks.onProgress) {
      events.on('progress', ({ jobId, data }) => {
        callbacks.onProgress!(jobId, data as number);
      });
    }

    return events;
  }

  async healthCheck(): Promise<boolean> {
    try {
      await this.connection.ping();
      return true;
    } catch {
      return false;
    }
  }
}

