  namespace: 'live-quiz',
  cors: {
    origin: process.env.CORS_ORIGINS?.split(',') || [
      'http://localhost:3010',
      'http://localhost:5189',
    ],
    credentials: true,
  },
})
export class LiveQuizGateway extends BaseGateway implements OnModuleInit {
  protected readonly logger = new Logger(LiveQuizGateway.name);

  constructor(
    private readonly liveQuizService: LiveQuizService,
    private readonly quizService: QuizService,
    private readonly subscriptionService: SubscriptionService,
  ) {
    super();
  }

  onModuleInit() {
    // Set up emit callback so service can emit events
    this.liveQuizService.setEmitCallback((roomCode, event, data) => {
      this.emitToRoom(`live-quiz:${roomCode}`, event, data);
    });
  }

  handleDisconnect(client: Socket) {
    super.handleDisconnect(client);
    const roomCode = client.data.roomCode as string;
    const user = this.getUserFromSocket(client);
    if (roomCode && user) {
      this.liveQuizService.removePlayer(roomCode, user.sub);
      const room = this.liveQuizService.getRoom(roomCode);
      if (room) {
        this.emitToRoom(
          `live-quiz:${roomCode}`,
          'room:updated',
          this.liveQuizService.serializeRoom(room),
        );
      }
    }
  }

  @SubscribeMessage('create-room')
  async handleCreateRoom(
    @MessageBody() data: { studySetId: string; questionCount?: number; timePerQuestion?: number },
    @ConnectedSocket() client: Socket,
  ) {
    this.logger.log(`create-room received from ${client.id}, data: ${JSON.stringify(data)}`);
    const user = this.getUserFromSocket(client);
    if (!user) {
      client.emit('error', { message: 'Not authenticated' });
      return;
    }

    const isPro = await this.subscriptionService.isPro(user.sub);
    if (!isPro) {
      client.emit('error', {
        message: 'This feature requires a Pro plan',
        upgrade: true,
        feature: 'live_quiz',
      });
      return;
    }

    try {
      // Generate quiz questions from study set
      const quiz = await this.quizService.generate(user.sub, {
        studySetId: data.studySetId,
        title: 'Live Quiz',
        questionCount: data.questionCount || 10,
        questionTypes: ['multiple_choice'],
        difficulty: 'mixed',
      });

      const quizQuestions = await this.quizService.getQuestions(quiz.id);
      const timeLimit = data.timePerQuestion || 20;

      const questions: Omit<LiveQuestion, 'playerAnswers'>[] = quizQuestions.map((q, i) => ({
        id: `q-${i}`,
        question: q.question,
        options: q.options || [],
        correctIndex: (q.options || []).indexOf(q.correctAnswer),
        timeLimit,
      }));

      const room = this.liveQuizService.createRoom(user.sub, data.studySetId, questions);

      // Add host as player
      this.liveQuizService.addPlayer(room.code, {
        id: user.sub,
        name: user.email.split('@')[0],
        avatarUrl: null,
        score: 0,
        answers: 0,
        correctAnswers: 0,
        connected: true,
      });

      client.data.roomCode = room.code;
      this.joinRoom(client, `live-quiz:${room.code}`);

      const serializedRoom = this.liveQuizService.serializeRoom(room);
      this.logger.log(`Room created: ${room.code}, emitting to client`);
      client.emit('room:created', serializedRoom);
    } catch (error) {
      this.logger.error(`Failed to create room: ${error}`);
      client.emit('error', { message: 'Failed to create quiz room' });
    }
  }

  @SubscribeMessage('join-room')
  handleJoinRoom(
    @MessageBody() data: { code: string; name: string; avatarUrl?: string },
    @ConnectedSocket() client: Socket,
  ) {
    const user = this.getUserFromSocket(client);
    if (!user) {
      client.emit('error', { message: 'Not authenticated' });
      return;
    }

    const room = this.liveQuizService.addPlayer(data.code, {
      id: user.sub,
      name: data.name || user.email.split('@')[0],
      avatarUrl: data.avatarUrl || null,
      score: 0,
      answers: 0,
      correctAnswers: 0,
      connected: true,
    });

    if (!room) {
      client.emit('error', { message: 'Room not found or game already started' });
      return;
    }

    client.data.roomCode = room.code;
    this.joinRoom(client, `live-quiz:${room.code}`);

    const serializedRoom = this.liveQuizService.serializeRoom(room);
    client.emit('room:joined', serializedRoom);
    this.emitToRoom(`live-quiz:${room.code}`, 'room:updated', serializedRoom);
  }

  @SubscribeMessage('start-game')
  handleStartGame(@MessageBody() data: { code: string }, @ConnectedSocket() client: Socket) {
    const user = this.getUserFromSocket(client);
    if (!user) {
      client.emit('error', { message: 'Not authenticated' });
      return;
    }

    const room = this.liveQuizService.startGame(data.code, user.sub);
    if (!room) {
      client.emit('error', { message: 'Cannot start game. You must be the host.' });
      return;
    }

    this.logger.log(`Game started for room ${data.code}`);
    // The service handles emitting countdown and starting questions
  }

  @SubscribeMessage('submit-answer')
  handleSubmitAnswer(
    @MessageBody() data: { code: string; questionIndex: number; answerIndex: number },
    @ConnectedSocket() client: Socket,
  ) {
    const user = this.getUserFromSocket(client);
    if (!user) {
      client.emit('error', { message: 'Not authenticated' });
      return;
    }

    const result = this.liveQuizService.submitAnswer(
      data.code,
      user.sub,
      data.questionIndex,
      data.answerIndex,
    );

    if (!result) {
      client.emit('error', { message: 'Cannot submit answer' });
      return;
    }

    // Emit to player privately that their answer was locked
    client.emit('answer:locked', {
      questionIndex: data.questionIndex,
      answerIndex: data.answerIndex,
      correct: result.correct,
      score: result.score,
    });

    // Emit updated player count who answered
    const room = result.room;
    const question = room.questions[data.questionIndex];
    this.emitToRoom(`live-quiz:${data.code}`, 'answers:update', {
      answeredCount: question.playerAnswers.size,
      totalPlayers: room.players.size,
    });
  }

  @SubscribeMessage('leave-room')
  handleLeaveRoom(@MessageBody() data: { code: string }, @ConnectedSocket() client: Socket) {
    const user = this.getUserFromSocket(client);
    if (!user) {
      client.emit('error', { message: 'Not authenticated' });
      return;
    }

    this.liveQuizService.removePlayer(data.code, user.sub);
    this.leaveRoom(client, `live-quiz:${data.code}`);
    client.data.roomCode = null;

    const room = this.liveQuizService.getRoom(data.code);
    if (room) {
      this.emitToRoom(
        `live-quiz:${data.code}`,
        'room:updated',
        this.liveQuizService.serializeRoom(room),
      );
    }

    client.emit('room:left', {});
  }

  @SubscribeMessage('get-summary')
  handleGetSummary(@MessageBody() data: { code: string }, @ConnectedSocket() client: Socket) {
    const summary = this.liveQuizService.getGameSummary(data.code);
    if (!summary) {
      client.emit('error', { message: 'Game not found' });
      return;
    }
    client.emit('game:summary', summary);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { DatabaseService } from '../database/database.service';

export interface LivePlayer {
  id: string;
  name: string;
  avatarUrl: string | null;
  score: number;
  answers: number;
  correctAnswers: number;
  connected: boolean;
}

export interface PlayerAnswer {
  playerId: string;
  playerName: string;
  answerIndex: number;
  answerText: string;
  correct: boolean;
  timeRemaining: number;
  pointsEarned: number;
}

export interface LiveQuestion {
  id: string;
  question: string;
  options: string[];
  correctIndex: number;
  timeLimit: number;
  playerAnswers: Map<string, PlayerAnswer>; // Track answers per question
}

export interface LiveRoom {
  code: string;
  hostId: string;
  studySetId: string;
  players: Map<string, LivePlayer>;
  questions: LiveQuestion[];
  currentQuestionIndex: number;
  status: 'waiting' | 'starting' | 'countdown' | 'question' | 'result' | 'finished';
  questionStartTime: number | null;
  questionTimer: NodeJS.Timeout | null;
  resultTimer: NodeJS.Timeout | null;
  createdAt: Date;
}

export interface QuestionResultData {
  questionIndex: number;
  question: string;
  correctIndex: number;
  correctAnswer: string;
  playerAnswers: PlayerAnswer[];
  leaderboard: LivePlayer[];
}

@Injectable()
export class LiveQuizService {
  private readonly logger = new Logger(LiveQuizService.name);
  private rooms = new Map<string, LiveRoom>();

  // Callback for emitting events (set by gateway)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private emitCallback: ((roomCode: string, event: string, data: any) => void) | null = null;

  constructor(private readonly db: DatabaseService) {}

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  setEmitCallback(callback: (roomCode: string, event: string, data: any) => void) {
    this.emitCallback = callback;
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private emit(roomCode: string, event: string, data: any) {
    if (this.emitCallback) {
      this.emitCallback(roomCode, event, data);
    }
  }

  generateRoomCode(): string {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    let code = '';
    for (let i = 0; i < 6; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    if (this.rooms.has(code)) return this.generateRoomCode();
    return code;
  }

  createRoom(
    hostId: string,
    studySetId: string,
    questions: Omit<LiveQuestion, 'playerAnswers'>[],
  ): LiveRoom {
    const code = this.generateRoomCode();
    const room: LiveRoom = {
      code,
      hostId,
      studySetId,
      players: new Map(),
      questions: questions.map((q) => ({ ...q, playerAnswers: new Map() })),
      currentQuestionIndex: -1,
      status: 'waiting',
      questionStartTime: null,
      questionTimer: null,
      resultTimer: null,
      createdAt: new Date(),
    };
    this.rooms.set(code, room);
    this.logger.log(`Room created: ${code} by host ${hostId}`);
    return room;
  }

  getRoom(code: string): LiveRoom | undefined {
    return this.rooms.get(code.toUpperCase());
  }

  addPlayer(code: string, player: LivePlayer): LiveRoom | null {
    const room = this.rooms.get(code.toUpperCase());
    if (!room || room.status !== 'waiting') return null;
    room.players.set(player.id, player);
    this.logger.log(`Player ${player.name} joined room ${code}`);
    return room;
  }

  removePlayer(code: string, playerId: string): LiveRoom | null {
    const room = this.rooms.get(code.toUpperCase());
    if (!room) return null;
    room.players.delete(playerId);
    if (room.players.size === 0 && room.hostId === playerId) {
      this.clearRoomTimers(room);
      this.rooms.delete(code.toUpperCase());
      this.logger.log(`Room ${code} deleted (empty)`);
      return null;
    }
    return room;
  }

  private clearRoomTimers(room: LiveRoom) {
    if (room.questionTimer) {
      clearTimeout(room.questionTimer);
      room.questionTimer = null;
    }
    if (room.resultTimer) {
      clearTimeout(room.resultTimer);
      room.resultTimer = null;
    }
  }

  startGame(code: string, hostId: string): LiveRoom | null {
    const room = this.rooms.get(code.toUpperCase());
    if (!room || room.hostId !== hostId || room.status !== 'waiting') return null;
    if (room.questions.length === 0) return null;

    room.status = 'countdown';
    room.currentQuestionIndex = 0;

    // Emit countdown, then start first question after 3 seconds
    this.emit(code, 'game:countdown', { countdown: 3 });

    setTimeout(() => {
      this.startQuestion(code);
    }, 3000);

    return room;
  }

  private startQuestion(code: string) {
    const room = this.rooms.get(code.toUpperCase());
    if (!room || room.currentQuestionIndex >= room.questions.length) return;

    const question = room.questions[room.currentQuestionIndex];
    room.status = 'question';
    room.questionStartTime = Date.now();

    // Clear any existing answers for this question
    question.playerAnswers.clear();

    this.logger.log(
      `Starting question ${room.currentQuestionIndex + 1}/${room.questions.length} for room ${code}`,
    );

    // Emit question to all players
    this.emit(code, 'question:start', {
      index: room.currentQuestionIndex,
      question: question.question,
      options: question.options,
      timeLimit: question.timeLimit,
      total: room.questions.length,
    });

    // Set timer for auto-advance
    room.questionTimer = setTimeout(() => {
      this.endQuestion(code);
    }, question.timeLimit * 1000);
  }

  private endQuestion(code: string) {
    const room = this.rooms.get(code.toUpperCase());
    if (!room || room.status !== 'question') return;

    this.clearRoomTimers(room);
    room.status = 'result';

    const question = room.questions[room.currentQuestionIndex];

    // Players who didn't answer get 0 points
    room.players.forEach((player, playerId) => {
      if (!question.playerAnswers.has(playerId)) {
        question.playerAnswers.set(playerId, {
          playerId,
          playerName: player.name,
          answerIndex: -1,
          answerText: '(No answer)',
          correct: false,
          timeRemaining: 0,
          pointsEarned: 0,
        });
      }
    });

    const resultData: QuestionResultData = {
      questionIndex: room.currentQuestionIndex,
      question: question.question,
      correctIndex: question.correctIndex,
      correctAnswer: question.options[question.correctIndex],
      playerAnswers: Array.from(question.playerAnswers.values()),
      leaderboard: this.getLeaderboard(code),
    };

    this.logger.log(`Question ${room.currentQuestionIndex + 1} ended for room ${code}`);
    this.emit(code, 'question:result', resultData);

    // Auto-advance to next question after 4 seconds
    room.resultTimer = setTimeout(() => {
      this.advanceToNextQuestion(code);
    }, 4000);
  }

  private advanceToNextQuestion(code: string) {
    const room = this.rooms.get(code.toUpperCase());
    if (!room) return;

    room.currentQuestionIndex++;

    if (room.currentQuestionIndex >= room.questions.length) {
      // Game finished
      room.status = 'finished';
      this.logger.log(`Game finished for room ${code}`);
      this.emit(code, 'game:finished', {
        leaderboard: this.getLeaderboard(code),
        totalQuestions: room.questions.length,
      });

      // Save to database
      this.saveHistory(room).catch((err) => {
        this.logger.error(`Failed to save quiz history: ${err.message}`);
      });
      return;
    }

    // Start next question with brief countdown
    room.status = 'countdown';
    this.emit(code, 'question:next', {
      nextIndex: room.currentQuestionIndex,
      countdown: 2,
    });

    setTimeout(() => {
      this.startQuestion(code);
    }, 2000);
  }

  submitAnswer(
    code: string,
    playerId: string,
    questionIndex: number,
    answerIndex: number,
  ): { correct: boolean; score: number; room: LiveRoom } | null {
    const room = this.rooms.get(code.toUpperCase());
    if (!room || room.status !== 'question') return null;
    if (room.currentQuestionIndex !== questionIndex) return null;

    const player = room.players.get(playerId);
    if (!player) return null;

    const question = room.questions[questionIndex];

    // Check if already answered
    if (question.playerAnswers.has(playerId)) {
      return null; // Already answered
    }

    // Calculate time remaining
    const elapsed = room.questionStartTime
      ? (Date.now() - room.questionStartTime) / 1000
      : question.timeLimit;
    const timeRemaining = Math.max(0, question.timeLimit - elapsed);

    const correct = answerIndex === question.correctIndex;
    const timeBonus = Math.round((timeRemaining / question.timeLimit) * 500);
    const points = correct ? 1000 + timeBonus : 0;

    // Update player stats
    player.answers++;
    if (correct) player.correctAnswers++;
    player.score += points;

    // Store the answer
    const playerAnswer: PlayerAnswer = {
      playerId,
      playerName: player.name,
      answerIndex,
      answerText: question.options[answerIndex] || '(Invalid)',
      correct,
      timeRemaining: Math.round(timeRemaining * 10) / 10,
      pointsEarned: points,
    };
    question.playerAnswers.set(playerId, playerAnswer);

    this.logger.log(
      `Player ${player.name} answered Q${questionIndex + 1}: ${correct ? 'correct' : 'wrong'} (+${points})`,
    );

    // Check if all players have answered
    if (question.playerAnswers.size >= room.players.size) {
      this.logger.log(`All players answered for Q${questionIndex + 1}, ending early`);
      // Clear existing timer and end question early
      if (room.questionTimer) {
        clearTimeout(room.questionTimer);
        room.questionTimer = null;
      }
      // Small delay before showing results
      setTimeout(() => this.endQuestion(code), 500);
    }

    return { correct, score: points, room };
  }

  getLeaderboard(code: string): LivePlayer[] {
    const room = this.rooms.get(code.toUpperCase());
    if (!room) return [];
    return Array.from(room.players.values())
      .sort((a, b) => b.score - a.score)
      .map((p, index) => ({ ...p, rank: index + 1 }));
  }

  getAnswerStats(
    code: string,
    questionIndex: number,
  ): { option: string; count: number; percentage: number }[] {
    const room = this.rooms.get(code.toUpperCase());
    if (!room || questionIndex >= room.questions.length) return [];

    const question = room.questions[questionIndex];
    const totalAnswers = question.playerAnswers.size;

    return question.options.map((option, index) => {
      const count = Array.from(question.playerAnswers.values()).filter(
        (a) => a.answerIndex === index,
      ).length;
      return {
        option,
        count,
        percentage: totalAnswers > 0 ? Math.round((count / totalAnswers) * 100) : 0,
      };
    });
  }

  serializeRoom(room: LiveRoom) {
    return {
      code: room.code,
      hostId: room.hostId,
      studySetId: room.studySetId,
      players: Array.from(room.players.values()),
      currentQuestionIndex: room.currentQuestionIndex,
      totalQuestions: room.questions.length,
      status: room.status,
    };
  }

  getGameSummary(code: string) {
    const room = this.rooms.get(code.toUpperCase());
    if (!room) return null;

    return {
      code: room.code,
      studySetId: room.studySetId,
      totalQuestions: room.questions.length,
      players: Array.from(room.players.values()).map((p) => ({
        id: p.id,
        name: p.name,
        score: p.score,
        correctAnswers: p.correctAnswers,
        totalAnswers: p.answers,
        accuracy: p.answers > 0 ? Math.round((p.correctAnswers / p.answers) * 100) : 0,
      })),
      questions: room.questions.map((q, i) => ({
        index: i,
        question: q.question,
        correctAnswer: q.options[q.correctIndex],
        answers: Array.from(q.playerAnswers.values()),
      })),
    };
  }

  cleanupStaleRooms() {
    const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
    for (const [code, room] of this.rooms) {
      if (room.createdAt < oneHourAgo) {
        this.clearRoomTimers(room);
        this.rooms.delete(code);
        this.logger.log(`Stale room cleaned up: ${code}`);
      }
    }
  }

  /**
   * Save completed game to database for history
   */
  private async saveHistory(room: LiveRoom): Promise<void> {
    try {
      // 1. Create session record
      const sessionResult = await this.db.queryOne<{ id: string }>(
        `INSERT INTO live_quiz_sessions (room_code, host_id, study_set_id, total_questions, status, started_at, finished_at)
         VALUES ($1, $2, $3, $4, 'completed', $5, NOW())
         RETURNING id`,
        [room.code, room.hostId, room.studySetId, room.questions.length, room.createdAt],
      );

      if (!sessionResult) {
        throw new Error('Failed to create session record');
      }

      const sessionId = sessionResult.id;
      const leaderboard = this.getLeaderboard(room.code);

      // 2. Create participant records
      for (let i = 0; i < leaderboard.length; i++) {
        const player = leaderboard[i];
        const participantResult = await this.db.queryOne<{ id: string }>(
          `INSERT INTO live_quiz_participants (session_id, user_id, player_name, score, correct_answers, total_answers, rank)
           VALUES ($1, $2, $3, $4, $5, $6, $7)
           RETURNING id`,
          [
            sessionId,
            player.id,
            player.name,
            player.score,
            player.correctAnswers,
            player.answers,
            i + 1,
          ],
        );

        if (!participantResult) continue;

        // 3. Save individual answers for each participant
        for (let qIdx = 0; qIdx < room.questions.length; qIdx++) {
          const question = room.questions[qIdx];
          const answer = question.playerAnswers.get(player.id);

          if (answer) {
            await this.db.query(
              `INSERT INTO live_quiz_answers (session_id, participant_id, question_index, question_text, answer_text, correct_answer, is_correct, points_earned, time_taken_seconds)
               VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
              [
                sessionId,
                participantResult.id,
                qIdx,
                question.question,
                answer.answerText,
                question.options[question.correctIndex],
                answer.correct,
                answer.pointsEarned,
                question.timeLimit - answer.timeRemaining,
              ],
            );
          }
        }
      }

      this.logger.log(
        `Quiz history saved: session ${sessionId} with ${leaderboard.length} participants`,
      );
    } catch (error) {
      this.logger.error(`Failed to save quiz history: ${error}`);
      throw error;
    }
  }

  /**
   * Get user's live quiz history
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  async getUserHistory(userId: string, limit = 20): Promise<any[]> {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const results = await this.db.queryMany<any>(
      `SELECT
        s.id,
        s.room_code,
        s.total_questions,
        s.finished_at,
        ss.title as study_set_title,
        p.score,
        p.correct_answers,
        p.total_answers,
        p.rank,
        (SELECT COUNT(*) FROM live_quiz_participants WHERE session_id = s.id) as player_count
       FROM live_quiz_sessions s
       JOIN live_quiz_participants p ON p.session_id = s.id AND p.user_id = $1
       LEFT JOIN study_sets ss ON ss.id = s.study_set_id
       ORDER BY s.finished_at DESC
       LIMIT $2`,
      [userId, limit],
    );

    return results.map((r) => ({
      id: r.id,
      roomCode: r.room_code,
      totalQuestions: r.total_questions,
      finishedAt: r.finished_at,
      studySetTitle: r.study_set_title,
      score: r.score,
      correctAnswers: r.correct_answers,
      totalAnswers: r.total_answers,
      rank: r.rank,
      playerCount: parseInt(r.player_count, 10),
    }));
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { AiService } from '../ai/ai.service';

export type QuestionType = 'multiple_choice' | 'true_false' | 'short_answer' | 'fill_blank';

export interface GeneratedQuestion {
  type: QuestionType;
  question: string;
  options?: string[];
  correctAnswer: string;
  explanation: string;
  difficulty: 'easy' | 'medium' | 'hard';
}

export interface GenerateQuizOptions {
  content: string;
  questionCount?: number;
  questionTypes?: QuestionType[];
  difficulty?: 'easy' | 'medium' | 'hard' | 'mixed';
  focusTopics?: string[];
}

@Injectable()
export class QuizGeneratorService {
  private readonly logger = new Logger(QuizGeneratorService.name);

  constructor(private readonly aiService: AiService) {}

  async generateQuestions(options: GenerateQuizOptions): Promise<GeneratedQuestion[]> {
    const {
      content,
      questionCount = 10,
      questionTypes = ['multiple_choice', 'true_false', 'short_answer'],
      difficulty = 'mixed',
      focusTopics = [],
    } = options;

    const systemPrompt = `You are an expert educational content creator specializing in generating high-quality quiz questions.

Generate ${questionCount} questions based on the provided study material.

Requirements:
- Question types to include: ${questionTypes.join(', ')}
- Difficulty level: ${difficulty}
${focusTopics.length > 0 ? `- Focus on these topics: ${focusTopics.join(', ')}` : ''}
- Each question should test understanding, not just memorization
- Provide clear explanations for each answer
- For multiple choice, provide 4 options with only one correct answer
- Ensure questions are varied and cover different aspects of the material

Return the questions in this exact JSON format:
{
  "questions": [
    {
      "type": "multiple_choice" | "true_false" | "short_answer" | "fill_blank",
      "question": "The question text",
      "options": ["A", "B", "C", "D"], // only for multiple_choice
      "correctAnswer": "The correct answer",
      "explanation": "Why this is correct",
      "difficulty": "easy" | "medium" | "hard"
    }
  ]
}`;

    const userPrompt = `Study Material:
${content}

Generate ${questionCount} quiz questions based on this material.`;

    const response = await this.aiService.completeJson<{ questions: GeneratedQuestion[] }>(
      [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt },
      ],
      { maxTokens: 4096 },
    );

    this.logger.log(`Generated ${response.questions.length} questions`);
    return response.questions;
  }

  async generateFromFlashcards(
    flashcards: Array<{ front: string; back: string }>,
    questionCount = 10,
  ): Promise<GeneratedQuestion[]> {
    const content = flashcards
      .map((f, i) => `${i + 1}. Q: ${f.front}\n   A: ${f.back}`)
      .join('\n\n');

    return this.generateQuestions({
      content,
      questionCount,
      questionTypes: ['multiple_choice', 'true_false', 'fill_blank'],
      difficulty: 'mixed',
    });
  }

  async generateAdaptive(
    content: string,
    userPerformance: { correct: number; total: number },
    previousQuestions: string[],
  ): Promise<GeneratedQuestion[]> {
    const accuracy =
      userPerformance.total > 0 ? userPerformance.correct / userPerformance.total : 0.5;

    let difficulty: 'easy' | 'medium' | 'hard';
    if (accuracy < 0.4) {
      difficulty = 'easy';
    } else if (accuracy > 0.8) {
      difficulty = 'hard';
    } else {
      difficulty = 'medium';
    }

    const systemPrompt = `You are an expert educational content creator specializing in adaptive quiz questions.

Generate 5 questions based on the provided study material.
The student's current accuracy is ${(accuracy * 100).toFixed(0)}%, so generate ${difficulty} difficulty questions.

${previousQuestions.length > 0 ? `Avoid repeating these previous questions:\n${previousQuestions.join('\n')}` : ''}

Return the questions in this exact JSON format:
{
  "questions": [
    {
      "type": "multiple_choice" | "true_false" | "short_answer",
      "question": "The question text",
      "options": ["A", "B", "C", "D"],
      "correctAnswer": "The correct answer",
      "explanation": "Why this is correct",
      "difficulty": "${difficulty}"
    }
  ]
}`;

    const response = await this.aiService.completeJson<{ questions: GeneratedQuestion[] }>(
      [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: content },
      ],
      { maxTokens: 2048 },
    );

    return response.questions;
  }
}

import {
  Controller,
  Get,
  Post,
  Delete,
  Body,
  Param,
  UseGuards,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth } from '@nestjs/swagger';
import { QuizService, CreateQuizDto, GenerateQuizDto, SubmitAttemptDto } from './quiz.service';
import { LiveQuizService } from './live-quiz.service';
import { JwtAuthGuard } from '../../common/guards/jwt-auth.guard';
import { CurrentUser, JwtPayload } from '../../common';
import { SubscriptionService } from '../subscription/subscription.service';

const FREE_QUIZ_TYPES = ['multiple_choice', 'true_false'];

@ApiTags('Quiz')
@Controller('quizzes')
@UseGuards(JwtAuthGuard)
@ApiBearerAuth()
export class QuizController {
  constructor(
    private readonly quizService: QuizService,
    private readonly liveQuizService: LiveQuizService,
    private readonly subscriptionService: SubscriptionService,
  ) {}

  @Post()
  @ApiOperation({ summary: 'Create a new quiz' })
  @ApiResponse({ status: 201, description: 'Quiz created' })
  async create(@CurrentUser() user: JwtPayload, @Body() dto: CreateQuizDto) {
    return this.quizService.create(user.sub, dto);
  }

  @Post('generate')
  @ApiOperation({ summary: 'Generate quiz with AI' })
  @ApiResponse({ status: 201, description: 'Quiz generated' })
  async generate(@CurrentUser() user: JwtPayload, @Body() dto: GenerateQuizDto) {
    const isPro = await this.subscriptionService.isPro(user.sub);
    if (!isPro && dto.questionTypes) {
      // Free users can only use basic quiz types
      dto.questionTypes = dto.questionTypes.filter((t) =>
        FREE_QUIZ_TYPES.includes(t),
      ) as GenerateQuizDto['questionTypes'];
      if (dto.questionTypes!.length === 0) {
        dto.questionTypes = ['multiple_choice', 'true_false'];
      }
    }
    return this.quizService.generate(user.sub, dto);
  }

  @Get()
  @ApiOperation({ summary: 'Get all quizzes for current user' })
  @ApiResponse({ status: 200, description: 'Quizzes list' })
  async findAll(@CurrentUser() user: JwtPayload) {
    return this.quizService.findByUser(user.sub);
  }

  @Get('study-set/:studySetId')
  @ApiOperation({ summary: 'Get quizzes by study set' })
  @ApiResponse({ status: 200, description: 'Quizzes list' })
  async findByStudySet(@Param('studySetId') studySetId: string) {
    return this.quizService.findByStudySet(studySetId);
  }

  @Get('attempts/:attemptId')
  @ApiOperation({ summary: 'Get attempt details' })
  @ApiResponse({ status: 200, description: 'Attempt details' })
  async getAttemptDetails(@CurrentUser() user: JwtPayload, @Param('attemptId') attemptId: string) {
    return this.quizService.getAttemptDetails(attemptId, user.sub);
  }

  @Get('live/history')
  @ApiOperation({ summary: 'Get live quiz history for current user' })
  @ApiResponse({ status: 200, description: 'Live quiz history' })
  async getLiveQuizHistory(@CurrentUser() user: JwtPayload) {
    return this.liveQuizService.getUserHistory(user.sub);
  }

  @Get(':id')
  @ApiOperation({ summary: 'Get quiz by ID' })
  @ApiResponse({ status: 200, description: 'Quiz' })
  async findOne(@CurrentUser() user: JwtPayload, @Param('id') id: string) {
    return this.quizService.findByIdWithAccess(id, user.sub);
  }

  @Get(':id/questions')
  @ApiOperation({ summary: 'Get quiz questions' })
  @ApiResponse({ status: 200, description: 'Questions list' })
  async getQuestions(@CurrentUser() user: JwtPayload, @Param('id') id: string) {
    await this.quizService.findByIdWithAccess(id, user.sub);
    return this.quizService.getQuestions(id);
  }

  @Post(':id/attempts')
  @ApiOperation({ summary: 'Submit quiz attempt' })
  @ApiResponse({ status: 201, description: 'Attempt submitted' })
  async submitAttempt(
    @CurrentUser() user: JwtPayload,
    @Param('id') id: string,
    @Body() dto: SubmitAttemptDto,
  ) {
    return this.quizService.submitAttempt(id, user.sub, dto);
  }

  @Get(':id/attempts')
  @ApiOperation({ summary: 'Get quiz attempts' })
  @ApiResponse({ status: 200, description: 'Attempts list' })
  async getAttempts(@CurrentUser() user: JwtPayload, @Param('id') id: string) {
    return this.quizService.getAttempts(id, user.sub);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiOperation({ summary: 'Delete quiz' })
  @ApiResponse({ status: 204, description: 'Quiz deleted' })
  async delete(@CurrentUser() user: JwtPayload, @Param('id') id: string) {
    await this.quizService.delete(id, user.sub);
  }
}

import { Module } from '@nestjs/common';
import { AuthModule } from '../auth/auth.module';
import { NotificationsModule } from '../notifications/notifications.module';
import { QuizService } from './quiz.service';
import { QuizController } from './quiz.controller';
import { QuizGeneratorService } from './quiz-generator.service';
import { LiveQuizService } from './live-quiz.service';
import { LiveQuizGateway } from './live-quiz.gateway';

@Module({
  imports: [AuthModule, NotificationsModule],
  controllers: [QuizController],
  providers: [QuizService, QuizGeneratorService, LiveQuizService, LiveQuizGateway],
  exports: [QuizService, QuizGeneratorService, LiveQuizService],
})
export class QuizModule {}

import { Injectable, Logger, NotFoundException, ForbiddenException } from '@nestjs/common';
import { v4 as uuidv4 } from 'uuid';
import { DatabaseService } from '../database/database.service';
import { QuizGeneratorService, QuestionType } from './quiz-generator.service';
import { NotificationsService } from '../notifications/notifications.service';

export interface Quiz {
  id: string;
  userId: string;
  studySetId: string | null;
  title: string;
  description: string | null;
  questionCount: number;
  timeLimit: number | null;
  isPublic: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export interface QuizQuestion {
  id: string;
  quizId: string;
  type: QuestionType;
  question: string;
  options: string[] | null;
  correctAnswer: string;
  explanation: string | null;
  difficulty: string;
  order: number;
}

export interface QuizAttempt {
  id: string;
  quizId: string;
  userId: string;
  score: number;
  totalQuestions: number;
  timeSpent: number;
  completedAt: Date;
  createdAt: Date;
}

export interface QuizAttemptAnswer {
  id: string;
  attemptId: string;
  questionId: string;
  userAnswer: string;
  isCorrect: boolean;
  timeSpent: number;
}

export interface CreateQuizDto {
  title: string;
  description?: string;
  studySetId?: string;
  timeLimit?: number;
  isPublic?: boolean;
  questions?: Array<{
    type: QuestionType;
    question: string;
    options?: string[];
    correctAnswer: string;
    explanation?: string;
    difficulty?: string;
  }>;
}

export interface GenerateQuizDto {
  studySetId?: string;
  content?: string;
  title: string;
  questionCount?: number;
  questionTypes?: QuestionType[];
  difficulty?: 'easy' | 'medium' | 'hard' | 'mixed';
}

export interface SubmitAttemptDto {
  answers: Array<{
    questionId: string;
    answer: string;
    timeSpent: number;
  }>;
  totalTimeSpent: number;
}

@Injectable()
export class QuizService {
  private readonly logger = new Logger(QuizService.name);

  constructor(
    private readonly db: DatabaseService,
    private readonly quizGenerator: QuizGeneratorService,
    private readonly notificationsService: NotificationsService,
  ) {}

  async create(userId: string, dto: CreateQuizDto): Promise<Quiz> {
    const id = uuidv4();
    const now = new Date();

    await this.db.queryOne<Quiz>(
      `INSERT INTO quizzes (id, user_id, study_set_id, title, description, time_limit, is_public, created_at, updated_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
       RETURNING *`,
      [
        id,
        userId,
        dto.studySetId || null,
        dto.title,
        dto.description || null,
        dto.timeLimit || null,
        dto.isPublic || false,
        now,
        now,
      ],
    );

    if (dto.questions && dto.questions.length > 0) {
      for (let i = 0; i < dto.questions.length; i++) {
        await this.addQuestion(id, dto.questions[i], i);
      }
    }

    this.logger.log(`Quiz created: ${id}`);
    return this.findById(id) as Promise<Quiz>;
  }

  async generate(userId: string, dto: GenerateQuizDto): Promise<Quiz> {
    let content = dto.content || '';

    if (dto.studySetId && !content) {
      const flashcards = await this.db.queryMany<{ front: string; back: string }>(
        'SELECT front, back FROM flashcards WHERE study_set_id = $1',
        [dto.studySetId],
      );

      if (flashcards.length === 0) {
        throw new NotFoundException('No flashcards found in study set');
      }

      content = flashcards.map((f) => `Q: ${f.front}\nA: ${f.back}`).join('\n\n');
    }

    if (!content) {
      throw new Error('No content provided for quiz generation');
    }

    const questions = await this.quizGenerator.generateQuestions({
      content,
      questionCount: dto.questionCount || 10,
      questionTypes: dto.questionTypes || ['multiple_choice', 'true_false'],
      difficulty: dto.difficulty || 'mixed',
    });

    const quiz = await this.create(userId, {
      title: dto.title,
      studySetId: dto.studySetId,
      questions: questions.map((q) => ({
        type: q.type,
        question: q.question,
        options: q.options,
        correctAnswer: q.correctAnswer,
        explanation: q.explanation,
        difficulty: q.difficulty,
      })),
    });

    return quiz;
  }

  async findById(id: string): Promise<Quiz | null> {
    const result = await this.db.queryOne<Quiz>(
      `SELECT q.*,
        (SELECT COUNT(*) FROM quiz_questions WHERE quiz_id = q.id) as question_count
       FROM quizzes q WHERE q.id = $1`,
      [id],
    );
    return result ? this.mapQuiz(result) : null;
  }

  async findByIdWithAccess(id: string, userId: string): Promise<Quiz> {
    const quiz = await this.findById(id);
    if (!quiz) {
      throw new NotFoundException('Quiz not found');
    }
    if (!quiz.isPublic && quiz.userId !== userId) {
      throw new ForbiddenException('Access denied');
    }
    return quiz;
  }

  async findByUser(userId: string): Promise<Quiz[]> {
    const results = await this.db.queryMany<Quiz>(
      `SELECT q.*,
        (SELECT COUNT(*) FROM quiz_questions WHERE quiz_id = q.id) as question_count
       FROM quizzes q
       WHERE q.user_id = $1
       ORDER BY q.updated_at DESC`,
      [userId],
    );
    return results.map((r) => this.mapQuiz(r));
  }

  async findByStudySet(studySetId: string): Promise<Quiz[]> {
    const results = await this.db.queryMany<Quiz>(
      `SELECT q.*,
        (SELECT COUNT(*) FROM quiz_questions WHERE quiz_id = q.id) as question_count
       FROM quizzes q
       WHERE q.study_set_id = $1
       ORDER BY q.created_at DESC`,
      [studySetId],
    );
    return results.map((r) => this.mapQuiz(r));
  }

  async getQuestions(quizId: string): Promise<QuizQuestion[]> {
    const results = await this.db.queryMany<QuizQuestion>(
      'SELECT * FROM quiz_questions WHERE quiz_id = $1 ORDER BY "order" ASC',
      [quizId],
    );
    return results.map((r) => this.mapQuestion(r));
  }

  async submitAttempt(quizId: string, userId: string, dto: SubmitAttemptDto): Promise<QuizAttempt> {
    await this.findByIdWithAccess(quizId, userId);

    const questions = await this.getQuestions(quizId);
    const questionMap = new Map(questions.map((q) => [q.id, q]));

    let correctCount = 0;
    const attemptId = uuidv4();
    const now = new Date();

    await this.db.query(
      `INSERT INTO quiz_attempts (id, quiz_id, user_id, time_spent, created_at)
       VALUES ($1, $2, $3, $4, $5)`,
      [attemptId, quizId, userId, dto.totalTimeSpent, now],
    );

    for (const answer of dto.answers) {
      const question = questionMap.get(answer.questionId);
      if (!question) continue;

      const isCorrect = this.checkAnswer(question, answer.answer);
      if (isCorrect) correctCount++;

      await this.db.query(
        `INSERT INTO quiz_attempt_answers (id, attempt_id, question_id, user_answer, is_correct, time_spent)
         VALUES ($1, $2, $3, $4, $5, $6)`,
        [uuidv4(), attemptId, answer.questionId, answer.answer, isCorrect, answer.timeSpent],
      );
    }

    const score = (correctCount / questions.length) * 100;

    await this.db.query(
      `UPDATE quiz_attempts SET score = $1, total_questions = $2, completed_at = $3 WHERE id = $4`,
      [score, questions.length, now, attemptId],
    );

    const attempt = await this.db.queryOne<QuizAttempt>(
      'SELECT * FROM quiz_attempts WHERE id = $1',
      [attemptId],
    );

    // Send notification based on score
    await this.sendQuizCompletionNotification(userId, score, correctCount, questions.length);

    this.logger.log(`Quiz attempt submitted: ${attemptId}, score: ${score.toFixed(1)}%`);
    return this.mapAttempt(attempt!);
  }

  async getAttempts(quizId: string, userId: string): Promise<QuizAttempt[]> {
    const results = await this.db.queryMany<QuizAttempt>(
      `SELECT * FROM quiz_attempts
       WHERE quiz_id = $1 AND user_id = $2
       ORDER BY created_at DESC`,
      [quizId, userId],
    );
    return results.map((r) => this.mapAttempt(r));
  }

  async getAttemptDetails(
    attemptId: string,
    userId: string,
  ): Promise<{ attempt: QuizAttempt; answers: QuizAttemptAnswer[] }> {
    const attempt = await this.db.queryOne<QuizAttempt>(
      'SELECT * FROM quiz_attempts WHERE id = $1',
      [attemptId],
    );

    if (!attempt) {
      throw new NotFoundException('Attempt not found');
    }

    if ((attempt as unknown as Record<string, unknown>).user_id !== userId) {
      throw new ForbiddenException('Access denied');
    }

    const answers = await this.db.queryMany<QuizAttemptAnswer>(
      'SELECT * FROM quiz_attempt_answers WHERE attempt_id = $1',
      [attemptId],
    );

    return {
      attempt: this.mapAttempt(attempt),
      answers: answers.map((a) => this.mapAttemptAnswer(a)),
    };
  }

  async delete(id: string, userId: string): Promise<void> {
    const quiz = await this.findById(id);
    if (!quiz) {
      throw new NotFoundException('Quiz not found');
    }
    if (quiz.userId !== userId) {
      throw new ForbiddenException('Access denied');
    }

    await this.db.query(
      'DELETE FROM quiz_attempt_answers WHERE attempt_id IN (SELECT id FROM quiz_attempts WHERE quiz_id = $1)',
      [id],
    );
    await this.db.query('DELETE FROM quiz_attempts WHERE quiz_id = $1', [id]);
    await this.db.query('DELETE FROM quiz_questions WHERE quiz_id = $1', [id]);
    await this.db.query('DELETE FROM quizzes WHERE id = $1', [id]);

    this.logger.log(`Quiz deleted: ${id}`);
  }

  private async addQuestion(
    quizId: string,
    question: {
      type: QuestionType;
      question: string;
      options?: string[];
      correctAnswer: string;
      explanation?: string;
      difficulty?: string;
    },
    order: number,
  ): Promise<void> {
    await this.db.query(
      `INSERT INTO quiz_questions (id, quiz_id, type, question, options, correct_answer, explanation, difficulty, "order")
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
      [
        uuidv4(),
        quizId,
        question.type,
        question.question,
        question.options ? JSON.stringify(question.options) : null,
        question.correctAnswer,
        question.explanation || null,
        question.difficulty || 'medium',
        order,
      ],
    );
  }

  private async sendQuizCompletionNotification(
    userId: string,
    score: number,
    correctCount: number,
    totalQuestions: number,
  ): Promise<void> {
    try {
      let title: string;
      let message: string;
      let type: 'success' | 'info' | 'warning' | 'reminder';

      if (score >= 90) {
        type = 'success';
        title = '🎉 Perfect Score!';
        message = `Amazing! You scored ${score.toFixed(0)}% (${correctCount}/${totalQuestions} correct). Keep up the great work!`;
      } else if (score >= 70) {
        type = 'success';
        title = '✅ Great Job!';
        message = `Well done! You scored ${score.toFixed(0)}% (${correctCount}/${totalQuestions} correct). You're making progress!`;
      } else if (score >= 50) {
        type = 'info';
        title = '📚 Good Effort!';
        message = `You scored ${score.toFixed(0)}% (${correctCount}/${totalQuestions} correct). Review the material and try again!`;
      } else {
        type = 'warning';
        title = '💪 Keep Practicing!';
        message = `You scored ${score.toFixed(0)}% (${correctCount}/${totalQuestions} correct). Don't give up, practice makes perfect!`;
      }

      await this.notificationsService.create({
        userId,
        type,
        title,
        message,
        link: '/quiz/history',
      });
    } catch (error) {
      this.logger.error(`Failed to send quiz completion notification: ${error.message}`);
    }
  }

  private checkAnswer(question: QuizQuestion, userAnswer: string): boolean {
    const normalize = (s: string) => s.toLowerCase().trim();
    return normalize(question.correctAnswer) === normalize(userAnswer);
  }

  private mapQuiz(row: unknown): Quiz {
    const r = row as Record<string, unknown>;
    return {
      id: r.id as string,
      userId: r.user_id as string,
      studySetId: r.study_set_id as string | null,
      title: r.title as string,
      description: r.description as string | null,
      questionCount: parseInt(String(r.question_count || 0), 10),
      timeLimit: r.time_limit as number | null,
      isPublic: r.is_public as boolean,
      createdAt: new Date(r.created_at as string),
      updatedAt: new Date(r.updated_at as string),
    };
  }

  private mapQuestion(row: unknown): QuizQuestion {
    const r = row as Record<string, unknown>;
    return {
      id: r.id as string,
      quizId: r.quiz_id as string,
      type: r.type as QuestionType,
      question: r.question as string,
      options: r.options
        ? typeof r.options === 'string'
          ? JSON.parse(r.options)
          : (r.options as string[])
        : null,
      correctAnswer: r.correct_answer as string,
      explanation: r.explanation as string | null,
      difficulty: r.difficulty as string,
      order: r.order as number,
    };
  }

  private mapAttempt(row: unknown): QuizAttempt {
    const r = row as Record<string, unknown>;
    return {
      id: r.id as string,
      quizId: r.quiz_id as string,
      userId: r.user_id as string,
      score: parseFloat(String(r.score || 0)),
      totalQuestions: r.total_questions as number,
      timeSpent: r.time_spent as number,
      completedAt: r.completed_at ? new Date(r.completed_at as string) : new Date(),
      createdAt: new Date(r.created_at as string),
    };
  }

  private mapAttemptAnswer(row: unknown): QuizAttemptAnswer {
    const r = row as Record<string, unknown>;
    return {
      id: r.id as string,
      attemptId: r.attempt_id as string,
      questionId: r.question_id as string,
      userAnswer: r.user_answer as string,
      isCorrect: r.is_correct as boolean,
      timeSpent: r.time_spent as number,
    };
  }
}

import { Global, Module } from '@nestjs/common';
import { RedisService } from './redis.service';

@Global()
@Module({
  providers: [RedisService],
  exports: [RedisService],
})
export class RedisModule {}

import { Injectable, Logger, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import Redis from 'ioredis';

@Injectable()
export class RedisService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(RedisService.name);
  private client: Redis;

  constructor(private readonly configService: ConfigService) {}

  async onModuleInit() {
    this.client = new Redis({
      host: this.configService.get<string>('REDIS_HOST'),
      port: this.configService.get<number>('REDIS_PORT'),
      password: this.configService.get<string>('REDIS_PASSWORD') || undefined,
      db: this.configService.get<number>('REDIS_DB', 0),
      retryStrategy: (times) => {
        if (times > 3) {
          this.logger.error('Redis connection failed after 3 retries');
          return null;
        }
        return Math.min(times * 200, 2000);
      },
    });

    this.client.on('error', (err) => {
      this.logger.error('Redis error', err);
    });

    this.client.on('connect', () => {
      this.logger.log('Redis connection established');
    });
  }

  async onModuleDestroy() {
    await this.client.quit();
    this.logger.log('Redis connection closed');
  }

  getClient(): Redis {
    return this.client;
  }

  async get(key: string): Promise<string | null> {
    return this.client.get(key);
  }

  async set(key: string, value: string, ttlSeconds?: number): Promise<void> {
    if (ttlSeconds) {
      await this.client.setex(key, ttlSeconds, value);
    } else {
      await this.client.set(key, value);
    }
  }

  async del(key: string): Promise<void> {
    await this.client.del(key);
  }

  async exists(key: string): Promise<boolean> {
    const result = await this.client.exists(key);
    return result === 1;
  }

  async expire(key: string, ttlSeconds: number): Promise<void> {
    await this.client.expire(key, ttlSeconds);
  }

  async ttl(key: string): Promise<number> {
    return this.client.ttl(key);
  }

  async incr(key: string): Promise<number> {
    return this.client.incr(key);
  }

  async decr(key: string): Promise<number> {
    return this.client.decr(key);
  }

  async hget(key: string, field: string): Promise<string | null> {
    return this.client.hget(key, field);
  }

  async hset(key: string, field: string, value: string): Promise<void> {
    await this.client.hset(key, field, value);
  }

  async hgetall(key: string): Promise<Record<string, string>> {
    return this.client.hgetall(key);
  }

  async hdel(key: string, field: string): Promise<void> {
    await this.client.hdel(key, field);
  }

  async lpush(key: string, value: string): Promise<void> {
    await this.client.lpush(key, value);
  }

  async rpush(key: string, value: string): Promise<void> {
    await this.client.rpush(key, value);
  }

  async lrange(key: string, start: number, stop: number): Promise<string[]> {
    return this.client.lrange(key, start, stop);
  }

  async sadd(key: string, member: string): Promise<void> {
    await this.client.sadd(key, member);
  }

  async smembers(key: string): Promise<string[]> {
    return this.client.smembers(key);
  }

  async sismember(key: string, member: string): Promise<boolean> {
    const result = await this.client.sismember(key, member);
    return result === 1;
  }

  async publish(channel: string, message: string): Promise<void> {
    await this.client.publish(channel, message);
  }

  async getJson<T>(key: string): Promise<T | null> {
    const value = await this.get(key);
    if (!value) return null;
    try {
      return JSON.parse(value) as T;
    } catch {
      return null;
    }
  }

  async setJson<T>(key: string, value: T, ttlSeconds?: number): Promise<void> {
    await this.set(key, JSON.stringify(value), ttlSeconds);
  }

  async healthCheck(): Promise<boolean> {
    try {
      await this.client.ping();
      return true;
    } catch {
      return false;
    }
  }
}

