export interface UploadOptions {
  contentType?: string;
  metadata?: Record<string, string>;
  folder?: string;
}

export interface FileInfo {
  key: string;
  size: number;
  lastModified: Date;
  contentType?: string;
}

@Injectable()
export class StorageService implements OnModuleInit {
  private readonly logger = new Logger(StorageService.name);
  private client: S3Client;
  private bucket: string;
  private publicUrl: string;

  constructor(private readonly configService: ConfigService) {}

  async onModuleInit() {
    const accountId = this.configService.get<string>('R2_ACCOUNT_ID');
    const accessKeyId = this.configService.get<string>('R2_ACCESS_KEY_ID');
    const secretAccessKey = this.configService.get<string>('R2_SECRET_ACCESS_KEY');
    this.bucket = this.configService.get<string>('R2_BUCKET_NAME', 'studyield');
    this.publicUrl = this.configService.get<string>('R2_PUBLIC_URL', '');

    this.client = new S3Client({
      region: 'auto',
      endpoint: `https://${accountId}.r2.cloudflarestorage.com`,
      credentials: {
        accessKeyId: accessKeyId || '',
        secretAccessKey: secretAccessKey || '',
      },
    });

    this.logger.log(
      `R2 Storage client initialized - Bucket: ${this.bucket}, Public URL: ${this.publicUrl || 'Not configured'}`,
    );
  }

  private generateKey(filename: string, folder?: string): string {
    const ext = filename.split('.').pop() || '';
    const key = `${uuidv4()}.${ext}`;
    return folder ? `${folder}/${key}` : key;
  }

  async upload(
    file: Buffer | Readable,
    filename: string,
    options?: UploadOptions,
  ): Promise<{ key: string; url: string }> {
    const key = this.generateKey(filename, options?.folder);

    if (file instanceof Buffer) {
      await this.client.send(
        new PutObjectCommand({
          Bucket: this.bucket,
          Key: key,
          Body: file,
          ContentType: options?.contentType,
          Metadata: options?.metadata,
        }),
      );
    } else {
      const upload = new Upload({
        client: this.client,
        params: {
          Bucket: this.bucket,
          Key: key,
          Body: file,
          ContentType: options?.contentType,
          Metadata: options?.metadata,
        },
      });

      await upload.done();
    }

    const url = this.publicUrl ? `${this.publicUrl}/${key}` : key;
    this.logger.debug(`File uploaded to R2 - Key: ${key}, Public URL: ${url}`);

    return { key, url };
  }

  async uploadWithKey(
    file: Buffer,
    key: string,
    options?: Omit<UploadOptions, 'folder'>,
  ): Promise<{ key: string; url: string }> {
    await this.client.send(
      new PutObjectCommand({
        Bucket: this.bucket,
        Key: key,
        Body: file,
        ContentType: options?.contentType,
        Metadata: options?.metadata,
      }),
    );

    const url = this.publicUrl ? `${this.publicUrl}/${key}` : key;
    this.logger.debug(`File uploaded with key: ${key}`);

    return { key, url };
  }

  async download(key: string): Promise<Buffer> {
    try {
      this.logger.debug(`Downloading file from bucket: ${this.bucket}, key: ${key}`);

      const response = await this.client.send(
        new GetObjectCommand({
          Bucket: this.bucket,
          Key: key,
        }),
      );

      const stream = response.Body as Readable;
      const chunks: Buffer[] = [];

      for await (const chunk of stream) {
        chunks.push(Buffer.from(chunk));
      }

      const buffer = Buffer.concat(chunks);
      this.logger.debug(`File downloaded successfully: ${key}, size: ${buffer.length} bytes`);
      return buffer;
    } catch (error) {
      this.logger.error(
        `Failed to download file from R2. Bucket: ${this.bucket}, Key: ${key}`,
        error,
      );
      throw new Error(`Failed to download file from storage: ${error.message}`);
    }
  }

  async getStream(key: string): Promise<Readable> {
    const response = await this.client.send(
      new GetObjectCommand({
        Bucket: this.bucket,
        Key: key,
      }),
    );

    return response.Body as Readable;
  }

  async delete(key: string): Promise<void> {
    await this.client.send(
      new DeleteObjectCommand({
        Bucket: this.bucket,
        Key: key,
      }),
    );
    this.logger.debug(`File deleted: ${key}`);
  }

  async deleteMany(keys: string[]): Promise<void> {
    await Promise.all(keys.map((key) => this.delete(key)));
    this.logger.debug(`${keys.length} files deleted`);
  }

  async exists(key: string): Promise<boolean> {
    try {
      await this.client.send(
        new HeadObjectCommand({
          Bucket: this.bucket,
          Key: key,
        }),
      );
      return true;
    } catch {
      return false;
    }
  }

  async getInfo(key: string): Promise<FileInfo | null> {
    try {
      const response = await this.client.send(
        new HeadObjectCommand({
          Bucket: this.bucket,
          Key: key,
        }),
      );

      return {
        key,
        size: response.ContentLength || 0,
        lastModified: response.LastModified || new Date(),
        contentType: response.ContentType,
      };
    } catch {
      return null;
    }
  }

  async list(prefix?: string, maxKeys = 1000): Promise<FileInfo[]> {
    const response = await this.client.send(
      new ListObjectsV2Command({
        Bucket: this.bucket,
        Prefix: prefix,
        MaxKeys: maxKeys,
      }),
    );

    return (response.Contents || []).map((obj) => ({
      key: obj.Key || '',
      size: obj.Size || 0,
      lastModified: obj.LastModified || new Date(),
    }));
  }

  async copy(sourceKey: string, destinationKey: string): Promise<void> {
    await this.client.send(
      new CopyObjectCommand({
        Bucket: this.bucket,
        CopySource: `${this.bucket}/${sourceKey}`,
        Key: destinationKey,
      }),
    );
    this.logger.debug(`File copied: ${sourceKey} -> ${destinationKey}`);
  }

  async move(sourceKey: string, destinationKey: string): Promise<void> {
    await this.copy(sourceKey, destinationKey);
    await this.delete(sourceKey);
    this.logger.debug(`File moved: ${sourceKey} -> ${destinationKey}`);
  }

  async getSignedUploadUrl(key: string, contentType: string, expiresIn = 3600): Promise<string> {
    const command = new PutObjectCommand({
      Bucket: this.bucket,
      Key: key,
      ContentType: contentType,
    });

    return getSignedUrl(this.client, command, { expiresIn });
  }

  async getSignedDownloadUrl(key: string, expiresIn = 3600): Promise<string> {
    const command = new GetObjectCommand({
      Bucket: this.bucket,
      Key: key,
    });

    return getSignedUrl(this.client, command, { expiresIn });
  }

  getPublicUrl(key: string): string {
    return this.publicUrl ? `${this.publicUrl}/${key}` : key;
  }

  /**
   * Extract storage key from public URL
   * If the URL starts with the public URL prefix, remove it to get the key
   * Otherwise, return the URL as-is (assuming it's already a key)
   */
  extractKeyFromUrl(url: string): string {
    if (this.publicUrl && url.startsWith(this.publicUrl)) {
      return url.replace(`${this.publicUrl}/`, '');
    }

    // If it's a full URL but not our public URL, extract path after domain
    if (url.startsWith('http://') || url.startsWith('https://')) {
      const urlObj = new URL(url);
      return urlObj.pathname.startsWith('/') ? urlObj.pathname.substring(1) : urlObj.pathname;
    }

    // Already a key
    return url;
  }

  async healthCheck(): Promise<boolean> {
    try {
      await this.client.send(
        new ListObjectsV2Command({
          Bucket: this.bucket,
          MaxKeys: 1,
        }),
      );
      return true;
    } catch {
      return false;
    }
  }
}

export * from './subscription.module';
export * from './subscription.service';
export * from './subscription.controller';

import {
  Controller,
  Post,
  Req,
  Headers,
  RawBodyRequest,
  BadRequestException,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { ApiTags, ApiExcludeEndpoint } from '@nestjs/swagger';
import Stripe from 'stripe';
import { Request } from 'express';
import { SubscriptionService } from './subscription.service';
import { Public } from '../../common';

@ApiTags('Webhooks')
@Controller('webhooks')
export class StripeWebhookController {
  private stripe: Stripe;
  private webhookSecret: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly subscriptionService: SubscriptionService,
  ) {
    this.stripe = new Stripe(this.configService.get<string>('STRIPE_SECRET_KEY') || '', {
      apiVersion: '2024-12-18.acacia' as Stripe.LatestApiVersion,
    });
    this.webhookSecret = this.configService.get<string>('STRIPE_WEBHOOK_SECRET', '');
  }

  @Public()
  @Post('stripe')
  @ApiExcludeEndpoint()
  async handleStripeWebhook(
    @Req() req: RawBodyRequest<Request>,
    @Headers('stripe-signature') signature: string,
  ) {
    if (!req.rawBody) {
      throw new BadRequestException('Missing raw body');
    }

    let event: Stripe.Event;

    try {
      event = this.stripe.webhooks.constructEvent(req.rawBody, signature, this.webhookSecret);
    } catch (err) {
      throw new BadRequestException(
        `Webhook signature verification failed: ${(err as Error).message}`,
      );
    }

    await this.subscriptionService.handleWebhook(event);

    return { received: true };
  }
}

import { Controller, Get, Post, Body, Query, UseGuards } from '@nestjs/common';
import { ApiTags, ApiOperation, ApiBearerAuth } from '@nestjs/swagger';
import { SubscriptionService } from './subscription.service';
import { JwtAuthGuard } from '../../common/guards/jwt-auth.guard';
import { CurrentUser, JwtPayload } from '../../common';

@ApiTags('Subscription')
@Controller('subscription')
@UseGuards(JwtAuthGuard)
@ApiBearerAuth()
export class SubscriptionController {
  constructor(private readonly subscriptionService: SubscriptionService) {}

  @Get()
  @ApiOperation({ summary: 'Get current subscription' })
  async getSubscription(@CurrentUser() user: JwtPayload) {
    return this.subscriptionService.getOrCreateSubscription(user.sub, user.email);
  }

  @Post('checkout')
  @ApiOperation({ summary: 'Create checkout session' })
  async createCheckout(
    @CurrentUser() user: JwtPayload,
    @Body() body: { plan: 'monthly' | 'yearly' },
  ) {
    const url = await this.subscriptionService.createCheckoutSession(
      user.sub,
      user.email,
      body.plan,
    );
    return { url };
  }

  @Post('portal')
  @ApiOperation({ summary: 'Create billing portal session' })
  async createPortal(@CurrentUser() user: JwtPayload) {
    const url = await this.subscriptionService.createPortalSession(user.sub, user.email);
    return { url };
  }

  @Post('cancel')
  @ApiOperation({ summary: 'Cancel subscription' })
  async cancel(@CurrentUser() user: JwtPayload) {
    await this.subscriptionService.cancelSubscription(user.sub);
    return { message: 'Subscription will be canceled at period end' };
  }

  @Get('verify-session')
  @ApiOperation({ summary: 'Verify checkout session' })
  async verifySession(@Query('session_id') sessionId: string) {
    return this.subscriptionService.verifyCheckoutSession(sessionId);
  }

  @Get('usage')
  @ApiOperation({ summary: 'Get usage for all features' })
  async getUsage(@CurrentUser() user: JwtPayload) {
    const features = ['ai_requests', 'study_sets', 'flashcards'];
    const usage: Record<string, { allowed: boolean; remaining: number }> = {};

    for (const feature of features) {
      usage[feature] = await this.subscriptionService.checkUsage(user.sub, feature);
    }

    return usage;
  }
}

import { Global, Module } from '@nestjs/common';
import { SubscriptionService } from './subscription.service';
import { SubscriptionController } from './subscription.controller';
import { StripeWebhookController } from './stripe-webhook.controller';

@Global()
@Module({
  controllers: [SubscriptionController, StripeWebhookController],
  providers: [SubscriptionService],
  exports: [SubscriptionService],
})
export class SubscriptionModule {}

import {
  Injectable,
  Logger,
  BadRequestException,
  ForbiddenException,
  OnModuleInit,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import Stripe from 'stripe';
import { v4 as uuidv4 } from 'uuid';
import { DatabaseService } from '../database/database.service';

export interface Subscription {
  id: string;
  userId: string;
  stripeCustomerId: string;
  stripeSubscriptionId: string | null;
  plan: 'free' | 'monthly' | 'yearly';
  status: 'active' | 'canceled' | 'past_due' | 'trialing';
  currentPeriodStart: Date | null;
  currentPeriodEnd: Date | null;
  cancelAtPeriodEnd: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export interface UsageRecord {
  userId: string;
  feature: string;
  count: number;
  limit: number;
  resetAt: Date;
}

const PLAN_LIMITS = {
  free: { ai_requests: 10, study_sets: 3, flashcards: 50, storage_bytes: 50 * 1024 * 1024 },
  monthly: {
    ai_requests: -1,
    study_sets: -1,
    flashcards: -1,
    storage_bytes: 10 * 1024 * 1024 * 1024,
  },
  yearly: {
    ai_requests: -1,
    study_sets: -1,
    flashcards: -1,
    storage_bytes: 10 * 1024 * 1024 * 1024,
  },
};

@Injectable()
export class SubscriptionService implements OnModuleInit {
  private readonly logger = new Logger(SubscriptionService.name);
  private stripe: Stripe;
  private readonly monthlyPriceId: string;
  private readonly yearlyPriceId: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly db: DatabaseService,
  ) {
    const secretKey = this.configService.get<string>('STRIPE_SECRET_KEY');
    this.stripe = new Stripe(secretKey || '', {
      apiVersion: '2024-12-18.acacia' as Stripe.LatestApiVersion,
    });
    this.monthlyPriceId = this.configService.get<string>('STRIPE_PRICE_ID_MONTHLY', '');
    this.yearlyPriceId = this.configService.get<string>('STRIPE_PRICE_ID_YEARLY', '');
  }

  async onModuleInit() {
    try {
      await this.db.query(`
        CREATE TABLE IF NOT EXISTS subscriptions (
          id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
          user_id UUID UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,
          stripe_customer_id VARCHAR(255) NOT NULL,
          stripe_subscription_id VARCHAR(255),
          plan VARCHAR(50) DEFAULT 'free',
          status VARCHAR(50) DEFAULT 'active',
          current_period_start TIMESTAMP WITH TIME ZONE,
          current_period_end TIMESTAMP WITH TIME ZONE,
          cancel_at_period_end BOOLEAN DEFAULT FALSE,
          created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
          updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
        )
      `);
      await this.db.query(`
        CREATE TABLE IF NOT EXISTS usage_records (
          user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
          feature VARCHAR(100) NOT NULL,
          count INTEGER DEFAULT 0,
          reset_at TIMESTAMP WITH TIME ZONE NOT NULL,
          PRIMARY KEY (user_id, feature)
        )
      `);
      this.logger.log('Subscription tables verified');
    } catch (err) {
      this.logger.warn(`Could not verify subscription tables: ${(err as Error).message}`);
    }
  }

  async getOrCreateSubscription(userId: string, email: string): Promise<Subscription> {
    let subscription = await this.findByUserId(userId);

    if (!subscription) {
      let customerId = `local_${userId}`;

      // Only create Stripe customer if key is configured
      const secretKey = this.configService.get<string>('STRIPE_SECRET_KEY');
      if (secretKey) {
        try {
          const customer = await this.stripe.customers.create({ email, metadata: { userId } });
          customerId = customer.id;
        } catch (err) {
          this.logger.warn(
            `Stripe customer creation failed, using local ID: ${(err as Error).message}`,
          );
        }
      }

      const id = uuidv4();
      try {
        await this.db.query(
          `INSERT INTO subscriptions (id, user_id, stripe_customer_id, plan, status, created_at, updated_at)
           VALUES ($1, $2, $3, 'free', 'active', $4, $5)
           ON CONFLICT (user_id) DO NOTHING`,
          [id, userId, customerId, new Date(), new Date()],
        );
      } catch (err) {
        this.logger.warn(
          `Subscription insert failed (may already exist): ${(err as Error).message}`,
        );
      }

      subscription = await this.findByUserId(userId);
    }

    return subscription!;
  }

  async createCheckoutSession(
    userId: string,
    email: string,
    plan: 'monthly' | 'yearly',
  ): Promise<string> {
    const subscription = await this.getOrCreateSubscription(userId, email);

    const secretKey = this.configService.get<string>('STRIPE_SECRET_KEY');
    const priceId = plan === 'monthly' ? this.monthlyPriceId : this.yearlyPriceId;

    // Check if Stripe is properly configured (not placeholder values)
    const isPlaceholder =
      !secretKey ||
      secretKey.includes('your-') ||
      !priceId ||
      priceId.includes('_id') ||
      priceId.length < 20;

    if (isPlaceholder) {
      throw new BadRequestException(
        'Payment system is not configured yet. All features are currently free!',
      );
    }

    // Verify customer exists in Stripe, recreate if needed
    let customerId = subscription.stripeCustomerId;

    try {
      // Check if customer exists in Stripe
      if (customerId.startsWith('cus_')) {
        try {
          await this.stripe.customers.retrieve(customerId);
        } catch (err) {
          // Customer not found in Stripe, recreate
          this.logger.warn(`Customer ${customerId} not found, recreating`);
          const newCustomer = await this.stripe.customers.create({
            email,
            metadata: { userId },
          });
          customerId = newCustomer.id;
          await this.db.query(
            `UPDATE subscriptions SET stripe_customer_id = $1, updated_at = $2 WHERE user_id = $3`,
            [customerId, new Date(), userId],
          );
        }
      } else if (customerId.startsWith('local_')) {
        // Create new Stripe customer
        const customer = await this.stripe.customers.create({
          email,
          metadata: { userId },
        });
        customerId = customer.id;
        await this.db.query(
          `UPDATE subscriptions SET stripe_customer_id = $1, updated_at = $2 WHERE user_id = $3`,
          [customerId, new Date(), userId],
        );
      }
    } catch (err) {
      this.logger.error(`Stripe customer setup failed: ${(err as Error).message}`);
      throw new BadRequestException('Unable to initialize payment. Please try again.');
    }

    const sessionParams: Stripe.Checkout.SessionCreateParams = {
      customer: customerId,
      mode: 'subscription',
      line_items: [{ price: priceId, quantity: 1 }],
      success_url: `${this.configService.get('FRONTEND_URL')}/dashboard/subscription/success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${this.configService.get('FRONTEND_URL')}/dashboard/subscription`,
      allow_promotion_codes: true,
      metadata: { userId, plan },
    };

    if (plan === 'yearly') {
      sessionParams.subscription_data = { trial_period_days: 7 };
    }

    const session = await this.stripe.checkout.sessions.create(sessionParams);

    return session.url!;
  }

  async createPortalSession(userId: string, email: string): Promise<string> {
    const subscription = await this.getOrCreateSubscription(userId, email);

    const secretKey = this.configService.get<string>('STRIPE_SECRET_KEY');
    if (!secretKey) {
      throw new BadRequestException(
        'Payment system is not configured yet. All features are currently free!',
      );
    }

    // If customer ID is a local fallback, create a real Stripe customer first
    let customerId = subscription.stripeCustomerId;
    if (customerId.startsWith('local_')) {
      try {
        const customer = await this.stripe.customers.create({ email, metadata: { userId } });
        customerId = customer.id;
        await this.db.query(
          `UPDATE subscriptions SET stripe_customer_id = $1, updated_at = $2 WHERE user_id = $3`,
          [customerId, new Date(), userId],
        );
      } catch (err) {
        this.logger.error(`Failed to create Stripe customer for portal: ${(err as Error).message}`);
        throw new BadRequestException('Unable to access billing portal. Please try again later.');
      }
    }

    const session = await this.stripe.billingPortal.sessions.create({
      customer: customerId,
      return_url: `${this.configService.get('FRONTEND_URL')}/dashboard/subscription/manage`,
    });

    return session.url;
  }

  async cancelSubscription(userId: string): Promise<void> {
    const subscription = await this.findByUserId(userId);
    if (!subscription?.stripeSubscriptionId)
      throw new BadRequestException('No active subscription');

    await this.stripe.subscriptions.update(subscription.stripeSubscriptionId, {
      cancel_at_period_end: true,
    });

    await this.db.query(
      `UPDATE subscriptions SET cancel_at_period_end = true, updated_at = $1 WHERE user_id = $2`,
      [new Date(), userId],
    );
  }

  async handleWebhook(event: Stripe.Event): Promise<void> {
    switch (event.type) {
      case 'checkout.session.completed': {
        const session = event.data.object as Stripe.Checkout.Session;
        await this.handleCheckoutComplete(session);
        break;
      }
      case 'customer.subscription.updated':
      case 'customer.subscription.deleted': {
        const subscription = event.data.object as Stripe.Subscription;
        await this.syncSubscription(subscription);
        break;
      }
      case 'invoice.payment_failed': {
        const invoice = event.data.object as Stripe.Invoice;
        await this.handlePaymentFailed(invoice);
        break;
      }
    }
  }

  async checkUsage(
    userId: string,
    feature: string,
  ): Promise<{ allowed: boolean; remaining: number }> {
    const subscription = await this.findByUserId(userId);
    const plan = subscription?.plan || 'free';
    const limit = PLAN_LIMITS[plan][feature as keyof (typeof PLAN_LIMITS)['free']] || 0;

    if (limit === -1) return { allowed: true, remaining: -1 };

    const usage = await this.getUsage(userId, feature);
    const remaining = Math.max(0, limit - usage);

    return { allowed: remaining > 0, remaining };
  }

  async incrementUsage(userId: string, feature: string, amount = 1): Promise<void> {
    const resetAt = new Date();
    resetAt.setDate(1);
    resetAt.setMonth(resetAt.getMonth() + 1);

    await this.db.query(
      `INSERT INTO usage_records (user_id, feature, count, reset_at)
       VALUES ($1, $2, $3, $4)
       ON CONFLICT (user_id, feature)
       DO UPDATE SET count = CASE
         WHEN usage_records.reset_at <= NOW() THEN $3
         ELSE usage_records.count + $3
       END,
       reset_at = CASE
         WHEN usage_records.reset_at <= NOW() THEN $4
         ELSE usage_records.reset_at
       END`,
      [userId, feature, amount, resetAt],
    );
  }

  async isPro(userId: string): Promise<boolean> {
    const subscription = await this.findByUserId(userId);
    const plan = subscription?.plan || 'free';
    return plan === 'monthly' || plan === 'yearly';
  }

  async checkAndIncrementUsage(userId: string, feature: string, amount = 1): Promise<void> {
    const { allowed, remaining } = await this.checkUsage(userId, feature);
    if (!allowed || (remaining !== -1 && remaining < amount)) {
      throw new ForbiddenException({
        message: `You've reached your free plan limit for ${feature.replace(/_/g, ' ')}`,
        upgrade: true,
        limit: true,
        feature,
      });
    }
    await this.incrementUsage(userId, feature, amount);
  }

  async checkStorageQuota(userId: string, additionalBytes: number): Promise<void> {
    const subscription = await this.findByUserId(userId);
    const plan = subscription?.plan || 'free';
    const limitBytes = PLAN_LIMITS[plan].storage_bytes;

    // Get current storage usage from documents
    const result = await this.db.queryOne<{ total: string }>(
      `SELECT COALESCE(SUM(file_size), 0) as total FROM documents WHERE user_id = $1`,
      [userId],
    );
    const currentUsage = parseInt(result?.total || '0', 10);

    if (currentUsage + additionalBytes > limitBytes) {
      const limitLabel = plan === 'free' ? '50MB' : '10GB';
      throw new ForbiddenException({
        message: `Storage limit reached (${limitLabel}). Upgrade for more storage.`,
        upgrade: true,
        limit: true,
        feature: 'storage',
      });
    }
  }

  async verifyCheckoutSession(sessionId: string): Promise<{ status: string; plan: string }> {
    const session = await this.stripe.checkout.sessions.retrieve(sessionId);
    const plan = session.metadata?.plan || 'free';
    const paymentStatus = session.payment_status;

    // Activate the plan in DB (works without webhooks)
    if (session.status === 'complete') {
      await this.handleCheckoutComplete(session);
    }

    return {
      status:
        paymentStatus === 'paid' || paymentStatus === 'no_payment_required'
          ? 'success'
          : paymentStatus === 'unpaid'
            ? 'pending'
            : paymentStatus,
      plan,
    };
  }

  async findByUserId(userId: string): Promise<Subscription | null> {
    const result = await this.db.queryOne<Subscription>(
      'SELECT * FROM subscriptions WHERE user_id = $1',
      [userId],
    );
    return result ? this.mapSubscription(result) : null;
  }

  private async getUsage(userId: string, feature: string): Promise<number> {
    const result = await this.db.queryOne<{ count: string }>(
      `SELECT count FROM usage_records WHERE user_id = $1 AND feature = $2 AND reset_at > NOW()`,
      [userId, feature],
    );
    return parseInt(result?.count || '0', 10);
  }

  private async handleCheckoutComplete(session: Stripe.Checkout.Session): Promise<void> {
    const userId = session.metadata?.userId;
    const plan = session.metadata?.plan as 'monthly' | 'yearly';
    if (!userId) return;

    const stripeSubscription = await this.stripe.subscriptions.retrieve(
      session.subscription as string,
    );

    await this.db.query(
      `UPDATE subscriptions SET
        stripe_subscription_id = $1,
        plan = $2,
        status = 'active',
        current_period_start = $3,
        current_period_end = $4,
        cancel_at_period_end = false,
        updated_at = $5
       WHERE user_id = $6`,
      [
        stripeSubscription.id,
        plan,
        new Date(stripeSubscription.current_period_start * 1000),
        new Date(stripeSubscription.current_period_end * 1000),
        new Date(),
        userId,
      ],
    );

    this.logger.log(`Subscription activated for user ${userId}: ${plan}`);
  }

  private async syncSubscription(stripeSubscription: Stripe.Subscription): Promise<void> {
    const stripeStatus = stripeSubscription.status;
    const status =
      stripeStatus === 'active' || stripeStatus === 'trialing'
        ? 'active'
        : stripeStatus === 'canceled'
          ? 'canceled'
          : 'past_due';

    await this.db.query(
      `UPDATE subscriptions SET
        status = $1,
        current_period_start = $2,
        current_period_end = $3,
        cancel_at_period_end = $4,
        updated_at = $5
       WHERE stripe_subscription_id = $6`,
      [
        status,
        new Date(stripeSubscription.current_period_start * 1000),
        new Date(stripeSubscription.current_period_end * 1000),
        stripeSubscription.cancel_at_period_end,
        new Date(),
        stripeSubscription.id,
      ],
    );
  }

  private async handlePaymentFailed(invoice: Stripe.Invoice): Promise<void> {
    if (invoice.subscription) {
      await this.db.query(
        `UPDATE subscriptions SET status = 'past_due', updated_at = $1 WHERE stripe_subscription_id = $2`,
        [new Date(), invoice.subscription],
      );
    }
  }

  private mapSubscription(row: unknown): Subscription {
    const r = row as Record<string, unknown>;
    return {
      id: r.id as string,
      userId: r.user_id as string,
      stripeCustomerId: r.stripe_customer_id as string,
      stripeSubscriptionId: r.stripe_subscription_id as string | null,
      plan: r.plan as Subscription['plan'],
      status: r.status as Subscription['status'],
      currentPeriodStart: r.current_period_start
        ? new Date(r.current_period_start as string)
        : null,
      currentPeriodEnd: r.current_period_end ? new Date(r.current_period_end as string) : null,
      cancelAtPeriodEnd: r.cancel_at_period_end as boolean,
      createdAt: new Date(r.created_at as string),
      updatedAt: new Date(r.updated_at as string),
    };
  }
}

