import { useRef, useCallback } from 'react';
import { motion } from 'framer-motion';
import { extractClozeBlanks } from '@/types';
import { Brackets } from 'lucide-react';
import { useTranslation } from 'react-i18next';

interface ClozeEditorProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
}

export function ClozeEditor({ value, onChange, placeholder }: ClozeEditorProps) {
  const { t } = useTranslation();
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const blanks = extractClozeBlanks(value);

  const insertBlank = useCallback(() => {
    const textarea = textareaRef.current;
    if (!textarea) return;
    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selectedText = value.slice(start, end);
    const insertion = selectedText ? `{{${selectedText}}}` : '{{}}';
    const newValue = value.slice(0, start) + insertion + value.slice(end);
    onChange(newValue);
    // Set cursor position inside the braces if no selection
    setTimeout(() => {
      const cursorPos = selectedText ? start + insertion.length : start + 2;
      textarea.setSelectionRange(cursorPos, cursorPos);
      textarea.focus();
    }, 0);
  }, [value, onChange]);

  return (
    <div className="space-y-3">
      {/* Toolbar */}
      <div className="flex items-center gap-2">
        <button
          type="button"
          onClick={insertBlank}
          className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium bg-green-500/10 text-green-600 dark:text-green-400 rounded-lg hover:bg-green-500/20 transition-colors"
        >
          <Brackets className="w-3.5 h-3.5" />
          {t('clozeEditor.insertBlank')}
        </button>
        <span className="text-[10px] text-muted-foreground">
          {t('clozeEditor.wrapHint', { braces: '{{...}}' })}
        </span>
      </div>

      {/* Textarea */}
      <textarea
        ref={textareaRef}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder || t('clozeEditor.placeholder')}
        rows={4}
        className="w-full px-3 py-2.5 text-sm bg-background border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500/20 focus:border-green-500 resize-y font-mono"
        style={{ minHeight: '80px' }}
        onInput={(e) => {
          const t = e.target as HTMLTextAreaElement;
          t.style.height = 'auto';
          t.style.height = Math.max(80, t.scrollHeight) + 'px';
        }}
      />

      {/* Live preview */}
      {blanks.length > 0 && (
        <motion.div
          initial={{ opacity: 0, height: 0 }}
          animate={{ opacity: 1, height: 'auto' }}
          className="p-3 bg-muted/30 border border-border/50 rounded-lg"
        >
          <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">
            {t('clozeEditor.preview')} ({blanks.length !== 1 ? t('clozeEditor.blanksCountPlural', { count: blanks.length }) : t('clozeEditor.blanksCount', { count: blanks.length })})
          </p>
          <p className="text-sm leading-relaxed">
            {value.split(/(\{\{.+?\}\})/g).map((part, i) => {
              if (part.startsWith('{{') && part.endsWith('}}')) {
                return (
                  <span
                    key={i}
                    className="inline-block px-2 py-0.5 mx-0.5 bg-green-500/10 border border-green-500/30 rounded text-green-600 dark:text-green-400 font-medium"
                  >
                    {part.slice(2, -2)}
                  </span>
                );
              }
              return <span key={i}>{part}</span>;
            })}
          </p>
        </motion.div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { renderClozeWithBlanks } from '@/types';
import { Eye } from 'lucide-react';

interface ClozeRendererProps {
  text: string;
  onAllRevealed?: () => void;
}

export function ClozeRenderer({ text, onAllRevealed }: ClozeRendererProps) {
  const [revealedIndices, setRevealedIndices] = useState<Set<number>>(new Set());
  const { segments } = renderClozeWithBlanks(text, revealedIndices);
  const totalBlanks = segments.filter((s) => s.isBlank).length;
  const revealedCount = revealedIndices.size;

  const handleReveal = (index: number) => {
    const newSet = new Set(revealedIndices);
    newSet.add(index);
    setRevealedIndices(newSet);
    if (newSet.size === totalBlanks) {
      onAllRevealed?.();
    }
  };

  const revealAll = () => {
    const all = new Set<number>();
    segments.forEach((s) => { if (s.isBlank) all.add(s.index); });
    setRevealedIndices(all);
    onAllRevealed?.();
  };

  return (
    <div className="space-y-4">
      {/* Cloze text */}
      <div className="text-lg leading-relaxed text-center px-4">
        {segments.map((seg, i) => {
          if (!seg.isBlank) {
            return <span key={i}>{seg.text}</span>;
          }

          const isRevealed = revealedIndices.has(seg.index);

          return (
            <AnimatePresence mode="wait" key={i}>
              {isRevealed ? (
                <motion.span
                  initial={{ opacity: 0, scale: 0.8 }}
                  animate={{ opacity: 1, scale: 1 }}
                  className="inline-block px-2 py-0.5 mx-0.5 bg-green-500/15 border border-green-500/30 rounded-md text-green-600 dark:text-green-400 font-semibold"
                >
                  {seg.answer}
                </motion.span>
              ) : (
                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={() => handleReveal(seg.index)}
                  className="inline-block px-3 py-0.5 mx-0.5 bg-muted border-2 border-dashed border-green-500/40 rounded-md text-muted-foreground hover:border-green-500 hover:bg-green-500/5 transition-colors cursor-pointer min-w-[60px] text-center"
                >
                  ?
                </motion.button>
              )}
            </AnimatePresence>
          );
        })}
      </div>

      {/* Progress + Reveal All */}
      <div className="flex items-center justify-between px-4">
        <span className="text-xs text-muted-foreground">
          {revealedCount} / {totalBlanks} revealed
        </span>
        {revealedCount < totalBlanks && (
          <button
            onClick={revealAll}
            className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors"
          >
            <Eye className="w-3.5 h-3.5" />
            Reveal all
          </button>
        )}
      </div>
    </div>
  );
}

