import { Component, type ErrorInfo, type ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    console.error('ErrorBoundary caught an error:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      if (this.props.fallback) {
        return this.props.fallback;
      }

      return (
        <div className="min-h-screen flex items-center justify-center bg-background p-4">
          <div className="max-w-md w-full text-center space-y-4">
            <div className="w-16 h-16 mx-auto rounded-full bg-red-500/10 flex items-center justify-center">
              <svg
                className="w-8 h-8 text-red-500"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
                strokeWidth={2}
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z"
                />
              </svg>
            </div>
            <h2 className="text-xl font-semibold text-foreground">
              Something went wrong
            </h2>
            <p className="text-sm text-muted-foreground">
              An unexpected error occurred. Please try refreshing the page.
            </p>
            {this.state.error && (
              <pre className="mt-2 p-3 bg-muted rounded-lg text-xs text-left text-muted-foreground overflow-auto max-h-32">
                {this.state.error.message}
              </pre>
            )}
            <button
              onClick={() => window.location.reload()}
              className="inline-flex items-center justify-center px-4 py-2 text-sm font-medium rounded-lg bg-primary text-primary-foreground hover:bg-primary/90 transition-colors"
            >
              Refresh Page
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import { useState, useRef, useCallback, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import type { OcclusionRegion } from '@/types';
import { Trash2, MousePointer2, Square, RotateCcw, Upload } from 'lucide-react';
import { useTranslation } from 'react-i18next';

interface ImageOcclusionEditorProps {
  imageUrl: string;
  regions: OcclusionRegion[];
  onRegionsChange: (regions: OcclusionRegion[]) => void;
  onImageChange?: (url: string) => void;
}

type Tool = 'draw' | 'select';

let regionIdCounter = 0;

export function ImageOcclusionEditor({ imageUrl, regions, onRegionsChange, onImageChange }: ImageOcclusionEditorProps) {
  const { t } = useTranslation();
  const svgRef = useRef<SVGSVGElement>(null);
  const [tool, setTool] = useState<Tool>('draw');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [drawStart, setDrawStart] = useState<{ x: number; y: number } | null>(null);
  const [drawCurrent, setDrawCurrent] = useState<{ x: number; y: number } | null>(null);
  const [editLabel, setEditLabel] = useState('');
  const fileRef = useRef<HTMLInputElement>(null);

  const getRelativePos = useCallback((e: React.MouseEvent<SVGSVGElement>): { x: number; y: number } => {
    const svg = svgRef.current;
    if (!svg) return { x: 0, y: 0 };
    const rect = svg.getBoundingClientRect();
    return {
      x: ((e.clientX - rect.left) / rect.width) * 100,
      y: ((e.clientY - rect.top) / rect.height) * 100,
    };
  }, []);

  const handleMouseDown = useCallback((e: React.MouseEvent<SVGSVGElement>) => {
    if (tool !== 'draw') return;
    const pos = getRelativePos(e);
    setIsDrawing(true);
    setDrawStart(pos);
    setDrawCurrent(pos);
  }, [tool, getRelativePos]);

  const handleMouseMove = useCallback((e: React.MouseEvent<SVGSVGElement>) => {
    if (!isDrawing) return;
    setDrawCurrent(getRelativePos(e));
  }, [isDrawing, getRelativePos]);

  const handleMouseUp = useCallback(() => {
    if (!isDrawing || !drawStart || !drawCurrent) {
      setIsDrawing(false);
      return;
    }

    const x = Math.min(drawStart.x, drawCurrent.x);
    const y = Math.min(drawStart.y, drawCurrent.y);
    const width = Math.abs(drawCurrent.x - drawStart.x);
    const height = Math.abs(drawCurrent.y - drawStart.y);

    if (width > 2 && height > 2) {
      const newRegion: OcclusionRegion = {
        id: `occ-${++regionIdCounter}-${Date.now()}`,
        x, y, width, height,
        label: `${t('imageOcclusion.region')} ${regions.length + 1}`,
      };
      onRegionsChange([...regions, newRegion]);
      setSelectedId(newRegion.id);
      setEditLabel(newRegion.label || '');
    }

    setIsDrawing(false);
    setDrawStart(null);
    setDrawCurrent(null);
  }, [isDrawing, drawStart, drawCurrent, regions, onRegionsChange, t]);

  const deleteRegion = useCallback((id: string) => {
    onRegionsChange(regions.filter((r) => r.id !== id));
    if (selectedId === id) setSelectedId(null);
  }, [regions, onRegionsChange, selectedId]);

  const updateLabel = (id: string, label: string) => {
    onRegionsChange(regions.map((r) => r.id === id ? { ...r, label } : r));
  };

  const clearAll = () => {
    onRegionsChange([]);
    setSelectedId(null);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !onImageChange) return;
    const reader = new FileReader();
    reader.onload = () => {
      onImageChange(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  // Handle keyboard
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Delete' || e.key === 'Backspace') {
        if (selectedId && document.activeElement?.tagName !== 'INPUT') {
          deleteRegion(selectedId);
        }
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [selectedId, deleteRegion]);

  if (!imageUrl) {
    return (
      <div
        onClick={() => fileRef.current?.click()}
        className="border-2 border-dashed border-border rounded-xl p-12 text-center cursor-pointer hover:border-green-500/30 hover:bg-green-500/5 transition-all"
      >
        <input
          ref={fileRef}
          type="file"
          accept="image/*"
          onChange={handleImageUpload}
          className="hidden"
        />
        <Upload className="w-10 h-10 text-muted-foreground mx-auto mb-3" />
        <p className="text-sm font-medium">{t('imageOcclusion.uploadImage')}</p>
        <p className="text-xs text-muted-foreground mt-1">{t('imageOcclusion.imageFormats')}</p>
      </div>
    );
  }

  const drawingRect = isDrawing && drawStart && drawCurrent ? {
    x: Math.min(drawStart.x, drawCurrent.x),
    y: Math.min(drawStart.y, drawCurrent.y),
    width: Math.abs(drawCurrent.x - drawStart.x),
    height: Math.abs(drawCurrent.y - drawStart.y),
  } : null;

  return (
    <div className="space-y-3">
      {/* Toolbar */}
      <div className="flex items-center gap-2">
        <button
          type="button"
          onClick={() => setTool('draw')}
          className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg transition-colors ${
            tool === 'draw' ? 'bg-green-500/10 text-green-600 border border-green-500/30' : 'bg-muted text-muted-foreground hover:text-foreground'
          }`}
        >
          <Square className="w-3.5 h-3.5" />
          {t('imageOcclusion.draw')}
        </button>
        <button
          type="button"
          onClick={() => setTool('select')}
          className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg transition-colors ${
            tool === 'select' ? 'bg-green-500/10 text-green-600 border border-green-500/30' : 'bg-muted text-muted-foreground hover:text-foreground'
          }`}
        >
          <MousePointer2 className="w-3.5 h-3.5" />
          {t('imageOcclusion.select')}
        </button>
        <div className="flex-1" />
        {selectedId && (
          <button
            type="button"
            onClick={() => deleteRegion(selectedId)}
            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-red-500 bg-red-500/10 rounded-lg hover:bg-red-500/20 transition-colors"
          >
            <Trash2 className="w-3.5 h-3.5" />
            {t('imageOcclusion.delete')}
          </button>
        )}
        <button
          type="button"
          onClick={clearAll}
          disabled={regions.length === 0}
          className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-muted-foreground bg-muted rounded-lg hover:text-foreground transition-colors disabled:opacity-40"
        >
          <RotateCcw className="w-3.5 h-3.5" />
          {t('imageOcclusion.clear')}
        </button>
        <button
          type="button"
          onClick={() => fileRef.current?.click()}
          className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-muted-foreground bg-muted rounded-lg hover:text-foreground transition-colors"
        >
          <Upload className="w-3.5 h-3.5" />
        </button>
        <input ref={fileRef} type="file" accept="image/*" onChange={handleImageUpload} className="hidden" />
      </div>

      {/* Image + SVG overlay */}
      <div className="relative rounded-xl overflow-hidden border border-border bg-black/5">
        <img src={imageUrl} alt="Occlusion base" className="w-full block" draggable={false} />
        <svg
          ref={svgRef}
          className="absolute inset-0 w-full h-full"
          viewBox="0 0 100 100"
          preserveAspectRatio="none"
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          style={{ cursor: tool === 'draw' ? 'crosshair' : 'default' }}
        >
          {/* Existing regions */}
          {regions.map((r) => (
            <g key={r.id} onClick={(e) => { e.stopPropagation(); setSelectedId(r.id); setEditLabel(r.label || ''); setTool('select'); }}>
              <rect
                x={r.x}
                y={r.y}
                width={r.width}
                height={r.height}
                fill="rgba(34, 197, 94, 0.6)"
                stroke={selectedId === r.id ? '#fff' : 'rgba(34, 197, 94, 0.8)'}
                strokeWidth={selectedId === r.id ? 0.5 : 0.2}
                rx={0.5}
                className="cursor-pointer"
              />
              <text
                x={r.x + r.width / 2}
                y={r.y + r.height / 2}
                textAnchor="middle"
                dominantBaseline="central"
                fill="white"
                fontSize={Math.min(r.width / 4, r.height / 3, 3)}
                fontWeight="bold"
              >
                ?
              </text>
            </g>
          ))}

          {/* Drawing preview */}
          {drawingRect && (
            <rect
              x={drawingRect.x}
              y={drawingRect.y}
              width={drawingRect.width}
              height={drawingRect.height}
              fill="rgba(34, 197, 94, 0.3)"
              stroke="rgba(34, 197, 94, 0.8)"
              strokeWidth={0.2}
              strokeDasharray="1"
              rx={0.5}
            />
          )}
        </svg>
      </div>

      {/* Selected region label editor */}
      <AnimatePresence>
        {selectedId && tool === 'select' && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="flex items-center gap-2"
          >
            <span className="text-xs text-muted-foreground shrink-0">{t('imageOcclusion.label')}</span>
            <input
              type="text"
              value={editLabel}
              onChange={(e) => { setEditLabel(e.target.value); updateLabel(selectedId, e.target.value); }}
              placeholder={t('imageOcclusion.labelPlaceholder')}
              className="flex-1 px-3 py-1.5 text-sm bg-background border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500/20 focus:border-green-500"
            />
          </motion.div>
        )}
      </AnimatePresence>

      {/* Region count */}
      <p className="text-xs text-muted-foreground">
        {regions.length !== 1 ? t('imageOcclusion.regionCountPlural', { count: regions.length }) : t('imageOcclusion.regionCount', { count: regions.length })}
      </p>
    </div>
  );
}

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import type { OcclusionRegion } from '@/types';
import { Eye } from 'lucide-react';

interface ImageOcclusionViewerProps {
  imageUrl: string;
  regions: OcclusionRegion[];
  onAllRevealed?: () => void;
}

export function ImageOcclusionViewer({ imageUrl, regions, onAllRevealed }: ImageOcclusionViewerProps) {
  const [revealedIds, setRevealedIds] = useState<Set<string>>(new Set());

  const handleReveal = (id: string) => {
    const newSet = new Set(revealedIds);
    newSet.add(id);
    setRevealedIds(newSet);
    if (newSet.size === regions.length) {
      onAllRevealed?.();
    }
  };

  const revealAll = () => {
    const all = new Set(regions.map((r) => r.id));
    setRevealedIds(all);
    onAllRevealed?.();
  };

  const revealedCount = revealedIds.size;

  return (
    <div className="space-y-4">
      {/* Image with occlusion overlays */}
      <div className="relative rounded-xl overflow-hidden border border-border">
        <img src={imageUrl} alt="Study image" className="w-full block" draggable={false} />
        <svg
          className="absolute inset-0 w-full h-full"
          viewBox="0 0 100 100"
          preserveAspectRatio="none"
        >
          {regions.map((r) => {
            const isRevealed = revealedIds.has(r.id);

            return (
              <g key={r.id}>
                <AnimatePresence mode="wait">
                  {!isRevealed ? (
                    <motion.g
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      exit={{ opacity: 0 }}
                      onClick={() => handleReveal(r.id)}
                      className="cursor-pointer"
                    >
                      <rect
                        x={r.x}
                        y={r.y}
                        width={r.width}
                        height={r.height}
                        fill="rgba(34, 197, 94, 0.85)"
                        stroke="rgba(34, 197, 94, 1)"
                        strokeWidth={0.3}
                        rx={0.5}
                      />
                      <text
                        x={r.x + r.width / 2}
                        y={r.y + r.height / 2}
                        textAnchor="middle"
                        dominantBaseline="central"
                        fill="white"
                        fontSize={Math.min(r.width / 3, r.height / 2.5, 4)}
                        fontWeight="bold"
                      >
                        ?
                      </text>
                    </motion.g>
                  ) : (
                    <motion.rect
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      x={r.x}
                      y={r.y}
                      width={r.width}
                      height={r.height}
                      fill="none"
                      stroke="rgba(34, 197, 94, 0.8)"
                      strokeWidth={0.3}
                      rx={0.5}
                    />
                  )}
                </AnimatePresence>
              </g>
            );
          })}
        </svg>
      </div>

      {/* Revealed labels */}
      {revealedCount > 0 && (
        <div className="flex flex-wrap gap-2 px-2">
          {regions
            .filter((r) => revealedIds.has(r.id) && r.label)
            .map((r) => (
              <motion.span
                key={r.id}
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                className="px-2.5 py-1 text-xs font-medium bg-green-500/10 text-green-600 dark:text-green-400 rounded-full border border-green-500/20"
              >
                {r.label}
              </motion.span>
            ))}
        </div>
      )}

      {/* Progress */}
      <div className="flex items-center justify-between px-2">
        <span className="text-xs text-muted-foreground">
          {revealedCount} / {regions.length} regions revealed
        </span>
        {revealedCount < regions.length && (
          <button
            onClick={revealAll}
            className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors"
          >
            <Eye className="w-3.5 h-3.5" />
            Reveal all
          </button>
        )}
      </div>
    </div>
  );
}

import { useState, useRef, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { Globe } from 'lucide-react';
import { supportedLanguages, languageNames, type SupportedLanguage } from '@/lib/i18n';

export function LanguageSwitcher() {
  const { i18n } = useTranslation();
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const changeLanguage = (lang: SupportedLanguage) => {
    i18n.changeLanguage(lang);
    setOpen(false);
  };

  return (
    <div className="relative" ref={ref}>
      <button
        onClick={() => setOpen(!open)}
        className="p-2 hover:bg-muted rounded-lg transition-colors"
        aria-label="Change language"
      >
        <Globe className="w-5 h-5 text-muted-foreground" />
      </button>

      {open && (
        <div className="absolute right-0 top-full mt-2 w-40 bg-card border border-border rounded-lg shadow-lg z-50">
          <div className="p-1">
            {supportedLanguages.map((lang) => (
              <button
                key={lang}
                onClick={() => changeLanguage(lang)}
                className={`w-full text-left px-3 py-2 text-sm rounded-md transition-colors ${
                  i18n.language === lang
                    ? 'bg-green-500/10 text-green-600 font-medium'
                    : 'hover:bg-muted'
                }`}
              >
                {languageNames[lang]}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import { useEffect, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { motion, AnimatePresence } from 'framer-motion';
import { useNotificationsStore } from '@/stores/useNotificationsStore';
import { cn } from '@/lib/utils';
import {
  Bell,
  Check,
  CheckCheck,
  Trash2,
  Info,
  Trophy,
  AlertTriangle,
  Clock,
  X,
} from 'lucide-react';
import type { NotificationType } from '@/types';

const typeConfig: Record<NotificationType, { icon: typeof Info; color: string; bg: string }> = {
  info: { icon: Info, color: 'text-blue-500', bg: 'bg-blue-500/10' },
  success: { icon: Trophy, color: 'text-green-500', bg: 'bg-green-500/10' },
  warning: { icon: AlertTriangle, color: 'text-amber-500', bg: 'bg-amber-500/10' },
  reminder: { icon: Clock, color: 'text-purple-500', bg: 'bg-purple-500/10' },
};

function useFormatTimeAgo() {
  const { t } = useTranslation();
  return (dateString: string): string => {
    const date = new Date(dateString);
    const now = new Date();
    const seconds = Math.floor((now.getTime() - date.getTime()) / 1000);

    if (seconds < 60) return t('notifications.justNow');
    if (seconds < 3600) return t('notifications.minutesAgo', { count: Math.floor(seconds / 60) });
    if (seconds < 86400) return t('notifications.hoursAgo', { count: Math.floor(seconds / 3600) });
    if (seconds < 604800) return t('notifications.daysAgo', { count: Math.floor(seconds / 86400) });
    return date.toLocaleDateString();
  };
}

export function NotificationBell() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const formatTimeAgo = useFormatTimeAgo();
  const panelRef = useRef<HTMLDivElement>(null);
  const {
    notifications,
    unreadCount,
    isLoading,
    isOpen,
    setOpen,
    toggle,
    fetchNotifications,
    fetchUnreadCount,
    markAsRead,
    markAllAsRead,
    deleteNotification,
  } = useNotificationsStore();

  // Fetch unread count on mount
  useEffect(() => {
    fetchUnreadCount();
    // Poll for new notifications every 30 seconds
    const interval = setInterval(fetchUnreadCount, 30000);
    return () => clearInterval(interval);
  }, [fetchUnreadCount]);

  // Fetch full list when panel opens
  useEffect(() => {
    if (isOpen) {
      fetchNotifications();
    }
  }, [isOpen, fetchNotifications]);

  // Close panel when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (panelRef.current && !panelRef.current.contains(event.target as Node)) {
        setOpen(false);
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen, setOpen]);

  const handleNotificationClick = (notification: typeof notifications[0]) => {
    if (!notification.isRead) {
      markAsRead(notification.id);
    }
    if (notification.link) {
      navigate(notification.link);
      setOpen(false);
    }
  };

  return (
    <div className="relative" ref={panelRef}>
      {/* Bell button */}
      <button
        onClick={toggle}
        className={cn(
          'relative p-2 rounded-lg transition-colors',
          isOpen ? 'bg-muted' : 'hover:bg-muted'
        )}
        aria-label="Notifications"
      >
        <Bell className="w-5 h-5" />
        {unreadCount > 0 && (
          <motion.span
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            className="absolute -top-0.5 -right-0.5 min-w-[18px] h-[18px] px-1 flex items-center justify-center text-[10px] font-bold text-white bg-red-500 rounded-full"
          >
            {unreadCount > 99 ? '99+' : unreadCount}
          </motion.span>
        )}
      </button>

      {/* Dropdown panel */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 10, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 10, scale: 0.95 }}
            transition={{ duration: 0.15 }}
            className="absolute right-0 top-full mt-2 w-80 sm:w-96 bg-card border border-border rounded-xl shadow-xl z-50 overflow-hidden"
          >
            {/* Header */}
            <div className="flex items-center justify-between px-4 py-3 border-b border-border">
              <h3 className="font-semibold">{t('notifications.title')}</h3>
              <div className="flex items-center gap-1">
                {unreadCount > 0 && (
                  <button
                    onClick={markAllAsRead}
                    className="p-1.5 rounded-lg hover:bg-muted transition-colors text-muted-foreground hover:text-foreground"
                    title={t('notifications.markAllAsRead')}
                  >
                    <CheckCheck className="w-4 h-4" />
                  </button>
                )}
                <button
                  onClick={() => setOpen(false)}
                  className="p-1.5 rounded-lg hover:bg-muted transition-colors text-muted-foreground hover:text-foreground sm:hidden"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            </div>

            {/* Notifications list */}
            <div className="max-h-[400px] overflow-y-auto">
              {isLoading && notifications.length === 0 ? (
                <div className="flex items-center justify-center py-8">
                  <div className="w-6 h-6 border-2 border-green-500 border-t-transparent rounded-full animate-spin" />
                </div>
              ) : notifications.length === 0 ? (
                <div className="text-center py-12 px-4">
                  <div className="w-12 h-12 rounded-full bg-muted flex items-center justify-center mx-auto mb-3">
                    <Bell className="w-6 h-6 text-muted-foreground" />
                  </div>
                  <p className="text-sm font-medium text-muted-foreground">{t('notifications.noNotifications')}</p>
                  <p className="text-xs text-muted-foreground/70 mt-1">
                    {t('notifications.wellNotify')}
                  </p>
                </div>
              ) : (
                <div className="divide-y divide-border">
                  {notifications.map((notification) => {
                    const config = typeConfig[notification.type] || typeConfig.info;
                    const Icon = config.icon;

                    return (
                      <motion.div
                        key={notification.id}
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        className={cn(
                          'relative group',
                          !notification.isRead && 'bg-green-500/5'
                        )}
                      >
                        <button
                          onClick={() => handleNotificationClick(notification)}
                          className="w-full text-left px-4 py-3 hover:bg-muted/50 transition-colors"
                        >
                          <div className="flex gap-3">
                            {/* Icon */}
                            <div className={cn('w-9 h-9 rounded-lg flex items-center justify-center shrink-0', config.bg)}>
                              <Icon className={cn('w-4 h-4', config.color)} />
                            </div>

                            {/* Content */}
                            <div className="flex-1 min-w-0">
                              <div className="flex items-start justify-between gap-2">
                                <p className={cn(
                                  'text-sm leading-tight',
                                  !notification.isRead ? 'font-semibold' : 'font-medium'
                                )}>
                                  {notification.title}
                                </p>
                                {!notification.isRead && (
                                  <span className="w-2 h-2 rounded-full bg-green-500 shrink-0 mt-1.5" />
                                )}
                              </div>
                              <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">
                                {notification.message}
                              </p>
                              <p className="text-[10px] text-muted-foreground/70 mt-1">
                                {formatTimeAgo(notification.createdAt)}
                              </p>
                            </div>
                          </div>
                        </button>

                        {/* Action buttons (visible on hover) */}
                        <div className="absolute right-2 top-1/2 -translate-y-1/2 hidden group-hover:flex items-center gap-1 bg-card/90 backdrop-blur-sm px-1 py-0.5 rounded-lg border border-border shadow-sm">
                          {!notification.isRead && (
                            <button
                              onClick={(e) => {
                                e.stopPropagation();
                                markAsRead(notification.id);
                              }}
                              className="p-1 rounded hover:bg-muted transition-colors"
                              title={t('notifications.markAllAsRead')}
                            >
                              <Check className="w-3.5 h-3.5 text-green-500" />
                            </button>
                          )}
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              deleteNotification(notification.id);
                            }}
                            className="p-1 rounded hover:bg-muted transition-colors"
                            title={t('common.delete')}
                          >
                            <Trash2 className="w-3.5 h-3.5 text-red-500" />
                          </button>
                        </div>
                      </motion.div>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Footer */}
            {notifications.length > 0 && (
              <div className="px-4 py-2.5 border-t border-border bg-muted/30">
                <Link
                  to="/dashboard/notifications"
                  onClick={() => setOpen(false)}
                  className="text-xs font-medium text-green-600 hover:text-green-500 transition-colors"
                >
                  {t('notifications.viewAll')}
                </Link>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { ChevronLeft, ChevronRight, Flame } from 'lucide-react';
import { useTranslation } from 'react-i18next';

interface StreakCalendarProps {
  activeDays: Set<string>; // ISO date strings, e.g. '2025-01-15'
}

export function StreakCalendar({ activeDays }: StreakCalendarProps) {
  const { t } = useTranslation();

  const DAY_NAMES = [
    t('streakCalendar.days.sun'), t('streakCalendar.days.mon'), t('streakCalendar.days.tue'),
    t('streakCalendar.days.wed'), t('streakCalendar.days.thu'), t('streakCalendar.days.fri'),
    t('streakCalendar.days.sat'),
  ];
  const MONTH_NAMES = [
    t('streakCalendar.months.january'), t('streakCalendar.months.february'), t('streakCalendar.months.march'),
    t('streakCalendar.months.april'), t('streakCalendar.months.may'), t('streakCalendar.months.june'),
    t('streakCalendar.months.july'), t('streakCalendar.months.august'), t('streakCalendar.months.september'),
    t('streakCalendar.months.october'), t('streakCalendar.months.november'), t('streakCalendar.months.december'),
  ];
  const today = new Date();
  const [year, setYear] = useState(today.getFullYear());
  const [month, setMonth] = useState(today.getMonth());

  const { days, firstDayOffset } = useMemo(() => {
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const firstDay = new Date(year, month, 1).getDay();
    const daysList = Array.from({ length: daysInMonth }, (_, i) => i + 1);
    return { days: daysList, firstDayOffset: firstDay };
  }, [year, month]);

  const goBack = () => {
    if (month === 0) { setMonth(11); setYear(year - 1); }
    else setMonth(month - 1);
  };

  const goForward = () => {
    if (month === 11) { setMonth(0); setYear(year + 1); }
    else setMonth(month + 1);
  };

  const todayStr = today.toISOString().split('T')[0];

  return (
    <div>
      {/* Month navigation */}
      <div className="flex items-center justify-between mb-4">
        <button onClick={goBack} className="p-1.5 rounded-lg hover:bg-muted transition-colors">
          <ChevronLeft className="w-4 h-4" />
        </button>
        <h4 className="text-sm font-semibold">
          {MONTH_NAMES[month]} {year}
        </h4>
        <button onClick={goForward} className="p-1.5 rounded-lg hover:bg-muted transition-colors">
          <ChevronRight className="w-4 h-4" />
        </button>
      </div>

      {/* Day names */}
      <div className="grid grid-cols-7 gap-1 mb-1">
        {DAY_NAMES.map((d) => (
          <div key={d} className="text-center text-[10px] font-medium text-muted-foreground py-1">
            {d}
          </div>
        ))}
      </div>

      {/* Calendar grid */}
      <div className="grid grid-cols-7 gap-1">
        {/* Empty cells for offset */}
        {Array.from({ length: firstDayOffset }).map((_, i) => (
          <div key={`empty-${i}`} />
        ))}

        {/* Day cells */}
        {days.map((day) => {
          const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
          const isActive = activeDays.has(dateStr);
          const isToday = dateStr === todayStr;

          return (
            <div
              key={day}
              className={`relative flex items-center justify-center h-9 rounded-lg text-xs transition-colors ${
                isActive
                  ? 'bg-green-500/15 text-green-600 dark:text-green-400 font-semibold'
                  : 'text-muted-foreground hover:bg-muted/50'
              } ${isToday ? 'ring-2 ring-green-500/40' : ''}`}
            >
              {day}
              {isActive && (
                <Flame className="absolute -top-1 -right-0.5 w-3 h-3 text-orange-500 fill-orange-500" />
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';

interface StudyHeatmapProps {
  data: Record<string, number>; // { '2025-01-15': 5, ... }
  weeks?: number;
}

function getIntensity(count: number, max: number): string {
  if (count === 0) return 'bg-muted';
  const ratio = count / Math.max(max, 1);
  if (ratio <= 0.25) return 'bg-green-200 dark:bg-green-900';
  if (ratio <= 0.5) return 'bg-green-400 dark:bg-green-700';
  if (ratio <= 0.75) return 'bg-green-500 dark:bg-green-600';
  return 'bg-green-600 dark:bg-green-500';
}

export function StudyHeatmap({ data, weeks = 52 }: StudyHeatmapProps) {
  const { t } = useTranslation();
  const [tooltip, setTooltip] = useState<{ date: string; count: number; x: number; y: number } | null>(null);

  const MONTHS = [
    t('studyHeatmap.months.jan'), t('studyHeatmap.months.feb'), t('studyHeatmap.months.mar'),
    t('studyHeatmap.months.apr'), t('studyHeatmap.months.may'), t('studyHeatmap.months.jun'),
    t('studyHeatmap.months.jul'), t('studyHeatmap.months.aug'), t('studyHeatmap.months.sep'),
    t('studyHeatmap.months.oct'), t('studyHeatmap.months.nov'), t('studyHeatmap.months.dec'),
  ];
  const DAYS = [t('studyHeatmap.days.mon'), '', t('studyHeatmap.days.wed'), '', t('studyHeatmap.days.fri'), '', ''];

  const { grid, monthLabels, maxCount } = useMemo(() => {
    const today = new Date();
    const totalDays = weeks * 7;
    const startDate = new Date(today);
    startDate.setDate(today.getDate() - totalDays + 1);
    // Adjust to start on Sunday
    const dayOfWeek = startDate.getDay();
    startDate.setDate(startDate.getDate() - dayOfWeek);

    const cells: Array<{ date: string; count: number; week: number; day: number }> = [];
    let maxVal = 0;
    const months: Array<{ label: string; week: number }> = [];
    let lastMonth = -1;

    const cursor = new Date(startDate);
    for (let w = 0; w < weeks; w++) {
      for (let d = 0; d < 7; d++) {
        const dateStr = cursor.toISOString().split('T')[0];
        const count = data[dateStr] || 0;
        if (count > maxVal) maxVal = count;
        cells.push({ date: dateStr, count, week: w, day: d });

        const month = cursor.getMonth();
        if (month !== lastMonth) {
          months.push({ label: MONTHS[month], week: w });
          lastMonth = month;
        }
        cursor.setDate(cursor.getDate() + 1);
      }
    }

    return { grid: cells, monthLabels: months, maxCount: maxVal };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [data, weeks, t]);

  return (
    <div className="relative">
      {/* Month labels */}
      <div className="flex ml-8 mb-1 text-[10px] text-muted-foreground">
        {monthLabels.map((m, i) => (
          <span key={i} style={{ marginLeft: i === 0 ? 0 : `${(m.week - (monthLabels[i - 1]?.week ?? 0)) * 14 - 20}px` }}>
            {m.label}
          </span>
        ))}
      </div>

      <div className="flex gap-0.5">
        {/* Day labels */}
        <div className="flex flex-col gap-0.5 mr-1 text-[10px] text-muted-foreground justify-between py-0.5">
          {DAYS.map((d, i) => (
            <span key={i} className="h-[12px] flex items-center">{d}</span>
          ))}
        </div>

        {/* Grid */}
        <div className="flex gap-[2px] overflow-x-auto">
          {Array.from({ length: weeks }).map((_, w) => (
            <div key={w} className="flex flex-col gap-[2px]">
              {Array.from({ length: 7 }).map((_, d) => {
                const cell = grid.find((c) => c.week === w && c.day === d);
                if (!cell) return <div key={d} className="w-[12px] h-[12px]" />;
                return (
                  <div
                    key={d}
                    className={`w-[12px] h-[12px] rounded-[2px] ${getIntensity(cell.count, maxCount)} cursor-default transition-colors`}
                    onMouseEnter={(e) => {
                      const rect = e.currentTarget.getBoundingClientRect();
                      setTooltip({ date: cell.date, count: cell.count, x: rect.left, y: rect.top - 30 });
                    }}
                    onMouseLeave={() => setTooltip(null)}
                  />
                );
              })}
            </div>
          ))}
        </div>
      </div>

      {/* Legend */}
      <div className="flex items-center gap-1.5 mt-2 ml-8 text-[10px] text-muted-foreground">
        <span>{t('studyHeatmap.less')}</span>
        <div className="w-[12px] h-[12px] rounded-[2px] bg-muted" />
        <div className="w-[12px] h-[12px] rounded-[2px] bg-green-200 dark:bg-green-900" />
        <div className="w-[12px] h-[12px] rounded-[2px] bg-green-400 dark:bg-green-700" />
        <div className="w-[12px] h-[12px] rounded-[2px] bg-green-500 dark:bg-green-600" />
        <div className="w-[12px] h-[12px] rounded-[2px] bg-green-600 dark:bg-green-500" />
        <span>{t('studyHeatmap.more')}</span>
      </div>

      {/* Tooltip */}
      {tooltip && (
        <div
          className="fixed z-50 px-2 py-1 bg-popover border border-border rounded-md shadow-lg text-xs pointer-events-none"
          style={{ left: tooltip.x - 20, top: tooltip.y }}
        >
          <span className="font-medium">{t('studyHeatmap.sessions', { count: tooltip.count })}</span>
          <span className="text-muted-foreground"> {t('studyHeatmap.on')} {tooltip.date}</span>
        </div>
      )}
    </div>
  );
}

import { motion, AnimatePresence } from 'framer-motion';
import { useTranslation } from 'react-i18next';
import { useGamificationStore } from '@/stores/useGamificationStore';
import { getLevelInfo } from '@/types';
import { Flame, Star, Zap } from 'lucide-react';

export function XPProgressBar() {
  const { t } = useTranslation();
  const { stats, recentXpGain, clearRecentXp } = useGamificationStore();

  if (!stats) return null;

  const xpInLevel = stats.totalXp - stats.currentLevelXp;
  const xpNeeded = stats.nextLevelXp - stats.currentLevelXp;
  const progressPct = xpNeeded > 0 ? Math.min((xpInLevel / xpNeeded) * 100, 100) : 100;
  const dailyPct = stats.dailyGoal > 0 ? Math.min((stats.dailyXp / stats.dailyGoal) * 100, 100) : 0;
  const levelInfo = getLevelInfo(stats.level);

  return (
    <div className="space-y-3">
      {/* Level + XP Bar row */}
      <div className="flex items-center gap-3">
        {/* Level badge */}
        <div className="relative">
          <div className={`w-11 h-11 rounded-xl bg-gradient-to-br ${levelInfo.gradient} flex items-center justify-center shadow-lg ${levelInfo.shadow}`}>
            <span className="text-white font-bold text-sm">{stats.level}</span>
          </div>
          <Star className="absolute -top-1 -right-1 w-4 h-4 text-amber-400 fill-amber-400" />
        </div>

        {/* XP progress */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center justify-between mb-1">
            <span className={`text-xs font-semibold ${levelInfo.text}`}>{t(`gamification.levelNames.${stats.level}`, { defaultValue: levelInfo.name })}</span>
            <span className="text-xs text-muted-foreground">
              {xpInLevel} / {xpNeeded} {t('gamification.xp')}
            </span>
          </div>
          <div className="h-2.5 bg-muted rounded-full overflow-hidden">
            <motion.div
              className={`h-full bg-gradient-to-r ${levelInfo.gradient} rounded-full`}
              initial={{ width: 0 }}
              animate={{ width: `${progressPct}%` }}
              transition={{ duration: 0.8, ease: 'easeOut' }}
            />
          </div>
        </div>
      </div>

      {/* Streak + Daily Goal row */}
      <div className="flex items-center gap-3">
        {/* Streak */}
        <div className="flex items-center gap-1.5 px-3 py-1.5 bg-orange-500/10 rounded-full">
          <Flame className="w-4 h-4 text-orange-500" />
          <span className="text-sm font-semibold text-orange-600 dark:text-orange-400">
            {stats.streakDays} {stats.streakDays === 1 ? t('gamification.day') : t('gamification.days')}
          </span>
        </div>

        {/* Daily goal ring */}
        <div className="flex items-center gap-2 flex-1">
          <div className="relative w-8 h-8">
            <svg className="w-8 h-8 -rotate-90" viewBox="0 0 36 36">
              <circle cx="18" cy="18" r="15" fill="none" stroke="currentColor" strokeWidth="3" className="text-muted" />
              <motion.circle
                cx="18"
                cy="18"
                r="15"
                fill="none"
                stroke="currentColor"
                strokeWidth="3"
                strokeDasharray={`${dailyPct * 0.9425} 94.25`}
                strokeLinecap="round"
                className="text-green-500"
                initial={{ strokeDasharray: '0 94.25' }}
                animate={{ strokeDasharray: `${dailyPct * 0.9425} 94.25` }}
                transition={{ duration: 0.8 }}
              />
            </svg>
            <Zap className="absolute inset-0 m-auto w-3.5 h-3.5 text-green-500" />
          </div>
          <div className="text-xs">
            <span className="font-medium">{stats.dailyXp}</span>
            <span className="text-muted-foreground"> / {stats.dailyGoal} {t('gamification.dailyXp')}</span>
          </div>
        </div>
      </div>

      {/* XP gain toast */}
      <AnimatePresence>
        {recentXpGain && (
          <motion.div
            initial={{ opacity: 0, y: 10, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -10, scale: 0.9 }}
            onAnimationComplete={() => setTimeout(clearRecentXp, 1500)}
            className="flex items-center gap-2 px-3 py-1.5 bg-green-500/10 border border-green-500/20 rounded-lg w-fit"
          >
            <Zap className="w-4 h-4 text-green-500" />
            <span className="text-sm font-semibold text-green-600 dark:text-green-400">
              +{recentXpGain} XP
            </span>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useState, useCallback, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Upload,
  FileText,
  File,
  Image,
  Trash2,
  Download,
  Loader2,
  X,
  AlertCircle,
  Eye,
  ExternalLink,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import api from '@/services/api';
import { ENDPOINTS } from '@/config/api';
import { cn } from '@/lib/utils';
import { useTranslation } from 'react-i18next';

interface Document {
  id: string;
  title: string;
  fileName: string;
  fileUrl: string;
  fileSize: number;
  mimeType: string;
  createdAt: string;
}

interface DocumentsTabProps {
  studySetId: string;
}

const ALLOWED_TYPES = [
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'text/plain',
  'text/markdown',
  'image/png',
  'image/jpeg',
];

const MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB

function formatFileSize(bytes: number): string {
  if (bytes === 0) return '0 Bytes';
  const k = 1024;
  const sizes = ['Bytes', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

function getFileIcon(mimeType: string) {
  if (mimeType.startsWith('image/')) {
    return <Image className="w-8 h-8 text-green-500" />;
  }
  if (mimeType === 'application/pdf') {
    return <FileText className="w-8 h-8 text-red-500" />;
  }
  if (mimeType.includes('word') || mimeType.includes('document')) {
    return <FileText className="w-8 h-8 text-blue-500" />;
  }
  if (mimeType === 'text/markdown') {
    return <FileText className="w-8 h-8 text-purple-500" />;
  }
  return <File className="w-8 h-8 text-muted-foreground" />;
}

export function DocumentsTab({ studySetId }: DocumentsTabProps) {
  const { t } = useTranslation();
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [previewDoc, setPreviewDoc] = useState<Document | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Fetch documents on mount
  const fetchDocuments = useCallback(async () => {
    try {
      setIsLoading(true);
      const response = await api.get<Document[]>(
        ENDPOINTS.documents.byStudySet(studySetId)
      );
      setDocuments(response.data);
    } catch (err) {
      console.error('Failed to fetch documents:', err);
      setError(t('documentsTab.failedLoad'));
    } finally {
      setIsLoading(false);
    }
  }, [studySetId, t]);

  // Initial fetch
  useEffect(() => {
    fetchDocuments();
  }, [fetchDocuments]);

  const handleUpload = useCallback(
    async (files: FileList | File[]) => {
      const fileArray = Array.from(files);
      if (fileArray.length === 0) return;

      setError(null);
      setIsUploading(true);
      setUploadProgress(0);

      const uploadedDocs: Document[] = [];
      const totalFiles = fileArray.length;
      let completedFiles = 0;

      for (const file of fileArray) {
        // Validate file type
        if (!ALLOWED_TYPES.includes(file.type)) {
          setError(t('documentsTab.fileTypeNotAllowed', { name: file.name }));
          continue;
        }

        // Validate file size
        if (file.size > MAX_FILE_SIZE) {
          setError(t('documentsTab.fileTooLarge', { name: file.name }));
          continue;
        }

        try {
          const formData = new FormData();
          formData.append('file', file);
          formData.append('studySetId', studySetId);
          formData.append('title', file.name);

          const response = await api.post<Document>(
            ENDPOINTS.documents.upload,
            formData,
            {
              headers: {
                'Content-Type': 'multipart/form-data',
              },
              onUploadProgress: (progressEvent) => {
                if (progressEvent.total) {
                  const fileProgress =
                    (progressEvent.loaded / progressEvent.total) * 100;
                  const overallProgress =
                    ((completedFiles + fileProgress / 100) / totalFiles) * 100;
                  setUploadProgress(Math.round(overallProgress));
                }
              },
            }
          );

          uploadedDocs.push(response.data);
          completedFiles++;
        } catch (err) {
          console.error(`Failed to upload ${file.name}:`, err);
          setError(t('documentsTab.failedUpload', { name: file.name }));
        }
      }

      if (uploadedDocs.length > 0) {
        setDocuments((prev) => [...uploadedDocs, ...prev]);
      }

      setIsUploading(false);
      setUploadProgress(0);
    },
    [studySetId, t]
  );

  const handleDrop = useCallback(
    (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      setIsDragging(false);

      if (e.dataTransfer.files) {
        handleUpload(e.dataTransfer.files);
      }
    },
    [handleUpload]
  );

  const handleDragOver = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDelete = useCallback(async (id: string) => {
    try {
      await api.delete(ENDPOINTS.documents.delete(id));
      setDocuments((prev) => prev.filter((doc) => doc.id !== id));
      setDeleteId(null);
    } catch (err) {
      console.error('Failed to delete document:', err);
      setError(t('documentsTab.failedDelete'));
    }
  }, [t]);

  const handleDownload = useCallback(async (doc: Document) => {
    try {
      // Get signed download URL
      const response = await api.get<{ url: string }>(
        ENDPOINTS.documents.downloadUrl(doc.id)
      );
      window.open(response.data.url, '_blank');
    } catch (err) {
      console.error('Failed to get download URL:', err);
      // Fallback to direct URL
      window.open(doc.fileUrl, '_blank');
    }
  }, []);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      className="space-y-6"
    >
      {/* Upload Zone */}
      <div
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        className={cn(
          'relative border-2 border-dashed rounded-xl p-8 text-center transition-all',
          isDragging
            ? 'border-primary bg-primary/5'
            : 'border-border hover:border-primary/50',
          isUploading && 'pointer-events-none opacity-60'
        )}
      >
        <input
          ref={fileInputRef}
          type="file"
          multiple
          accept=".pdf,.doc,.docx,.txt,.md,.png,.jpg,.jpeg"
          onChange={(e) => e.target.files && handleUpload(e.target.files)}
          className="hidden"
        />

        {isUploading ? (
          <div className="space-y-3">
            <Loader2 className="w-10 h-10 animate-spin text-primary mx-auto" />
            <p className="text-sm text-muted-foreground">
              {t('documentsTab.uploadingProgress', { progress: uploadProgress })}
            </p>
            <div className="w-full max-w-xs mx-auto bg-muted rounded-full h-2 overflow-hidden">
              <div
                className="bg-primary h-full transition-all duration-300"
                style={{ width: `${uploadProgress}%` }}
              />
            </div>
          </div>
        ) : (
          <>
            <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center mx-auto mb-4">
              <Upload className="w-8 h-8 text-primary" />
            </div>
            <h3 className="font-semibold mb-1">{t('documentsTab.uploadDocuments')}</h3>
            <p className="text-sm text-muted-foreground mb-4">
              {t('documentsTab.dragAndDrop')}
            </p>
            <Button
              variant="outline"
              onClick={() => fileInputRef.current?.click()}
            >
              {t('documentsTab.chooseFiles')}
            </Button>
            <p className="text-xs text-muted-foreground mt-3">
              {t('documentsTab.supportedFormats')}
            </p>
          </>
        )}
      </div>

      {/* Error Message */}
      {error && (
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-center gap-2 p-3 bg-destructive/10 border border-destructive/20 rounded-lg text-destructive text-sm"
        >
          <AlertCircle className="w-4 h-4 flex-shrink-0" />
          <span>{error}</span>
          <button
            onClick={() => setError(null)}
            className="ml-auto hover:opacity-70"
          >
            <X className="w-4 h-4" />
          </button>
        </motion.div>
      )}

      {/* Documents List */}
      {documents.length === 0 ? (
        <div className="text-center py-8 text-muted-foreground">
          <FileText className="w-12 h-12 mx-auto mb-3 opacity-50" />
          <p>{t('documentsTab.noDocuments')}</p>
          <p className="text-sm">{t('documentsTab.uploadFirst')}</p>
        </div>
      ) : (
        <div className="grid gap-3">
          <AnimatePresence mode="popLayout">
            {documents.map((doc) => (
              <motion.div
                key={doc.id}
                layout
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, x: -10 }}
                className="flex items-center gap-4 p-4 bg-card border border-border rounded-xl hover:border-primary/30 transition-colors"
              >
                <div className="flex-shrink-0">{getFileIcon(doc.mimeType)}</div>

                <div className="flex-1 min-w-0">
                  <h4 className="font-medium truncate">{doc.title}</h4>
                  <div className="flex items-center gap-2 text-xs text-muted-foreground">
                    <span>{formatFileSize(doc.fileSize)}</span>
                    <span>-</span>
                    <span>
                      {new Date(doc.createdAt).toLocaleDateString()}
                    </span>
                  </div>
                </div>

                <div className="flex items-center gap-1">
                  {(doc.mimeType.startsWith('image/') ||
                    doc.mimeType === 'application/pdf') && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setPreviewDoc(doc)}
                      title="Preview"
                    >
                      <Eye className="w-4 h-4" />
                    </Button>
                  )}
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleDownload(doc)}
                    title="Download"
                  >
                    <Download className="w-4 h-4" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setDeleteId(doc.id)}
                    title="Delete"
                    className="text-destructive hover:text-destructive"
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      <AnimatePresence>
        {deleteId && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
            onClick={() => setDeleteId(null)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-card border border-border rounded-xl p-6 max-w-sm w-full"
            >
              <h3 className="text-lg font-semibold mb-2">{t('documentsTab.deleteDocument')}</h3>
              <p className="text-sm text-muted-foreground mb-4">
                {t('documentsTab.deleteDocumentDesc')}
              </p>
              <div className="flex justify-end gap-2">
                <Button variant="outline" onClick={() => setDeleteId(null)}>
                  Cancel
                </Button>
                <Button
                  variant="destructive"
                  onClick={() => handleDelete(deleteId)}
                >
                  Delete
                </Button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Preview Modal */}
      <AnimatePresence>
        {previewDoc && (
          <motion.div
