          transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
          className="absolute top-1/4 -left-20 w-[400px] h-[400px] bg-gradient-to-br from-blue-400/20 to-cyan-400/10 rounded-full blur-3xl"
