export function AccountSettingsPage() {
  const navigate = useNavigate();
  const { t } = useTranslation();
  const { user, logout } = useAuth();

  // Password
  const [oldPassword, setOldPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showOld, setShowOld] = useState(false);
  const [showNew, setShowNew] = useState(false);
  const [changingPassword, setChangingPassword] = useState(false);
  const [passwordChanged, setPasswordChanged] = useState(false);
  const [passwordError, setPasswordError] = useState('');

  // Delete
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteConfirmText, setDeleteConfirmText] = useState('');
  const [deleting, setDeleting] = useState(false);

  const handleChangePassword = async () => {
    setPasswordError('');

    if (newPassword.length < 8) {
      setPasswordError(t('accountSettingsPage.passwordMinLength'));
      return;
    }
    if (newPassword !== confirmPassword) {
      setPasswordError(t('accountSettingsPage.passwordsDoNotMatch'));
      return;
    }

    setChangingPassword(true);
    try {
      await api.post(ENDPOINTS.auth.changePassword, {
        oldPassword,
        newPassword,
      });
      setPasswordChanged(true);
      setOldPassword('');
      setNewPassword('');
      setConfirmPassword('');
      setTimeout(() => setPasswordChanged(false), 3000);
    } catch {
      setPasswordError(t('accountSettingsPage.incorrectPassword'));
    }
    setChangingPassword(false);
  };

  const handleDeleteAccount = async () => {
    if (deleteConfirmText !== 'DELETE') return;
    setDeleting(true);
    try {
      await api.delete(ENDPOINTS.users.profile);
      await logout();
      navigate('/');
    } catch {
      // Silently ignore delete errors
    }
    setDeleting(false);
  };

  return (
    <DashboardLayout>
      <div className="max-w-2xl mx-auto">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-center gap-3 mb-8"
        >
          <Button variant="ghost" size="sm" onClick={() => navigate('/dashboard/settings')}>
            <ArrowLeft className="w-4 h-4 mr-1" />
            {t('accountSettingsPage.back')}
          </Button>
          <h1 className="text-2xl font-bold">{t('accountSettingsPage.title')}</h1>
        </motion.div>

        {/* Change Password */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.05 }}
          className="bg-card rounded-2xl border border-border p-6 mb-6"
        >
          <div className="flex items-center gap-3 mb-4">
            <div className="w-10 h-10 rounded-xl bg-blue-500/10 flex items-center justify-center">
              <Lock className="w-5 h-5 text-blue-500" />
            </div>
            <div>
              <p className="text-sm font-semibold">{t('accountSettingsPage.changePassword')}</p>
              <p className="text-xs text-muted-foreground">{t('accountSettingsPage.changePasswordDesc')}</p>
            </div>
          </div>

          <div className="space-y-3">
            {/* Old password */}
            <div className="relative">
              <input
                type={showOld ? 'text' : 'password'}
                value={oldPassword}
                onChange={(e) => setOldPassword(e.target.value)}
                placeholder={t('accountSettingsPage.currentPassword')}
                className="w-full px-4 py-3 pr-10 bg-muted/50 border border-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500"
              />
              <button
                type="button"
                onClick={() => setShowOld(!showOld)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground"
              >
                {showOld ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>
            </div>

            {/* New password */}
            <div className="relative">
              <input
                type={showNew ? 'text' : 'password'}
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                placeholder={t('accountSettingsPage.newPassword')}
                className="w-full px-4 py-3 pr-10 bg-muted/50 border border-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500"
              />
              <button
                type="button"
                onClick={() => setShowNew(!showNew)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground"
              >
                {showNew ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>
            </div>

            {/* Confirm */}
            <input
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              placeholder={t('accountSettingsPage.confirmNewPassword')}
              className="w-full px-4 py-3 bg-muted/50 border border-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500"
            />

            {passwordError && (
              <p className="text-xs text-red-500">{passwordError}</p>
            )}

            {passwordChanged && (
              <p className="text-xs text-green-500 flex items-center gap-1">
                <Check className="w-3 h-3" /> {t('accountSettingsPage.passwordChangedSuccess')}
              </p>
            )}

            <Button
              onClick={handleChangePassword}
              disabled={!oldPassword || !newPassword || !confirmPassword || changingPassword}
              className="bg-blue-500 hover:bg-blue-600"
            >
              {changingPassword ? <Spinner size="sm" className="mr-2" /> : null}
              {changingPassword ? t('accountSettingsPage.changing') : t('accountSettingsPage.changePasswordBtn')}
            </Button>
          </div>
        </motion.div>

        {/* Account Info */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="bg-card rounded-2xl border border-border p-6 mb-6"
        >
          <p className="text-sm font-semibold mb-3">{t('accountSettingsPage.accountInfo')}</p>
          <div className="space-y-2 text-sm">
            <div className="flex justify-between py-2 border-b border-border">
              <span className="text-muted-foreground">{t('accountSettingsPage.emailLabel')}</span>
              <span>{user?.email}</span>
            </div>
            <div className="flex justify-between py-2 border-b border-border">
              <span className="text-muted-foreground">{t('accountSettingsPage.planLabel')}</span>
              <span className="capitalize">{user?.plan}</span>
            </div>
            <div className="flex justify-between py-2 border-b border-border">
              <span className="text-muted-foreground">{t('accountSettingsPage.emailVerified')}</span>
              <span>{user?.emailVerified ? t('accountSettingsPage.yes') : t('accountSettingsPage.no')}</span>
            </div>
            <div className="flex justify-between py-2">
              <span className="text-muted-foreground">{t('accountSettingsPage.memberSince')}</span>
              <span>{user?.createdAt ? new Date(user.createdAt).toLocaleDateString() : '-'}</span>
            </div>
          </div>
        </motion.div>

        {/* Delete Account */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.15 }}
          className="bg-card rounded-2xl border border-red-500/20 p-6"
        >
          <div className="flex items-center gap-3 mb-3">
            <div className="w-10 h-10 rounded-xl bg-red-500/10 flex items-center justify-center">
              <Trash2 className="w-5 h-5 text-red-500" />
            </div>
            <div>
              <p className="text-sm font-semibold text-red-500">{t('accountSettingsPage.deleteAccount')}</p>
              <p className="text-xs text-muted-foreground">{t('accountSettingsPage.deleteAccountDesc')}</p>
            </div>
          </div>

          {!showDeleteConfirm ? (
            <Button
              variant="outline"
              onClick={() => setShowDeleteConfirm(true)}
              className="text-red-500 border-red-500/30 hover:bg-red-500/5"
            >
              {t('accountSettingsPage.deleteMyAccount')}
            </Button>
          ) : (
            <div className="space-y-3 p-4 bg-red-500/5 rounded-xl border border-red-500/20">
              <div className="flex items-start gap-2">
                <AlertTriangle className="w-5 h-5 text-red-500 shrink-0 mt-0.5" />
                <div>
                  <p className="text-sm font-medium text-red-500">{t('accountSettingsPage.cannotBeUndone')}</p>
                  <p className="text-xs text-muted-foreground mt-1">
                    {t('accountSettingsPage.deleteWarning')}
                  </p>
                </div>
              </div>
              <div>
                <label className="text-xs text-muted-foreground mb-1 block" dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(t('accountSettingsPage.typeDeleteToConfirm')) }} />
                <input
                  value={deleteConfirmText}
                  onChange={(e) => setDeleteConfirmText(e.target.value)}
                  placeholder="DELETE"
                  className="w-full px-3 py-2 bg-background border border-red-500/30 rounded-lg text-sm focus:outline-none"
                />
              </div>
              <div className="flex gap-2">
                <Button
                  onClick={handleDeleteAccount}
                  disabled={deleteConfirmText !== 'DELETE' || deleting}
                  className="bg-red-500 hover:bg-red-600"
                >
                  {deleting ? <Spinner size="sm" className="mr-2" /> : null}
                  {deleting ? t('accountSettingsPage.deleting') : t('accountSettingsPage.deleteForever')}
                </Button>
                <Button variant="outline" onClick={() => { setShowDeleteConfirm(false); setDeleteConfirmText(''); }}>
                  {t('accountSettingsPage.cancel')}
                </Button>
              </div>
            </div>
          )}
        </motion.div>
      </div>
    </DashboardLayout>
  );
}

export default AccountSettingsPage;

import { useState, useRef, useCallback, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { motion } from 'framer-motion';
import { DashboardLayout } from '@/layouts/DashboardLayout';
import { Button } from '@/components/ui/button';
import { Spinner } from '@/components/ui/spinner';
import { FlashcardEditor, type FlashcardEditorRef } from './FlashcardEditor';
import api from '@/services/api';
import { ENDPOINTS } from '@/config/api';
import {
  ArrowLeft,
  Loader2,
  Check,
  Library,
} from 'lucide-react';

export function AddFlashcardPage() {
  const { t } = useTranslation();
  const { id: studySetId } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const editorRef = useRef<FlashcardEditorRef>(null);

  // ── Study set info ───────────────────────────────────────────────
  const [studySetTitle, setStudySetTitle] = useState<string | null>(null);
  const [isLoadingSet, setIsLoadingSet] = useState(true);

  // ── Card counts (from FlashcardEditor) ──────────────────────────
  const [cardCounts, setCardCounts] = useState({ total: 0, valid: 0 });

  // ── Save state ───────────────────────────────────────────────────
  const [isSaving, setIsSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);

  // ── Fetch study set title ────────────────────────────────────────
  useEffect(() => {
    if (!studySetId) return;
    setIsLoadingSet(true);
    api.get(ENDPOINTS.studySets.get(studySetId))
      .then((res) => setStudySetTitle(res.data.title || 'Study Set'))
      .catch(() => setStudySetTitle('Study Set'))
      .finally(() => setIsLoadingSet(false));
  }, [studySetId]);

  const handleCountChange = useCallback((total: number, valid: number) => {
    setCardCounts({ total, valid });
  }, []);

  // ── Save: bulk add to existing study set ─────────────────────────
  const handleSave = async () => {
    if (!studySetId) return;
    const validCards = editorRef.current?.getValidCards() || [];
    if (validCards.length === 0) return;

    setIsSaving(true);
    setSaveError(null);
    try {
      await api.post(`/study-sets/${studySetId}/flashcards/bulk`, { flashcards: validCards });
      navigate(`/dashboard/study-sets/${studySetId}`);
    } catch {
      setSaveError(t('addFlashcard.failedSave'));
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoadingSet) {
    return (
      <DashboardLayout>
        <div className="flex items-center justify-center py-20">
          <Spinner className="w-6 h-6" />
        </div>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout>
      <div className="max-w-4xl mx-auto pb-24">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-center gap-4 mb-8"
        >
          <button onClick={() => navigate(-1)} className="p-2 rounded-lg hover:bg-muted transition-colors">
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-2xl font-bold">{t('addFlashcard.title')}</h1>
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Library className="w-3.5 h-3.5" />
              <span>{studySetTitle}</span>
            </div>
          </div>
        </motion.div>

        {/* Error */}
        {saveError && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-red-500/10 border border-red-500/20 text-red-500 rounded-lg p-4 mb-6"
          >
            {saveError}
          </motion.div>
        )}

        {/* ═══════════ Flashcard Editor (same as Create page) ═══════════ */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.05 }}
        >
          <FlashcardEditor ref={editorRef} onCountChange={handleCountChange} studySetId={studySetId} />
        </motion.div>

        {/* ═══════════ Sticky bottom bar ═══════════ */}
        <div className="fixed bottom-0 left-0 right-0 z-50 bg-background/95 backdrop-blur-sm border-t border-border">
          <div className="max-w-4xl mx-auto flex items-center justify-between px-6 py-3">
            <div className="flex items-center gap-3">
              <Button type="button" variant="outline" size="sm" onClick={() => navigate(-1)}>
                {t('common.cancel')}
              </Button>
              {cardCounts.total > 0 && (
                <p className="text-sm text-muted-foreground hidden sm:block">
                  {t('addFlashcard.cardsReady', { valid: cardCounts.valid, total: cardCounts.total })}
                  {cardCounts.total > cardCounts.valid && (
                    <span className="text-amber-500 ml-1">{t('addFlashcard.incomplete', { count: cardCounts.total - cardCounts.valid })}</span>
                  )}
                </p>
              )}
            </div>
            <Button
              type="button"
              onClick={handleSave}
              disabled={cardCounts.valid === 0 || isSaving}
              className="bg-green-500 hover:bg-green-600 min-w-[140px] sm:min-w-[180px]"
            >
              {isSaving ? (
                <><Loader2 className="w-4 h-4 mr-2 animate-spin" />{t('common.saving')}</>
              ) : (
                <><Check className="w-4 h-4 mr-2" />{cardCounts.valid > 0 ? t('addFlashcard.saveCards', { count: cardCounts.valid }) : t('addFlashcard.saveCardsButton')}</>
              )}
            </Button>
          </div>
        </div>
      </div>
    </DashboardLayout>
  );
}

import { useEffect, useState, useMemo, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { motion } from 'framer-motion';
import { DashboardLayout } from '@/layouts/DashboardLayout';
import { Spinner } from '@/components/ui/spinner';
import { StudyHeatmap } from '@/components/StudyHeatmap';
import { StreakCalendar } from '@/components/StreakCalendar';
import { XPProgressBar } from '@/components/XPProgressBar';
import { useGamificationStore } from '@/stores/useGamificationStore';
import api from '@/services/api';
import { ENDPOINTS } from '@/config/api';
import {
  LineChart,
  Line,
  PieChart,
  Pie,
  Cell,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import {
  Clock,
  BookOpen,
  FileQuestion,
  Target,
  TrendingUp,
} from 'lucide-react';

type DateRange = '7d' | '30d' | '90d' | 'all';

interface AnalyticsData {
  totalStudyTime: number;
  cardsReviewed: number;
  quizzesTaken: number;
  avgScore: number;
  currentStreak: number;
  longestStreak: number;
}

interface ActivityEntry {
  date: string;
  sessions: number;
  cardsReviewed: number;
  studyMinutes: number;
}

interface PerformanceData {
  accuracy: number;
  improvementRate: number;
  cardsByStatus: Record<string, number>;
  retentionCurve: Array<{ day: number; retention: number }>;
}

const STATUS_COLORS: Record<string, string> = {
  New: '#3b82f6',
  Learning: '#f59e0b',
  Review: '#a855f7',
  Mastered: '#22c55e',
};

export function AnalyticsPage() {
  const { t } = useTranslation();
  const { fetchGamification } = useGamificationStore();
  const [analytics, setAnalytics] = useState<AnalyticsData | null>(null);
  const [activity, setActivity] = useState<ActivityEntry[]>([]);
  const [performance, setPerformance] = useState<PerformanceData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [dateRange, setDateRange] = useState<DateRange>('30d');
  const [timeView, setTimeView] = useState<'daily' | 'weekly'>('daily');

  const fetchAnalytics = useCallback(async () => {
    setIsLoading(true);
    try {
      const [analyticsRes, activityRes, performanceRes] = await Promise.all([
        api.get(ENDPOINTS.analytics.me, { params: { range: dateRange } }).catch(() => ({ data: null })),
        api.get(ENDPOINTS.analytics.activity, { params: { range: dateRange } }).catch(() => ({ data: [] })),
        api.get(ENDPOINTS.analytics.performance, { params: { range: dateRange } }).catch(() => ({ data: null })),
      ]);

      setAnalytics(analyticsRes.data || {
        totalStudyTime: 0, cardsReviewed: 0, quizzesTaken: 0,
        avgScore: 0, currentStreak: 0, longestStreak: 0,
      });
      setActivity(activityRes.data || []);
      setPerformance(performanceRes.data || {
        accuracy: 0, improvementRate: 0,
        cardsByStatus: { New: 0, Learning: 0, Review: 0, Mastered: 0 },
        retentionCurve: [],
      });
    } catch {
      // Fallback with empty data
      setAnalytics({ totalStudyTime: 0, cardsReviewed: 0, quizzesTaken: 0, avgScore: 0, currentStreak: 0, longestStreak: 0 });
      setActivity([]);
      setPerformance({ accuracy: 0, improvementRate: 0, cardsByStatus: {}, retentionCurve: [] });
    } finally {
      setIsLoading(false);
    }
  }, [dateRange]);

  useEffect(() => {
    fetchGamification();
    fetchAnalytics();
  }, [dateRange, fetchAnalytics, fetchGamification]);

  // Transform activity data for heatmap
  const heatmapData = useMemo(() => {
    const map: Record<string, number> = {};
    activity.forEach((a) => { map[a.date] = a.sessions; });
    return map;
  }, [activity]);

  // Active days set for streak calendar
  const activeDaysSet = useMemo(() => {
    return new Set(activity.filter((a) => a.sessions > 0).map((a) => a.date));
  }, [activity]);

  // Study time bar chart data
  const studyTimeData = useMemo(() => {
    if (timeView === 'weekly') {
      const weeks: Record<string, number> = {};
      activity.forEach((a) => {
        const d = new Date(a.date);
        const weekStart = new Date(d);
        weekStart.setDate(d.getDate() - d.getDay());
        const key = weekStart.toISOString().split('T')[0];
        weeks[key] = (weeks[key] || 0) + a.studyMinutes;
      });
      return Object.entries(weeks).map(([date, minutes]) => ({
        date: new Date(date).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }),
        minutes,
      }));
    }
    return activity.slice(-14).map((a) => ({
      date: new Date(a.date).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }),
      minutes: a.studyMinutes,
    }));
  }, [activity, timeView]);

  // Pie chart data
  const pieData = useMemo(() => {
    if (!performance?.cardsByStatus) return [];
    return Object.entries(performance.cardsByStatus)
      .filter(([, count]) => count > 0)
      .map(([name, value]) => ({ name, value }));
  }, [performance]);

  if (isLoading) {
    return (
      <DashboardLayout>
        <div className="flex items-center justify-center py-12">
          <Spinner className="w-8 h-8" />
        </div>
      </DashboardLayout>
    );
  }

  const formatTime = (minutes: number) => {
    if (minutes < 60) return `${minutes}m`;
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return m > 0 ? `${h}h ${m}m` : `${h}h`;
  };

  return (
    <DashboardLayout>
      <div className="max-w-6xl mx-auto space-y-6">
        {/* Header */}
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-2">
            <div>
              <h1 className="text-2xl font-bold">{t('analytics.title')}</h1>
              <p className="text-sm text-muted-foreground">{t('analytics.subtitle')}</p>
            </div>
            {/* Date range selector */}
            <div className="flex items-center gap-1 bg-muted rounded-lg p-1">
              {(['7d', '30d', '90d', 'all'] as DateRange[]).map((range) => (
                <button
                  key={range}
                  onClick={() => setDateRange(range)}
                  className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                    dateRange === range
                      ? 'bg-background shadow text-foreground'
                      : 'text-muted-foreground hover:text-foreground'
                  }`}
                >
                  {t(`analytics.dateRange.${range}`)}
                </button>
              ))}
            </div>
          </div>
        </motion.div>

        {/* XP Progress */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.05 }}
          className="bg-card border border-border rounded-xl p-5"
        >
          <XPProgressBar />
        </motion.div>

        {/* Top stats row */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="grid grid-cols-2 lg:grid-cols-4 gap-4"
        >
          <div className="bg-card border border-border rounded-xl p-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-blue-500/10 flex items-center justify-center">
                <Clock className="w-5 h-5 text-blue-500" />
              </div>
              <div>
                <p className="text-xl font-bold">{formatTime(analytics?.totalStudyTime || 0)}</p>
                <p className="text-xs text-muted-foreground">{t('analytics.studyTime')}</p>
              </div>
            </div>
          </div>
          <div className="bg-card border border-border rounded-xl p-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-green-500/10 flex items-center justify-center">
                <BookOpen className="w-5 h-5 text-green-500" />
              </div>
              <div>
                <p className="text-xl font-bold">{analytics?.cardsReviewed || 0}</p>
                <p className="text-xs text-muted-foreground">{t('analytics.cardsReviewed')}</p>
              </div>
            </div>
          </div>
          <div className="bg-card border border-border rounded-xl p-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-purple-500/10 flex items-center justify-center">
                <FileQuestion className="w-5 h-5 text-purple-500" />
              </div>
              <div>
                <p className="text-xl font-bold">{analytics?.quizzesTaken || 0}</p>
                <p className="text-xs text-muted-foreground">{t('dashboard.stats.quizzesDone')}</p>
              </div>
            </div>
          </div>
          <div className="bg-card border border-border rounded-xl p-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-amber-500/10 flex items-center justify-center">
                <Target className="w-5 h-5 text-amber-500" />
              </div>
              <div>
                <p className="text-xl font-bold">{Math.round(analytics?.avgScore || 0)}%</p>
                <p className="text-xs text-muted-foreground">{t('analytics.avgScore')}</p>
              </div>
            </div>
          </div>
        </motion.div>

        {/* Study Heatmap */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.15 }}
          className="bg-card border border-border rounded-xl p-5"
        >
          <h3 className="font-medium text-sm mb-4">{t('analytics.studyTime')}</h3>
          <div className="overflow-x-auto">
            <StudyHeatmap data={heatmapData} weeks={dateRange === '7d' ? 8 : dateRange === '30d' ? 16 : dateRange === '90d' ? 26 : 52} />
          </div>
        </motion.div>

        {/* Charts row */}
        <div className="grid md:grid-cols-2 gap-4">
          {/* Streak Calendar */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
            className="bg-card border border-border rounded-xl p-5"
          >
            <h3 className="font-medium text-sm mb-4">{t('analytics.streak')}</h3>
            <StreakCalendar activeDays={activeDaysSet} />
          </motion.div>

          {/* Card Mastery Breakdown */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.25 }}
            className="bg-card border border-border rounded-xl p-5"
          >
            <h3 className="font-medium text-sm mb-4">{t('analytics.cardMastery')}</h3>
            {pieData.length > 0 ? (
              <div className="flex items-center gap-6">
                <ResponsiveContainer width={150} height={150}>
                  <PieChart>
                    <Pie data={pieData} cx="50%" cy="50%" innerRadius={45} outerRadius={70} paddingAngle={2} dataKey="value">
                      {pieData.map((entry) => (
                        <Cell key={entry.name} fill={STATUS_COLORS[entry.name] || '#888'} />
                      ))}
                    </Pie>
                  </PieChart>
                </ResponsiveContainer>
                <div className="space-y-2">
                  {pieData.map((entry) => (
                    <div key={entry.name} className="flex items-center gap-2">
                      <div className="w-3 h-3 rounded-full" style={{ backgroundColor: STATUS_COLORS[entry.name] || '#888' }} />
                      <span className="text-xs text-muted-foreground">{t(`analytics.cardStatus.${entry.name.toLowerCase()}`)}</span>
                      <span className="text-xs font-medium">{entry.value}</span>
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              <p className="text-sm text-muted-foreground text-center py-8">{t('analytics.noCardData')}</p>
            )}
          </motion.div>
        </div>

        {/* Retention Curve + Study Time */}
        <div className="grid md:grid-cols-2 gap-4">
          {/* Retention Curve */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="bg-card border border-border rounded-xl p-5"
          >
            <div className="flex items-center gap-2 mb-4">
              <TrendingUp className="w-4 h-4 text-green-500" />
              <h3 className="font-medium text-sm">{t('analytics.retentionCurve')}</h3>
            </div>
            {performance?.retentionCurve && performance.retentionCurve.length > 0 ? (
              <ResponsiveContainer width="100%" height={160}>
                <LineChart data={performance.retentionCurve}>
                  <XAxis dataKey="day" tick={{ fontSize: 11 }} axisLine={false} tickLine={false} />
                  <YAxis tick={{ fontSize: 11 }} axisLine={false} tickLine={false} domain={[0, 100]} />
                  <Tooltip
                    contentStyle={{
                      borderRadius: '8px',
                      border: '1px solid hsl(var(--border))',
                      backgroundColor: 'hsl(var(--card))',
                      fontSize: '12px',
                    }}
                    formatter={(value) => [`${value ?? 0}%`, t('analytics.retention')]}
                  />
                  <Line type="monotone" dataKey="retention" stroke="#22c55e" strokeWidth={2} dot={{ r: 3 }} />
                </LineChart>
              </ResponsiveContainer>
            ) : (
              <p className="text-sm text-muted-foreground text-center py-8">{t('analytics.notEnoughData')}</p>
            )}
          </motion.div>

          {/* Study Time Bar Chart */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.35 }}
            className="bg-card border border-border rounded-xl p-5"
          >
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-medium text-sm">{t('analytics.studyTime')}</h3>
              <div className="flex items-center gap-1 bg-muted rounded-md p-0.5">
                <button
                  onClick={() => setTimeView('daily')}
                  className={`px-2 py-1 text-[10px] font-medium rounded-sm transition-colors ${timeView === 'daily' ? 'bg-background shadow' : 'text-muted-foreground'}`}
                >
                  {t('analytics.daily')}
                </button>
                <button
                  onClick={() => setTimeView('weekly')}
                  className={`px-2 py-1 text-[10px] font-medium rounded-sm transition-colors ${timeView === 'weekly' ? 'bg-background shadow' : 'text-muted-foreground'}`}
                >
                  {t('analytics.weekly')}
                </button>
              </div>
            </div>
            {studyTimeData.length > 0 ? (
              <ResponsiveContainer width="100%" height={160}>
                <BarChart data={studyTimeData}>
                  <XAxis dataKey="date" tick={{ fontSize: 10 }} axisLine={false} tickLine={false} />
                  <YAxis tick={{ fontSize: 11 }} axisLine={false} tickLine={false} />
                  <Tooltip
                    contentStyle={{
                      borderRadius: '8px',
                      border: '1px solid hsl(var(--border))',
                      backgroundColor: 'hsl(var(--card))',
                      fontSize: '12px',
                    }}
                    formatter={(value) => [`${value ?? 0}m`, t('analytics.studyTime')]}
                  />
                  <Bar dataKey="minutes" fill="#22c55e" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <p className="text-sm text-muted-foreground text-center py-8">{t('analytics.noStudyData')}</p>
            )}
          </motion.div>
        </div>
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { DashboardLayout } from '@/layouts/DashboardLayout';
import { Button } from '@/components/ui/button';
import { motion } from 'framer-motion';
import { ArrowLeft, Sun, Moon, Monitor, Check } from 'lucide-react';

type Theme = 'light' | 'dark' | 'system';

function getStoredTheme(): Theme {
  return (localStorage.getItem('theme') as Theme) || 'system';
}

function applyTheme(theme: Theme) {
  const root = document.documentElement;

  if (theme === 'system') {
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    root.classList.toggle('dark', prefersDark);
  } else {
    root.classList.toggle('dark', theme === 'dark');
  }

  localStorage.setItem('theme', theme);
}

