          </div>
        </form>
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { motion } from 'framer-motion';
import { DashboardLayout } from '@/layouts/DashboardLayout';
import { Button } from '@/components/ui/button';
import { Spinner } from '@/components/ui/spinner';
import { useNotesStore } from '@/stores/useNotesStore';
import {
  ArrowLeft,
  Bold,
  Italic,
  Heading1,
  Heading2,
  List,
  ListOrdered,
  Highlighter,
  Save,
  Loader2,
  Tag,
  X,
} from 'lucide-react';

export function EditNotePage() {
  const { id: studySetId, noteId } = useParams<{ id: string; noteId: string }>();
  const navigate = useNavigate();
  const { t } = useTranslation();
  const { currentNote, isLoading, fetchNote, updateNote } = useNotesStore();

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [tagInput, setTagInput] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);

  useEffect(() => {
    if (noteId) {
      fetchNote(noteId);
    }
  }, [noteId, fetchNote]);

  useEffect(() => {
    if (currentNote && !isInitialized) {
      setTitle(currentNote.title);
      setContent(currentNote.content);
      setTags(currentNote.tags || []);
      setIsInitialized(true);
    }
  }, [currentNote, isInitialized]);

  const handleAddTag = () => {
    if (tagInput.trim() && !tags.includes(tagInput.trim())) {
      setTags([...tags, tagInput.trim()]);
      setTagInput('');
    }
  };

  const handleRemoveTag = (tag: string) => {
    setTags(tags.filter((t) => t !== tag));
  };

  const handleSave = async () => {
    if (!title.trim()) {
      setError(t('editNote.errorTitle'));
      return;
    }
    if (!content.trim()) {
      setError(t('editNote.errorContent'));
      return;
    }

    setIsSaving(true);
    try {
      await updateNote(noteId!, {
        title: title.trim(),
        content: content.trim(),
        tags,
      });
      navigate(`/dashboard/study-sets/${studySetId}/notes/${noteId}`);
    } catch {
      setError(t('editNote.errorUpdate'));
    } finally {
      setIsSaving(false);
    }
  };

  const applyFormatting = (type: string) => {
    const textarea = document.getElementById('note-content') as HTMLTextAreaElement;
    if (!textarea) return;

    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selectedText = content.substring(start, end);

    let before = '';
    let after = '';

    switch (type) {
      case 'bold':
        before = '**';
        after = '**';
        break;
      case 'italic':
        before = '_';
        after = '_';
        break;
      case 'h1':
        before = '# ';
        break;
      case 'h2':
        before = '## ';
        break;
      case 'bullet':
        before = '- ';
        break;
      case 'numbered':
        before = '1. ';
        break;
      case 'highlight':
        before = '==';
        after = '==';
        break;
    }

    const newContent =
      content.substring(0, start) +
      before +
      selectedText +
      after +
      content.substring(end);

    setContent(newContent);

    // Restore cursor position
    setTimeout(() => {
      textarea.focus();
      textarea.setSelectionRange(start + before.length, end + before.length);
    }, 0);
  };

  if (isLoading || !currentNote) {
    return (
      <DashboardLayout>
        <div className="flex items-center justify-center min-h-[50vh]">
          <Spinner className="w-8 h-8" />
        </div>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout>
      <div className="max-w-3xl mx-auto">
        {/* Header */}
        <div className="flex items-center gap-4 mb-6">
          <button
            onClick={() => navigate(`/dashboard/study-sets/${studySetId}/notes/${noteId}`)}
            className="p-2 rounded-lg hover:bg-muted transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div className="flex-1">
            <h1 className="text-2xl font-bold">{t('editNote.title')}</h1>
            <p className="text-sm text-muted-foreground">{t('editNote.subtitle')}</p>
          </div>
          <Button
            className="bg-green-500 hover:bg-green-600"
            onClick={handleSave}
            disabled={isSaving}
          >
            {isSaving ? (
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
            ) : (
              <Save className="w-4 h-4 mr-2" />
            )}
            {t('editNote.saveChanges')}
          </Button>
        </div>

        {error && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            className="mb-4 p-3 rounded-lg bg-red-500/10 border border-red-500/30 text-red-500 text-sm"
          >
            {error}
          </motion.div>
        )}

        {/* Title Input */}
        <div className="mb-4">
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder={t('editNote.titlePlaceholder')}
            className="w-full px-4 py-3 text-xl font-semibold bg-transparent border-0 border-b-2 border-border focus:border-green-500 focus:outline-none transition-colors"
          />
        </div>

        {/* Formatting Toolbar */}
        <div className="flex items-center gap-1 p-2 mb-2 bg-muted/50 rounded-lg">
          <button
            onClick={() => applyFormatting('bold')}
            className="p-2 rounded-lg hover:bg-muted transition-colors"
            title={t('editNote.bold')}
          >
            <Bold className="w-4 h-4" />
          </button>
          <button
            onClick={() => applyFormatting('italic')}
            className="p-2 rounded-lg hover:bg-muted transition-colors"
            title={t('editNote.italic')}
          >
            <Italic className="w-4 h-4" />
          </button>
          <div className="w-px h-5 bg-border mx-1" />
          <button
            onClick={() => applyFormatting('h1')}
            className="p-2 rounded-lg hover:bg-muted transition-colors"
            title={t('editNote.heading1')}
          >
            <Heading1 className="w-4 h-4" />
          </button>
          <button
            onClick={() => applyFormatting('h2')}
            className="p-2 rounded-lg hover:bg-muted transition-colors"
            title={t('editNote.heading2')}
          >
            <Heading2 className="w-4 h-4" />
          </button>
          <div className="w-px h-5 bg-border mx-1" />
          <button
            onClick={() => applyFormatting('bullet')}
            className="p-2 rounded-lg hover:bg-muted transition-colors"
            title={t('editNote.bulletList')}
          >
            <List className="w-4 h-4" />
          </button>
          <button
            onClick={() => applyFormatting('numbered')}
            className="p-2 rounded-lg hover:bg-muted transition-colors"
            title={t('editNote.numberedList')}
          >
            <ListOrdered className="w-4 h-4" />
          </button>
          <div className="w-px h-5 bg-border mx-1" />
          <button
            onClick={() => applyFormatting('highlight')}
            className="p-2 rounded-lg hover:bg-muted transition-colors"
            title={t('editNote.highlight')}
          >
            <Highlighter className="w-4 h-4" />
          </button>
        </div>

        {/* Content Editor */}
        <div className="bg-card border border-border rounded-xl overflow-hidden mb-4">
          <textarea
            id="note-content"
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder={t('editNote.contentPlaceholder')}
            className="w-full min-h-[400px] p-4 bg-transparent resize-none focus:outline-none text-sm leading-relaxed font-mono"
          />
        </div>

        {/* Tags Section */}
        <div className="bg-card border border-border rounded-xl p-4">
          <div className="flex items-center gap-2 mb-3">
            <Tag className="w-4 h-4 text-muted-foreground" />
            <span className="text-sm font-medium">{t('editNote.tags')}</span>
          </div>

          <div className="flex flex-wrap gap-2 mb-3">
            {tags.map((tag) => (
              <span
                key={tag}
                className="flex items-center gap-1 px-2 py-1 text-xs bg-green-500/10 text-green-600 rounded-full"
              >
                {tag}
                <button
                  onClick={() => handleRemoveTag(tag)}
                  className="hover:text-red-500 transition-colors"
                >
                  <X className="w-3 h-3" />
                </button>
              </span>
            ))}
          </div>

          <div className="flex gap-2">
            <input
              type="text"
              value={tagInput}
              onChange={(e) => setTagInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && (e.preventDefault(), handleAddTag())}
              placeholder={t('editNote.addTagPlaceholder')}
              className="flex-1 px-3 py-2 text-sm bg-muted/50 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500/20"
            />
            <Button variant="outline" size="sm" onClick={handleAddTag}>
              {t('editNote.addTag')}
            </Button>
          </div>
        </div>
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { motion, AnimatePresence } from 'framer-motion';
import { useStudySetsStore } from '@/stores/useStudySetsStore';
import { DashboardLayout } from '@/layouts/DashboardLayout';
import { Button } from '@/components/ui/button';
import { Spinner } from '@/components/ui/spinner';
import { FlashcardEditor, type FlashcardEditorRef } from './FlashcardEditor';
import api from '@/services/api';
import type { UpdateStudySetRequest } from '@/types';
import {
  ArrowLeft,
  X,
  Plus,
  Globe,
  Lock,
  Image,
  Loader2,
  Check,
  ChevronDown,
  Calendar,
  BookOpen,
} from 'lucide-react';

export function EditStudySetPage() {
  const { t } = useTranslation();
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { currentStudySet, fetchStudySet, updateStudySet, isLoading: storeLoading, error } = useStudySetsStore();
  const editorRef = useRef<FlashcardEditorRef>(null);

  // ── Form state ─────────────────────────────────────────────────
  const [formData, setFormData] = useState<UpdateStudySetRequest>({
    title: '',
    description: '',
    isPublic: false,
    tags: [],
    coverImageUrl: '',
    examDate: '',
    examSubject: '',
  });
  const [tagInput, setTagInput] = useState('');
  const [showMoreOptions, setShowMoreOptions] = useState(false);

  // ── Card counts (from FlashcardEditor) ──────────────────────────
  const [cardCounts, setCardCounts] = useState({ total: 0, valid: 0 });

  // ── Save state ───────────────────────────────────────────────────
  const [isSaving, setIsSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    if (id) fetchStudySet(id);
  }, [id, fetchStudySet]);

  // Pre-fill form when study set loads
  useEffect(() => {
    if (currentStudySet && !loaded) {
      const hasExtras = !!(currentStudySet.coverImageUrl || (currentStudySet.tags && currentStudySet.tags.length > 0) || currentStudySet.examDate);
      setFormData({
        title: currentStudySet.title,
        description: currentStudySet.description || '',
        isPublic: currentStudySet.isPublic,
        tags: currentStudySet.tags || [],
        coverImageUrl: currentStudySet.coverImageUrl || '',
        examDate: currentStudySet.examDate || '',
        examSubject: currentStudySet.examSubject || '',
      });
      if (hasExtras) setShowMoreOptions(true);
      setLoaded(true);
    }
  }, [currentStudySet, loaded]);

  // ── Tag handlers ─────────────────────────────────────────────────
  const addTag = () => {
    if (tagInput.trim() && !formData.tags?.includes(tagInput.trim())) {
      setFormData((prev) => ({ ...prev, tags: [...(prev.tags || []), tagInput.trim()] }));
      setTagInput('');
    }
  };
  const removeTag = (tag: string) => {
    setFormData((prev) => ({ ...prev, tags: prev.tags?.filter((t) => t !== tag) }));
  };

  const handleCountChange = useCallback((total: number, valid: number) => {
    setCardCounts({ total, valid });
  }, []);

  // ── Save ─────────────────────────────────────────────────────────
  const handleSubmit = async () => {
    if (!id || !formData.title?.trim()) return;
    const validCards = editorRef.current?.getValidCards() || [];

    setIsSaving(true);
    setSaveError(null);
    try {
      await updateStudySet(id, formData);
      if (validCards.length > 0) {
        await api.post(`/study-sets/${id}/flashcards/bulk`, { flashcards: validCards });
      }
      navigate(`/dashboard/study-sets/${id}`);
    } catch {
      setSaveError(t('editStudySet.failedSave'));
    } finally {
      setIsSaving(false);
    }
  };

  if (storeLoading && !currentStudySet) {
    return (
      <DashboardLayout>
        <div className="flex items-center justify-center py-12">
          <Spinner className="w-8 h-8" />
        </div>
      </DashboardLayout>
    );
  }

  if (!currentStudySet) {
    return (
      <DashboardLayout>
        <div className="text-center py-12">
          <p className="text-red-500 mb-4">{t('editStudySet.notFound')}</p>
          <Button variant="outline" onClick={() => navigate('/dashboard')}>
            {t('editStudySet.backToDashboard')}
          </Button>
        </div>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout>
      <div className="max-w-4xl mx-auto pb-24">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-center gap-4 mb-8"
        >
          <button onClick={() => navigate(-1)} className="p-2 rounded-lg hover:bg-muted transition-colors">
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-2xl font-bold">{t('editStudySet.title')}</h1>
            <p className="text-sm text-muted-foreground">{t('editStudySet.subtitle')}</p>
          </div>
        </motion.div>

        {/* Error */}
        {(error || saveError) && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-red-500/10 border border-red-500/20 text-red-500 rounded-lg p-4 mb-6"
          >
            {error || saveError}
          </motion.div>
        )}

        {/* ═══════════ Metadata ═══════════ */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.05 }}
          className="bg-card border border-border rounded-xl p-6 mb-6"
        >
          <div className="mb-4">
            <input
              type="text"
              value={formData.title || ''}
              onChange={(e) => setFormData((prev) => ({ ...prev, title: e.target.value }))}
              placeholder={t('createStudySet.titlePlaceholder')}
              className="w-full text-xl font-semibold px-0 py-2 bg-transparent border-0 border-b-2 border-border focus:outline-none focus:border-green-500 placeholder:text-muted-foreground/50 transition-colors"
              required
            />
          </div>

          <div className="mb-3">
            <textarea
              value={formData.description || ''}
              onChange={(e) => setFormData((prev) => ({ ...prev, description: e.target.value }))}
              placeholder={t('createStudySet.descriptionPlaceholder')}
              rows={2}
              className="w-full px-0 py-1.5 text-sm bg-transparent border-0 border-b border-border/50 focus:outline-none focus:border-green-500/50 resize-none placeholder:text-muted-foreground/40 transition-colors"
            />
          </div>

          <button
            type="button"
            onClick={() => setShowMoreOptions(!showMoreOptions)}
            className="flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors"
          >
            <ChevronDown className={`w-4 h-4 transition-transform ${showMoreOptions ? 'rotate-180' : ''}`} />
            {showMoreOptions ? t('createStudySet.lessOptions') : t('createStudySet.moreOptions')}
          </button>

          <AnimatePresence>
            {showMoreOptions && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                transition={{ duration: 0.2 }}
                className="overflow-hidden"
              >
                <div className="pt-4 space-y-4 border-t border-border/50 mt-4">
                  <div>
                    <label className="block text-sm font-medium mb-1.5">{t('createStudySet.coverImageUrl')}</label>
                    <div className="relative">
                      <Image className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                      <input
                        type="url"
                        value={formData.coverImageUrl || ''}
                        onChange={(e) => setFormData((prev) => ({ ...prev, coverImageUrl: e.target.value }))}
                        placeholder={t('createStudySet.coverImagePlaceholder')}
                        className="w-full pl-9 pr-4 py-2 text-sm bg-background border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500/20 focus:border-green-500"
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium mb-1.5">{t('createStudySet.tags')}</label>
                    <div className="flex gap-2 mb-2">
                      <input
                        type="text"
                        value={tagInput}
                        onChange={(e) => setTagInput(e.target.value)}
                        onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addTag(); } }}
                        placeholder={t('createStudySet.addTag')}
                        className="flex-1 px-3 py-2 text-sm bg-background border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500/20 focus:border-green-500"
                      />
                      <Button type="button" variant="outline" size="sm" onClick={addTag} disabled={!tagInput.trim()}>
                        <Plus className="w-4 h-4" />
                      </Button>
                    </div>
                    {formData.tags && formData.tags.length > 0 && (
                      <div className="flex flex-wrap gap-1.5">
                        {formData.tags.map((tag) => (
                          <span key={tag} className="inline-flex items-center gap-1 px-2 py-0.5 bg-green-500/10 text-green-600 dark:text-green-400 rounded-full text-xs">
                            {tag}
                            <button type="button" onClick={() => removeTag(tag)} className="p-0.5 hover:bg-green-500/20 rounded-full">
                              <X className="w-3 h-3" />
                            </button>
                          </span>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Exam Date */}
                  <div>
                    <label className="block text-sm font-medium mb-1.5">{t('createStudySet.examDate')}</label>
                    <div className="relative">
                      <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                      <input
                        type="datetime-local"
                        value={formData.examDate || ''}
                        onChange={(e) => setFormData((prev) => ({ ...prev, examDate: e.target.value || undefined }))}
                        min={new Date().toISOString().slice(0, 16)}
                        className="w-full pl-9 pr-4 py-2 text-sm bg-background border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500/20 focus:border-green-500"
                      />
                    </div>
                    <p className="text-xs text-muted-foreground mt-1">{t('createStudySet.examDateHint')}</p>
                  </div>

                  {/* Exam Subject */}
                  {formData.examDate && (
                    <div>
                      <label className="block text-sm font-medium mb-1.5">{t('createStudySet.examSubject')}</label>
                      <div className="relative">
                        <BookOpen className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                        <input
                          type="text"
                          value={formData.examSubject || ''}
                          onChange={(e) => setFormData((prev) => ({ ...prev, examSubject: e.target.value }))}
                          placeholder={t('createStudySet.examSubjectPlaceholder')}
                          className="w-full pl-9 pr-4 py-2 text-sm bg-background border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500/20 focus:border-green-500"
                        />
                      </div>
                    </div>
                  )}

                  <div>
                    <label className="block text-sm font-medium mb-1.5">{t('createStudySet.visibility')}</label>
                    <div className="flex gap-2">
                      <button
                        type="button"
                        onClick={() => setFormData((prev) => ({ ...prev, isPublic: false }))}
                        className={`flex-1 flex items-center justify-center gap-2 px-3 py-2 text-sm rounded-lg border transition-colors ${!formData.isPublic ? 'border-green-500 bg-green-500/10 text-green-600 dark:text-green-400' : 'border-border hover:border-green-500/50'}`}
                      >
                        <Lock className="w-3.5 h-3.5" />{t('createStudySet.private')}
                      </button>
                      <button
                        type="button"
                        onClick={() => setFormData((prev) => ({ ...prev, isPublic: true }))}
                        className={`flex-1 flex items-center justify-center gap-2 px-3 py-2 text-sm rounded-lg border transition-colors ${formData.isPublic ? 'border-green-500 bg-green-500/10 text-green-600 dark:text-green-400' : 'border-border hover:border-green-500/50'}`}
                      >
                        <Globe className="w-3.5 h-3.5" />{t('createStudySet.public')}
                      </button>
                    </div>
                    <p className="text-xs text-muted-foreground mt-1.5">
                      {formData.isPublic ? t('createStudySet.publicHint') : t('createStudySet.privateHint')}
                    </p>
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </motion.div>

        {/* ═══════════ Flashcard Editor (add new cards) ═══════════ */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
        >
          <FlashcardEditor ref={editorRef} onCountChange={handleCountChange} studySetId={id} />
        </motion.div>

        {/* ═══════════ Sticky bottom bar ═══════════ */}
        <div className="fixed bottom-0 left-0 right-0 z-50 bg-background/95 backdrop-blur-sm border-t border-border">
          <div className="max-w-4xl mx-auto flex items-center justify-between px-6 py-3">
            <div className="flex items-center gap-3">
              <Button type="button" variant="outline" size="sm" onClick={() => navigate(-1)}>
                {t('common.cancel')}
              </Button>
              {cardCounts.total > 0 && (
                <p className="text-sm text-muted-foreground hidden sm:block">
                  {t('editStudySet.newCardsReady', { valid: cardCounts.valid, total: cardCounts.total })}
                  {cardCounts.total > cardCounts.valid && (
                    <span className="text-amber-500 ml-1">{t('createStudySet.incomplete', { count: cardCounts.total - cardCounts.valid })}</span>
                  )}
                </p>
              )}
            </div>
            <Button
              type="button"
              onClick={handleSubmit}
              disabled={!formData.title?.trim() || isSaving || storeLoading}
              className="bg-green-500 hover:bg-green-600 min-w-[140px] sm:min-w-[180px]"
            >
              {isSaving ? (
                <><Loader2 className="w-4 h-4 mr-2 animate-spin" />{t('common.saving')}</>
              ) : (
                <><Check className="w-4 h-4 mr-2" />{cardCounts.valid > 0 ? t('editStudySet.saveChangesWithCount', { count: cardCounts.valid }) : t('editFlashcard.saveChanges')}</>
              )}
            </Button>
          </div>
        </div>
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { motion, AnimatePresence } from 'framer-motion';
import { DashboardLayout } from '@/layouts/DashboardLayout';
import { Button } from '@/components/ui/button';
import api from '@/services/api';
import { ENDPOINTS } from '@/config/api';
import {
  Plus,
  FileText,
  Loader2,
  Trash2,
  Play,
  Sparkles,
  Clock,
  CheckCircle,
  XCircle,
  AlertCircle,
  ChevronRight,
  Upload,
  Brain,
  BarChart3,
  Target,
  BookOpen,
  X,
  Bell,
  RotateCcw,
} from 'lucide-react';
import { cn } from '@/lib/utils';

interface ExamStyle {
  questionTypes: string[];
  difficultyDistribution: { easy: number; medium: number; hard: number };
  averageQuestionLength: number;
  topicsCovered: string[];
  formatPatterns: string[];
  languageStyle: string;
}

interface ExamClone {
  id: string;
  userId: string;
  title: string;
  subject: string | null;
  originalFileUrl: string | null;
  extractedStyle: ExamStyle | null;
  status: 'pending' | 'processing' | 'completed' | 'failed';
  originalQuestionCount: number;
  generatedQuestionCount: number;
  createdAt: string;
  updatedAt: string;
}

const STATUS_CONFIG = {
  pending: { labelKey: 'examClone.status.pending', color: 'text-amber-500', bg: 'bg-amber-500/10', icon: Clock },
  processing: { labelKey: 'examClone.status.processing', color: 'text-blue-500', bg: 'bg-blue-500/10', icon: Loader2 },
  completed: { labelKey: 'examClone.status.completed', color: 'text-green-500', bg: 'bg-green-500/10', icon: CheckCircle },
  failed: { labelKey: 'examClone.status.failed', color: 'text-red-500', bg: 'bg-red-500/10', icon: XCircle },
};

export default function ExamClonePage() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [exams, setExams] = useState<ExamClone[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [reviewQueueCount, setReviewQueueCount] = useState(0);
  const [showReviewNotification, setShowReviewNotification] = useState(false);
  const pollIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const fetchReviewQueueCount = useCallback(async () => {
    try {
      const response = await api.get(ENDPOINTS.examClone.reviewQueue);
      const count = response.data.length;
      if (count > 0 && reviewQueueCount === 0) {
        // New items due - show notification
        setShowReviewNotification(true);
      }
      setReviewQueueCount(count);
    } catch (err) {
      console.error('Failed to fetch review queue:', err);
    }
  }, [reviewQueueCount]);

  const fetchExams = useCallback(async () => {
    try {
      setIsLoading(true);
      const response = await api.get<ExamClone[]>(ENDPOINTS.examClone.list);
      setExams(response.data);
    } catch (err) {
      console.error('Failed to fetch exams:', err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchExams();
    fetchReviewQueueCount();

    // Poll every 30 seconds for new review items
    pollIntervalRef.current = setInterval(fetchReviewQueueCount, 30000);

    return () => {
      if (pollIntervalRef.current) {
        clearInterval(pollIntervalRef.current);
      }
    };
  }, [fetchExams, fetchReviewQueueCount]);

  const handleDelete = async (id: string) => {
    try {
      await api.delete(ENDPOINTS.examClone.get(id));
      setExams((prev) => prev.filter((e) => e.id !== id));
      setDeleteId(null);
    } catch (err) {
      console.error('Failed to delete exam:', err);
    }
  };

  const handleUploadSuccess = (newExam: ExamClone) => {
    setExams((prev) => [newExam, ...prev]);
    setShowUploadModal(false);
  };

  return (
    <DashboardLayout>
      <div className="max-w-6xl mx-auto px-4 py-8">
        {/* Header */}
        <div className="flex items-center justify-between mb-8">
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center">
                <Brain className="w-5 h-5 text-white" />
              </div>
              {t('examClone.title')}
            </h1>
            <p className="text-muted-foreground mt-1">
              {t('examClone.description')}
            </p>
          </div>
          <Button onClick={() => setShowUploadModal(true)} className="bg-purple-500 hover:bg-purple-600">
            <Plus className="w-4 h-4 mr-2" />
            {t('examClone.generate')}
          </Button>
        </div>

        {/* Quick Access Buttons */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
          <button
            onClick={() => navigate('/dashboard/exam-clone/review-queue')}
            className="flex items-center gap-3 p-4 bg-card border border-border rounded-xl hover:border-amber-500/50 transition-all group"
          >
            <div className="w-10 h-10 rounded-lg bg-amber-500/10 flex items-center justify-center group-hover:bg-amber-500/20 transition-colors">
              <Brain className="w-5 h-5 text-amber-500" />
            </div>
            <div className="text-left">
              <p className="font-medium text-sm">{t('studySets.reviewQueue')}</p>
              <p className="text-xs text-muted-foreground">
                {reviewQueueCount > 0 ? `${reviewQueueCount} due` : t('flashcards.allCaughtUp')}
              </p>
            </div>
          </button>

          <button
            onClick={() => navigate('/dashboard/exam-clone/bookmarks')}
            className="flex items-center gap-3 p-4 bg-card border border-border rounded-xl hover:border-blue-500/50 transition-all group"
          >
            <div className="w-10 h-10 rounded-lg bg-blue-500/10 flex items-center justify-center group-hover:bg-blue-500/20 transition-colors">
              <BookOpen className="w-5 h-5 text-blue-500" />
            </div>
            <div className="text-left">
              <p className="font-medium text-sm">{t('problemSolver.bookmarks')}</p>
              <p className="text-xs text-muted-foreground">{t('examClone.savedQuestions')}</p>
            </div>
          </button>

          <button
            onClick={() => navigate('/dashboard/exam-clone/badges')}
            className="flex items-center gap-3 p-4 bg-card border border-border rounded-xl hover:border-yellow-500/50 transition-all group"
          >
            <div className="w-10 h-10 rounded-lg bg-yellow-500/10 flex items-center justify-center group-hover:bg-yellow-500/20 transition-colors">
              <Target className="w-5 h-5 text-yellow-500" />
            </div>
            <div className="text-left">
              <p className="font-medium text-sm">{t('badges.title')}</p>
              <p className="text-xs text-muted-foreground">{t('examClone.achievements')}</p>
            </div>
          </button>

          <button
            onClick={() => navigate('/dashboard/exam-clone/leaderboard')}
            className="flex items-center gap-3 p-4 bg-card border border-border rounded-xl hover:border-purple-500/50 transition-all group"
          >
            <div className="w-10 h-10 rounded-lg bg-purple-500/10 flex items-center justify-center group-hover:bg-purple-500/20 transition-colors">
              <BarChart3 className="w-5 h-5 text-purple-500" />
            </div>
            <div className="text-left">
              <p className="font-medium text-sm">{t('leaderboard.title')}</p>
              <p className="text-xs text-muted-foreground">{t('examClone.rankings')}</p>
            </div>
          </button>
        </div>

        {/* Review Queue Notification */}
        <AnimatePresence>
          {reviewQueueCount > 0 && (
            <motion.div
              initial={{ opacity: 0, y: -20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              className={cn(
                "mb-6 p-4 rounded-xl border-2 cursor-pointer transition-all",
                showReviewNotification
                  ? "bg-gradient-to-r from-amber-500/20 to-orange-500/20 border-amber-500 animate-pulse"
                  : "bg-gradient-to-r from-amber-500/10 to-orange-500/10 border-amber-500/30 hover:border-amber-500/60"
              )}
              onClick={() => {
                setShowReviewNotification(false);
                navigate('/dashboard/exam-clone/review-queue');
              }}
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <div className="relative">
                    <div className="w-12 h-12 rounded-xl bg-amber-500/20 flex items-center justify-center">
                      <Bell className="w-6 h-6 text-amber-500" />
                    </div>
                    {showReviewNotification && (
                      <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 rounded-full animate-ping" />
                    )}
                    <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 rounded-full flex items-center justify-center text-[10px] text-white font-bold">
                      {reviewQueueCount > 9 ? '9+' : reviewQueueCount}
                    </span>
                  </div>
                  <div>
                    <h3 className="font-semibold text-lg flex items-center gap-2">
                      {t('examClone.reviewTime')}
                      <span className="text-sm font-normal text-muted-foreground">
                        ({t('examClone.questionsDue', { count: reviewQueueCount })})
                      </span>
                    </h3>
                    <p className="text-sm text-muted-foreground">
                      {t('examClone.reinforceLearning')}
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      fetchReviewQueueCount();
                    }}
                  >
                    <RotateCcw className="w-4 h-4" />
                  </Button>
                  <Button
                    className="bg-amber-500 hover:bg-amber-600 text-white"
                    onClick={(e) => {
                      e.stopPropagation();
                      setShowReviewNotification(false);
                      navigate('/dashboard/exam-clone/review-queue');
                    }}
                  >
                    {t('dashboard.studyNow')}
                    <ChevronRight className="w-4 h-4 ml-1" />
                  </Button>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Stats Overview */}
        {exams.length > 0 && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
            <div className="bg-card border border-border rounded-xl p-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-lg bg-purple-500/10 flex items-center justify-center">
                  <FileText className="w-5 h-5 text-purple-500" />
                </div>
                <div>
                  <p className="text-2xl font-bold">{exams.length}</p>
                  <p className="text-xs text-muted-foreground">{t('examClone.examsUploaded')}</p>
                </div>
              </div>
            </div>
            <div className="bg-card border border-border rounded-xl p-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-lg bg-blue-500/10 flex items-center justify-center">
                  <BookOpen className="w-5 h-5 text-blue-500" />
                </div>
                <div>
                  <p className="text-2xl font-bold">
                    {exams.reduce((acc, e) => acc + e.originalQuestionCount, 0)}
                  </p>
                  <p className="text-xs text-muted-foreground">{t('examClone.originalQuestions')}</p>
                </div>
              </div>
            </div>
            <div className="bg-card border border-border rounded-xl p-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-lg bg-green-500/10 flex items-center justify-center">
                  <Sparkles className="w-5 h-5 text-green-500" />
                </div>
                <div>
                  <p className="text-2xl font-bold">
                    {exams.reduce((acc, e) => acc + e.generatedQuestionCount, 0)}
                  </p>
                  <p className="text-xs text-muted-foreground">{t('examClone.generatedQuestions')}</p>
                </div>
              </div>
            </div>
            <div className="bg-card border border-border rounded-xl p-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-lg bg-amber-500/10 flex items-center justify-center">
                  <Target className="w-5 h-5 text-amber-500" />
                </div>
                <div>
                  <p className="text-2xl font-bold">
                    {exams.filter((e) => e.status === 'completed').length}
                  </p>
                  <p className="text-xs text-muted-foreground">{t('examClone.readyToPractice')}</p>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Exams List */}
        {isLoading ? (
          <div className="flex items-center justify-center py-20">
            <Loader2 className="w-8 h-8 animate-spin text-muted-foreground" />
          </div>
        ) : exams.length === 0 ? (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-center py-20 bg-card border border-border rounded-2xl"
          >
            <div className="w-20 h-20 rounded-full bg-purple-500/10 flex items-center justify-center mx-auto mb-6">
              <Brain className="w-10 h-10 text-purple-500" />
            </div>
            <h2 className="text-xl font-semibold mb-2">{t('common.noResults')}</h2>
            <p className="text-muted-foreground max-w-md mx-auto mb-6">
              {t('examClone.emptyDesc')}
            </p>
            <Button onClick={() => setShowUploadModal(true)} className="bg-purple-500 hover:bg-purple-600">
              <Upload className="w-4 h-4 mr-2" />
              {t('examClone.uploadFirst')}
            </Button>
          </motion.div>
        ) : (
          <div className="space-y-4">
            <AnimatePresence>
              {exams.map((exam, index) => {
                const statusConfig = STATUS_CONFIG[exam.status];
                const StatusIcon = statusConfig.icon;

                return (
                  <motion.div
                    key={exam.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, x: -20 }}
                    transition={{ delay: index * 0.05 }}
                    className="bg-card border border-border rounded-xl overflow-hidden hover:border-purple-500/30 transition-colors"
                  >
                    <div className="p-5">
                      <div className="flex items-start gap-4">
                        {/* Icon */}
                        <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-purple-500/20 to-pink-500/20 flex items-center justify-center flex-shrink-0">
                          <FileText className="w-6 h-6 text-purple-500" />
                        </div>

                        {/* Content */}
                        <div className="flex-1 min-w-0">
                          <div className="flex items-start justify-between gap-4">
                            <div>
                              <h3 className="font-semibold text-lg">{exam.title}</h3>
                              {exam.subject && (
                                <p className="text-sm text-muted-foreground">{exam.subject}</p>
                              )}
                            </div>
                            <div className={cn('flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium', statusConfig.bg, statusConfig.color)}>
                              <StatusIcon className={cn('w-3.5 h-3.5', exam.status === 'processing' && 'animate-spin')} />
                              {t(statusConfig.labelKey)}
                            </div>
                          </div>

                          {/* Stats */}
                          {exam.status === 'completed' && exam.extractedStyle && (
                            <div className="flex flex-wrap items-center gap-4 mt-3 text-sm">
                              <div className="flex items-center gap-1.5 text-muted-foreground">
                                <BookOpen className="w-4 h-4" />
                                <span>{t('examClone.nOriginal', { count: exam.originalQuestionCount })}</span>
                              </div>
                              <div className="flex items-center gap-1.5 text-muted-foreground">
                                <Sparkles className="w-4 h-4" />
                                <span>{t('examClone.nGenerated', { count: exam.generatedQuestionCount })}</span>
                              </div>
                              <div className="flex items-center gap-1.5 text-muted-foreground">
                                <BarChart3 className="w-4 h-4" />
                                <span>{t('examClone.nTypes', { count: exam.extractedStyle.questionTypes.length })}</span>
                              </div>
                            </div>
                          )}

                          {/* Topics */}
                          {exam.extractedStyle?.topicsCovered && exam.extractedStyle.topicsCovered.length > 0 && (
                            <div className="flex flex-wrap gap-1.5 mt-3">
                              {exam.extractedStyle.topicsCovered.slice(0, 5).map((topic, i) => (
                                <span key={i} className="px-2 py-0.5 bg-muted rounded text-xs">
                                  {topic}
                                </span>
                              ))}
                              {exam.extractedStyle.topicsCovered.length > 5 && (
                                <span className="px-2 py-0.5 text-muted-foreground text-xs">
                                  {t('examClone.moreTopics', { count: exam.extractedStyle.topicsCovered.length - 5 })}
                                </span>
                              )}
                            </div>
                          )}
                        </div>
                      </div>

                      {/* Actions */}
                      <div className="flex items-center justify-between mt-4 pt-4 border-t border-border">
                        <span className="text-xs text-muted-foreground">
                          {t('examClone.uploadedOn', { date: new Date(exam.createdAt).toLocaleDateString() })}
                        </span>
                        <div className="flex items-center gap-2">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => setDeleteId(exam.id)}
                            className="text-destructive hover:text-destructive"
                          >
                            <Trash2 className="w-4 h-4" />
                          </Button>
                          {exam.status === 'completed' && (
                            <>
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={() => navigate(`/dashboard/exam-clone/${exam.id}`)}
                              >
                                {t('examClone.viewAnalysis')}
                                <ChevronRight className="w-4 h-4 ml-1" />
                              </Button>
                              <Button
                                size="sm"
                                onClick={() => navigate(`/dashboard/exam-clone/${exam.id}/practice`)}
                                className="bg-purple-500 hover:bg-purple-600"
                              >
                                <Play className="w-4 h-4 mr-1" />
                                {t('examClone.practiceExam')}
                              </Button>
                            </>
                          )}
                          {exam.status === 'failed' && (
                            <Button variant="outline" size="sm" disabled>
                              <AlertCircle className="w-4 h-4 mr-1" />
                              {t('examClone.analysisFailed')}
                            </Button>
                          )}
                        </div>
                      </div>
                    </div>
                  </motion.div>
                );
              })}
            </AnimatePresence>
          </div>
        )}

        {/* Upload Modal */}
        <AnimatePresence>
          {showUploadModal && (
            <UploadExamModal
              onClose={() => setShowUploadModal(false)}
              onSuccess={handleUploadSuccess}
            />
          )}
        </AnimatePresence>

        {/* Delete Confirmation */}
        <AnimatePresence>
          {deleteId && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
              onClick={() => setDeleteId(null)}
            >
              <motion.div
                initial={{ scale: 0.95, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.95, opacity: 0 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-card border border-border rounded-xl p-6 max-w-sm w-full"
              >
