          <RotateCcw className="w-4 h-4 mr-2" />
          {t('matchGame.playAgain')}
        </Button>
      </div>
    </motion.div>
  );
}

export function MatchGamePage() {
  const { t } = useTranslation();
  const { id: studySetId } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { flashcards, isLoading, fetchFlashcards } = useFlashcardsStore();
  const { addXP } = useGamificationStore();

  const [terms, setTerms] = useState<MatchCard[]>([]);
  const [definitions, setDefinitions] = useState<MatchCard[]>([]);
  const [selectedTerm, setSelectedTerm] = useState<string | null>(null);
  const [selectedDef, setSelectedDef] = useState<string | null>(null);
  const [matchedIds, setMatchedIds] = useState<Set<string>>(new Set());
  const [wrongPair, setWrongPair] = useState<{
    term: string;
    def: string;
  } | null>(null);
  const [moves, setMoves] = useState(0);
  const [timer, setTimer] = useState(0);
  const [isComplete, setIsComplete] = useState(false);
  const [gameStarted, setGameStarted] = useState(false);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (studySetId) {
      fetchFlashcards(studySetId);
    }
  }, [studySetId, fetchFlashcards]);

  const initGame = useCallback(() => {
    if (flashcards.length < 2) return;

    const picked = shuffle(flashcards).slice(0, Math.min(6, flashcards.length));

    const termCards: MatchCard[] = picked.map((fc) => ({
      id: `term-${fc.id}`,
      flashcardId: fc.id,
      text: fc.front,
      type: 'term' as const,
    }));

    const defCards: MatchCard[] = picked.map((fc) => ({
      id: `def-${fc.id}`,
      flashcardId: fc.id,
      text: fc.back,
      type: 'definition' as const,
    }));

    setTerms(shuffle(termCards));
    setDefinitions(shuffle(defCards));
    setSelectedTerm(null);
    setSelectedDef(null);
    setMatchedIds(new Set());
    setWrongPair(null);
    setMoves(0);
    setTimer(0);
    setIsComplete(false);
    setGameStarted(true);

    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = setInterval(() => setTimer((t) => t + 1), 1000);
  }, [flashcards]);

  useEffect(() => {
    if (flashcards.length >= 2 && !gameStarted) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      initGame();
    }
  }, [flashcards, gameStarted, initGame]);

  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, []);

  // Check match function
  const checkMatch = useCallback((termId: string, defId: string) => {
    const termCard = terms.find((t) => t.id === termId);
    const defCard = definitions.find((d) => d.id === defId);

    if (!termCard || !defCard) return;

    setMoves((m) => m + 1);

    if (termCard.flashcardId === defCard.flashcardId) {
      // Match!
      const newMatched = new Set(matchedIds);
      newMatched.add(termCard.flashcardId);
      setMatchedIds(newMatched);
      setSelectedTerm(null);
      setSelectedDef(null);

      if (newMatched.size === terms.length) {
        setIsComplete(true);
        if (timerRef.current) clearInterval(timerRef.current);
        addXP('quiz_complete');
      }
    } else {
      // Wrong
      setWrongPair({ term: termId, def: defId });
      setTimeout(() => {
        setWrongPair(null);
        setSelectedTerm(null);
        setSelectedDef(null);
      }, 600);
    }
  }, [terms, definitions, matchedIds, addXP]);

  const handleTermClick = (id: string) => {
    if (wrongPair) return;
    const card = terms.find((t) => t.id === id);
    if (!card || matchedIds.has(card.flashcardId)) return;

    const newSelectedTerm = id === selectedTerm ? null : id;
    setSelectedTerm(newSelectedTerm);

    // Check for match if both term and def are selected
    if (newSelectedTerm && selectedDef) {
      checkMatch(newSelectedTerm, selectedDef);
    }
  };

  const handleDefClick = (id: string) => {
    if (wrongPair) return;
    const card = definitions.find((d) => d.id === id);
    if (!card || matchedIds.has(card.flashcardId)) return;

    const newSelectedDef = id === selectedDef ? null : id;
    setSelectedDef(newSelectedDef);

    // Check for match if both term and def are selected
    if (selectedTerm && newSelectedDef) {
      checkMatch(selectedTerm, newSelectedDef);
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  if (isLoading && flashcards.length === 0) {
    return (
      <DashboardLayout>
        <div className="flex items-center justify-center py-12">
          <Spinner className="w-8 h-8" />
        </div>
      </DashboardLayout>
    );
  }

  if (flashcards.length < 2) {
    return (
      <DashboardLayout>
        <div className="text-center py-12">
          <div className="w-16 h-16 rounded-full bg-green-500/10 flex items-center justify-center mx-auto mb-4">
            <Gamepad2 className="w-8 h-8 text-green-500" />
          </div>
          <h2 className="text-xl font-bold mb-2">{t('matchGame.notEnoughFlashcards')}</h2>
          <p className="text-muted-foreground mb-4">
            {t('matchGame.needAtLeast2')}
          </p>
          <Button
            variant="outline"
            onClick={() => navigate(`/dashboard/study-sets/${studySetId}`)}
          >
            {t('matchGame.backToStudySet')}
          </Button>
        </div>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout>
      <div className="max-w-4xl mx-auto min-h-[calc(100vh-120px)] flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <button
            onClick={() => navigate(`/dashboard/study-sets/${studySetId}`)}
            className="flex items-center gap-2 text-muted-foreground hover:text-foreground transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
            <span>{t('matchGame.exit')}</span>
          </button>
          {!isComplete && (
            <div className="flex items-center gap-4">
              <span className="flex items-center gap-1.5 text-sm font-medium text-muted-foreground">
                <MousePointerClick className="w-4 h-4" />
                {t('matchGame.movesCount', { count: moves })}
              </span>
              <span className="flex items-center gap-1.5 text-sm font-medium text-muted-foreground">
                <Clock className="w-4 h-4" />
                {formatTime(timer)}
              </span>
            </div>
          )}
        </div>

        {/* Content */}
        <div className="flex-1 flex flex-col justify-center">
          <AnimatePresence mode="wait">
            {isComplete ? (
              <MatchGameComplete
                key="complete"
                time={timer}
                moves={moves}
                pairs={terms.length}
                studySetId={studySetId!}
                onRetry={initGame}
              />
            ) : (
              <motion.div
                key="game"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="grid grid-cols-2 gap-4 md:gap-6"
              >
                {/* Terms Column */}
                <div className="space-y-3">
                  <h3 className="text-xs uppercase tracking-wider text-muted-foreground font-medium mb-2">
                    {t('matchGame.terms')}
                  </h3>
                  {terms.map((card) => {
                    const isMatched = matchedIds.has(card.flashcardId);
                    const isSelected = selectedTerm === card.id;
                    const isWrong = wrongPair?.term === card.id;

                    return (
                      <motion.button
                        key={card.id}
                        onClick={() => handleTermClick(card.id)}
                        disabled={isMatched}
                        animate={
                          isWrong
                            ? {
                                x: [0, -4, 4, -4, 4, 0],
                                transition: { duration: 0.4 },
                              }
                            : isMatched
                            ? { opacity: 0.4, scale: 0.95 }
                            : {}
                        }
                        className={cn(
                          'w-full text-left px-4 py-3.5 rounded-xl border-2 transition-all text-sm font-medium',
                          isMatched
                            ? 'border-green-500/50 bg-green-500/10 text-green-600 dark:text-green-400 line-through cursor-default'
                            : isWrong
                            ? 'border-red-500 bg-red-500/10 text-red-600'
                            : isSelected
                            ? 'border-green-500 bg-green-500/5 shadow-md'
                            : 'border-border bg-card hover:border-green-500/50'
                        )}
                      >
                        {card.text}
                      </motion.button>
                    );
                  })}
                </div>

                {/* Definitions Column */}
                <div className="space-y-3">
                  <h3 className="text-xs uppercase tracking-wider text-muted-foreground font-medium mb-2">
                    {t('matchGame.definitions')}
                  </h3>
                  {definitions.map((card) => {
                    const isMatched = matchedIds.has(card.flashcardId);
                    const isSelected = selectedDef === card.id;
                    const isWrong = wrongPair?.def === card.id;

                    return (
                      <motion.button
                        key={card.id}
                        onClick={() => handleDefClick(card.id)}
                        disabled={isMatched}
                        animate={
                          isWrong
                            ? {
                                x: [0, -4, 4, -4, 4, 0],
                                transition: { duration: 0.4 },
                              }
                            : isMatched
                            ? { opacity: 0.4, scale: 0.95 }
                            : {}
                        }
                        className={cn(
                          'w-full text-left px-4 py-3.5 rounded-xl border-2 transition-all text-sm font-medium',
                          isMatched
                            ? 'border-green-500/50 bg-green-500/10 text-green-600 dark:text-green-400 line-through cursor-default'
                            : isWrong
                            ? 'border-red-500 bg-red-500/10 text-red-600'
                            : isSelected
                            ? 'border-green-500 bg-green-500/5 shadow-md'
                            : 'border-border bg-card hover:border-green-500/50'
                        )}
                      >
                        {card.text}
                      </motion.button>
                    );
                  })}
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </DashboardLayout>
  );
}

