  {
    key: 'studyReminders' as const,
    labelKey: 'notificationSettingsPage.studyReminders',
    descKey: 'notificationSettingsPage.studyRemindersDesc',
  },
  {
    key: 'streakAlerts' as const,
    labelKey: 'notificationSettingsPage.streakAlerts',
