              'flex-1 flex items-center justify-center gap-2 py-2 px-4 text-sm font-medium rounded-md transition-colors',
              tab === 'settings' ? 'bg-card shadow-sm' : 'hover:bg-card/50'
            )}
          >
            <Settings className="w-4 h-4" />
            {t('notifications.tabs.settings')}
          </button>
        </div>

        {/* Content */}
        <AnimatePresence mode="wait">
          {tab === 'settings' ? (
            <motion.div
              key="settings"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="space-y-6"
            >
              {/* Notification Channels */}
              <div className="bg-card border border-border rounded-xl p-5">
                <h3 className="font-semibold mb-4">{t('notifications.channels.title')}</h3>
                <div className="space-y-3">
                  <PreferenceToggle
                    icon={Monitor}
                    label={t('notifications.channels.inApp')}
                    description={t('notifications.channels.inAppDesc')}
                    checked={preferences?.inApp ?? true}
                    onChange={(v) => handlePreferenceChange('inApp', v)}
                  />
                  <PreferenceToggle
                    icon={Mail}
                    label={t('notifications.channels.email')}
                    description={t('notifications.channels.emailDesc')}
                    checked={preferences?.email ?? true}
                    onChange={(v) => handlePreferenceChange('email', v)}
                  />
                  <PreferenceToggle
                    icon={Smartphone}
                    label={t('notifications.channels.push')}
                    description={t('notifications.channels.pushDesc')}
                    checked={preferences?.push ?? true}
                    onChange={(v) => handlePreferenceChange('push', v)}
                  />
                </div>
              </div>

              {/* Notification Types */}
              <div className="bg-card border border-border rounded-xl p-5">
                <h3 className="font-semibold mb-4">{t('notifications.notificationTypes.title')}</h3>
                <div className="space-y-3">
                  <PreferenceToggle
                    icon={CalendarClock}
                    label={t('notifications.notificationTypes.studyReminders')}
                    description={t('notifications.notificationTypes.studyRemindersDesc')}
                    checked={preferences?.studyReminders ?? true}
                    onChange={(v) => handlePreferenceChange('studyReminders', v)}
                  />
                  <PreferenceToggle
                    icon={Award}
                    label={t('notifications.notificationTypes.achievements')}
                    description={t('notifications.notificationTypes.achievementsDesc')}
                    checked={preferences?.achievementAlerts ?? true}
                    onChange={(v) => handlePreferenceChange('achievementAlerts', v)}
                  />
                  <PreferenceToggle
                    icon={Newspaper}
                    label={t('notifications.notificationTypes.weeklyDigest')}
                    description={t('notifications.notificationTypes.weeklyDigestDesc')}
                    checked={preferences?.weeklyDigest ?? true}
                    onChange={(v) => handlePreferenceChange('weeklyDigest', v)}
                  />
                </div>
              </div>
            </motion.div>
          ) : (
            <motion.div
              key="notifications"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
            >
              {isLoading && notifications.length === 0 ? (
                <div className="flex items-center justify-center py-20">
                  <div className="w-8 h-8 border-2 border-green-500 border-t-transparent rounded-full animate-spin" />
                </div>
              ) : filteredNotifications.length === 0 ? (
                <div className="text-center py-20 bg-card border border-border rounded-xl">
                  <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center mx-auto mb-4">
                    <Bell className="w-8 h-8 text-muted-foreground" />
                  </div>
                  <h3 className="text-lg font-semibold mb-2">
                    {tab === 'unread' ? t('notifications.noUnread') : t('notifications.noNotifications')}
                  </h3>
                  <p className="text-sm text-muted-foreground max-w-sm mx-auto">
                    {t('notifications.wellNotify')}
                  </p>
                </div>
              ) : (
                <div className="bg-card border border-border rounded-xl overflow-hidden divide-y divide-border">
                  {filteredNotifications.map((notification, index) => {
                    const config = typeConfig[notification.type] || typeConfig.info;
                    const Icon = config.icon;

                    return (
                      <motion.div
                        key={notification.id}
                        initial={{ opacity: 0, x: -20 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: index * 0.03 }}
                        className={cn(
                          'relative group',
                          !notification.isRead && 'bg-green-500/5'
                        )}
                      >
                        <button
                          onClick={() => handleNotificationClick(notification)}
                          className="w-full text-left p-4 hover:bg-muted/30 transition-colors"
                        >
                          <div className="flex gap-4">
                            {/* Icon */}
                            <div className={cn('w-11 h-11 rounded-xl flex items-center justify-center shrink-0', config.bg)}>
                              <Icon className={cn('w-5 h-5', config.color)} />
                            </div>

                            {/* Content */}
                            <div className="flex-1 min-w-0">
                              <div className="flex items-start justify-between gap-3">
                                <div className="flex-1">
                                  <div className="flex items-center gap-2">
                                    <p className={cn(
                                      'text-sm',
                                      !notification.isRead ? 'font-semibold' : 'font-medium'
                                    )}>
                                      {notification.title}
                                    </p>
                                    {!notification.isRead && (
                                      <span className="w-2 h-2 rounded-full bg-green-500" />
                                    )}
                                  </div>
                                  <p className="text-sm text-muted-foreground mt-0.5">
                                    {notification.message}
                                  </p>
                                </div>
                                <span className="text-xs text-muted-foreground/70 whitespace-nowrap">
                                  {formatTimeAgo(notification.createdAt)}
                                </span>
                              </div>
                              <div className="flex items-center gap-2 mt-2">
                                <span className={cn('text-[10px] px-2 py-0.5 rounded-full', config.bg, config.color)}>
                                  {t(config.labelKey)}
                                </span>
                                {notification.link && (
                                  <span className="text-[10px] text-muted-foreground">
                                    {t('notifications.clickToView')}
                                  </span>
                                )}
                              </div>
                            </div>
                          </div>
                        </button>

                        {/* Action buttons */}
                        <div className="absolute right-4 top-1/2 -translate-y-1/2 hidden group-hover:flex items-center gap-1 bg-card px-2 py-1 rounded-lg border border-border shadow-sm">
                          {!notification.isRead && (
                            <button
                              onClick={(e) => {
                                e.stopPropagation();
                                markAsRead(notification.id);
                              }}
                              className="p-1.5 rounded-lg hover:bg-muted transition-colors"
                              title={t('notifications.markAllAsRead')}
                            >
                              <Check className="w-4 h-4 text-green-500" />
                            </button>
                          )}
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              deleteNotification(notification.id);
                            }}
                            className="p-1.5 rounded-lg hover:bg-muted transition-colors"
                            title={t('common.delete')}
                          >
                            <Trash2 className="w-4 h-4 text-red-500" />
                          </button>
                        </div>
                      </motion.div>
                    );
                  })}
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '@/components/ui/button';
import api from '@/services/api';
import { ENDPOINTS } from '@/config/api';
import {
  ArrowLeft,
  Clock,
  Flag,
  ChevronLeft,
  ChevronRight,
  CheckCircle,
  AlertCircle,
  Loader2,
  Play,
  X,
  RotateCcw,
  Brain,
  BookOpen,
  Bookmark,
  Timer,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { PomodoroTimer } from '@/components/exam/PomodoroTimer';

interface ExamQuestion {
  id: string;
  type: string;
  question: string;
  options: string[] | null;
  correctAnswer: string;
  explanation: string | null;
  difficulty: string;
  topic: string | null;
  isOriginal?: boolean;
}

interface UserAnswer {
  questionId: string;
  answer: string;
  flagged: boolean;
  timeSpent: number;
}

type ExamState = 'setup' | 'in-progress' | 'review' | 'results';

export default function PracticeExamPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { t } = useTranslation();

  const [examState, setExamState] = useState<ExamState>('setup');
  const [questions, setQuestions] = useState<ExamQuestion[]>([]);
  const [selectedQuestions, setSelectedQuestions] = useState<ExamQuestion[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Map<string, UserAnswer>>(new Map());
  const [timeRemaining, setTimeRemaining] = useState(0);
  const [totalTime, setTotalTime] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [showConfirmSubmit, setShowConfirmSubmit] = useState(false);
  const [showConfirmExit, setShowConfirmExit] = useState(false);
  const [bookmarkedIds, setBookmarkedIds] = useState<Set<string>>(new Set());
  const [showPomodoro, setShowPomodoro] = useState(false);

  // Setup options
  const [questionCount, setQuestionCount] = useState(10);
  const [timeLimit, setTimeLimit] = useState(30); // minutes
  const [includeOriginal, setIncludeOriginal] = useState(true);
  const [includeGenerated, setIncludeGenerated] = useState(true);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const questionStartTime = useRef<number>(Date.now());

  // Fetch questions
  useEffect(() => {
    const fetchQuestions = async () => {
      if (!id) return;
      try {
        setIsLoading(true);
        const response = await api.get<ExamQuestion[]>(`/exam-clones/${id}/questions`);
        setQuestions(response.data);
      } catch (err) {
        console.error('Failed to fetch questions:', err);
      } finally {
        setIsLoading(false);
      }
    };
    fetchQuestions();
  }, [id]);

  // Timer effect
  useEffect(() => {
    if (examState === 'in-progress' && timeRemaining > 0) {
      timerRef.current = setInterval(() => {
        setTimeRemaining((prev) => {
          if (prev <= 1) {
            handleSubmit();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [examState, timeRemaining]);

  const startExam = () => {
    // Select questions
    let available = [...questions];
    if (!includeOriginal) {
      available = available.filter((q) => !q.isOriginal);
    }
    if (!includeGenerated) {
      available = available.filter((q) => q.isOriginal);
    }

    // Shuffle and pick
    const shuffled = available.sort(() => Math.random() - 0.5);
    const selected = shuffled.slice(0, Math.min(questionCount, shuffled.length));

    // Prevent starting with no questions
    if (selected.length === 0) {
      alert(t('practiceExam.noQuestionsAvailable'));
      return;
    }

    setSelectedQuestions(selected);
    setTimeRemaining(timeLimit * 60);
    setTotalTime(timeLimit * 60);
    setCurrentIndex(0);
    setAnswers(new Map());
    questionStartTime.current = Date.now();
    setExamState('in-progress');
  };

  const handleAnswer = (answer: string) => {
    const question = selectedQuestions[currentIndex];
    const timeSpent = Math.floor((Date.now() - questionStartTime.current) / 1000);

    setAnswers((prev) => {
      const newAnswers = new Map(prev);
      newAnswers.set(question.id, {
        questionId: question.id,
        answer,
        flagged: prev.get(question.id)?.flagged || false,
        timeSpent: (prev.get(question.id)?.timeSpent || 0) + timeSpent,
      });
      return newAnswers;
    });

    questionStartTime.current = Date.now();
  };

  const toggleFlag = () => {
    const question = selectedQuestions[currentIndex];
    setAnswers((prev) => {
      const newAnswers = new Map(prev);
      const existing = prev.get(question.id);
      newAnswers.set(question.id, {
        questionId: question.id,
        answer: existing?.answer || '',
        flagged: !existing?.flagged,
        timeSpent: existing?.timeSpent || 0,
      });
      return newAnswers;
    });
  };

  const toggleBookmark = async (questionId: string) => {
    const isBookmarked = bookmarkedIds.has(questionId);
    try {
      if (isBookmarked) {
        await api.delete(ENDPOINTS.examClone.bookmark(questionId));
        setBookmarkedIds((prev) => {
          const newSet = new Set(prev);
          newSet.delete(questionId);
          return newSet;
        });
      } else {
        await api.post(ENDPOINTS.examClone.bookmark(questionId), {});
        setBookmarkedIds((prev) => new Set(prev).add(questionId));
      }
    } catch (err) {
      console.error('Failed to toggle bookmark:', err);
    }
  };

  const goToQuestion = (index: number) => {
    const timeSpent = Math.floor((Date.now() - questionStartTime.current) / 1000);
    const currentQuestion = selectedQuestions[currentIndex];

    // Save time for current question
    setAnswers((prev) => {
      const newAnswers = new Map(prev);
      const existing = prev.get(currentQuestion.id);
      if (existing) {
        newAnswers.set(currentQuestion.id, {
          ...existing,
          timeSpent: existing.timeSpent + timeSpent,
        });
      }
      return newAnswers;
    });

    questionStartTime.current = Date.now();
    setCurrentIndex(index);
  };

  const handleSubmit = useCallback(async () => {
    if (timerRef.current) clearInterval(timerRef.current);

    // Submit attempt to backend for analytics and review queue
    try {
      const answersArray = selectedQuestions.map((q) => {
        const userAnswer = answers.get(q.id);
        return {
          questionId: q.id,
          answer: userAnswer?.answer || '',
          timeSpent: userAnswer?.timeSpent || 0,
        };
      });

      const timeTaken = totalTime - timeRemaining;

      await api.post(ENDPOINTS.examClone.submitAttempt(id!), {
        answers: answersArray,
        totalTime: timeTaken,
      });

      console.log('Attempt submitted to backend');
    } catch (err) {
      console.error('Failed to submit attempt:', err);
      // Continue to results even if API fails
    }

    setExamState('results');
  }, [selectedQuestions, answers, totalTime, timeRemaining, id]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // Calculate results
  const calculateResults = () => {
    let correct = 0;
    let incorrect = 0;
    let unanswered = 0;

    selectedQuestions.forEach((q) => {
      const userAnswer = answers.get(q.id);
      if (!userAnswer?.answer) {
        unanswered++;
      } else if (userAnswer.answer === q.correctAnswer) {
        correct++;
      } else {
        incorrect++;
      }
    });

    const score = Math.round((correct / selectedQuestions.length) * 100);
    const timeTaken = totalTime - timeRemaining;

    return { correct, incorrect, unanswered, score, timeTaken };
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  // Setup Screen
  if (examState === 'setup') {
    return (
      <div className="min-h-screen bg-background">
        <div className="max-w-2xl mx-auto px-4 py-12">
          <Button
            variant="ghost"
            onClick={() => navigate(`/dashboard/exam-clone/${id}`)}
            className="mb-6"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            {t('practiceExam.backToExam')}
          </Button>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-card border border-border rounded-2xl p-8"
          >
            <div className="text-center mb-8">
              <div className="w-16 h-16 rounded-full bg-purple-500/10 flex items-center justify-center mx-auto mb-4">
                <Brain className="w-8 h-8 text-purple-500" />
              </div>
              <h1 className="text-2xl font-bold mb-2">{t('practiceExam.title')}</h1>
              <p className="text-muted-foreground">
                {t('practiceExam.questionsAvailable', { count: questions.length })}
              </p>
            </div>

            <div className="space-y-6">
              {/* Question Count */}
              <div>
                <label className="block text-sm font-medium mb-2">{t('practiceExam.numberOfQuestions')}</label>
                <div className="flex gap-2">
                  {[5, 10, 15, 20, 'All'].map((n) => (
                    <button
                      key={n}
                      onClick={() => setQuestionCount(n === 'All' ? questions.length : (n as number))}
                      className={cn(
                        'flex-1 py-2.5 rounded-lg border text-sm font-medium transition-colors',
                        questionCount === (n === 'All' ? questions.length : n)
                          ? 'border-purple-500 bg-purple-500/10 text-purple-500'
                          : 'border-border hover:border-purple-500/50'
                      )}
                    >
                      {n}
                    </button>
                  ))}
                </div>
              </div>

              {/* Time Limit */}
              <div>
                <label className="block text-sm font-medium mb-2">{t('practiceExam.timeLimit')}</label>
                <div className="flex gap-2">
                  {[15, 30, 45, 60, 90].map((t) => (
                    <button
                      key={t}
                      onClick={() => setTimeLimit(t)}
                      className={cn(
                        'flex-1 py-2.5 rounded-lg border text-sm font-medium transition-colors',
                        timeLimit === t
                          ? 'border-purple-500 bg-purple-500/10 text-purple-500'
                          : 'border-border hover:border-purple-500/50'
                      )}
                    >
                      {t}
                    </button>
                  ))}
                </div>
              </div>

              {/* Question Sources */}
              <div>
                <label className="block text-sm font-medium mb-2">{t('practiceExam.includeQuestionsFrom')}</label>
                <div className="flex gap-3">
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={includeOriginal}
                      onChange={(e) => setIncludeOriginal(e.target.checked)}
                      className="w-4 h-4 rounded border-border"
                    />
                    <span className="text-sm">{t('practiceExam.originalExam')}</span>
                  </label>
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={includeGenerated}
                      onChange={(e) => setIncludeGenerated(e.target.checked)}
                      className="w-4 h-4 rounded border-border"
                    />
                    <span className="text-sm">{t('practiceExam.aiGenerated')}</span>
                  </label>
                </div>
              </div>

              <Button
                onClick={startExam}
                disabled={!includeOriginal && !includeGenerated}
                className="w-full bg-purple-500 hover:bg-purple-600 h-12 text-base"
              >
                <Play className="w-5 h-5 mr-2" />
                {t('practiceExam.startExam')}
              </Button>
            </div>
          </motion.div>
        </div>
      </div>
    );
  }

  // In Progress Screen
  if (examState === 'in-progress') {
    const currentQuestion = selectedQuestions[currentIndex];

    // Safety guard - if no questions, go back to setup
    if (!currentQuestion) {
      setExamState('setup');
      return null;
    }

    const currentAnswer = answers.get(currentQuestion.id);
    const answeredCount = Array.from(answers.values()).filter((a) => a.answer).length;
    const flaggedCount = Array.from(answers.values()).filter((a) => a.flagged).length;

    return (
      <div className="min-h-screen bg-background flex flex-col">
        {/* Header */}
        <div className="sticky top-0 bg-background/95 backdrop-blur border-b border-border z-10">
          <div className="max-w-4xl mx-auto px-4 py-3 flex items-center justify-between">
            <div className="flex items-center gap-4">
              {/* Exit Button */}
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setShowConfirmExit(true)}
                className="text-muted-foreground hover:text-foreground"
              >
                <X className="w-4 h-4 mr-1" />
                {t('practiceExam.exit')}
              </Button>
              <div className="h-4 w-px bg-border" />
              <span className="text-sm font-medium">
                {t('practiceExam.questionOf', { current: currentIndex + 1, total: selectedQuestions.length })}
              </span>
              <div className="h-4 w-px bg-border" />
              <span className="text-sm text-muted-foreground">
                {t('practiceExam.answered', { count: answeredCount })}
              </span>
              {flaggedCount > 0 && (
                <>
                  <div className="h-4 w-px bg-border" />
                  <span className="text-sm text-amber-500 flex items-center gap-1">
                    <Flag className="w-3.5 h-3.5" />
                    {t('practiceExam.flagged', { count: flaggedCount })}
                  </span>
                </>
              )}
            </div>
            <div className="flex items-center gap-4">
              {/* Pomodoro Toggle */}
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setShowPomodoro(!showPomodoro)}
                className={cn(showPomodoro && 'bg-purple-500/10 text-purple-500')}
                title="Pomodoro Timer"
              >
                <Timer className="w-4 h-4" />
              </Button>

              <div className={cn(
                'flex items-center gap-2 px-3 py-1.5 rounded-full font-mono text-sm font-medium',
                timeRemaining < 300 ? 'bg-red-500/10 text-red-500' : 'bg-muted'
              )}>
                <Clock className="w-4 h-4" />
                {formatTime(timeRemaining)}
              </div>
              <Button
                variant="default"
                size="sm"
                onClick={() => setShowConfirmSubmit(true)}
                className="bg-purple-500 hover:bg-purple-600"
              >
                {t('practiceExam.submitExam')}
              </Button>
            </div>
          </div>

          {/* Progress bar */}
          <div className="h-1 bg-muted">
            <div
              className="h-full bg-purple-500 transition-all"
              style={{ width: `${(answeredCount / selectedQuestions.length) * 100}%` }}
            />
          </div>
        </div>

        {/* Pomodoro Timer Sidebar */}
        <AnimatePresence>
          {showPomodoro && (
            <motion.div
              initial={{ opacity: 0, x: 300 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 300 }}
              className="fixed right-4 top-20 z-20 w-72"
            >
              <PomodoroTimer
                onSessionComplete={(type) => {
                  if (type === 'focus') {
                    // Could show a notification or play sound
                  }
                }}
              />
            </motion.div>
          )}
        </AnimatePresence>

        {/* Question Content */}
        <div className="flex-1 max-w-4xl mx-auto w-full px-4 py-8">
          <motion.div
            key={currentQuestion.id}
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            className="bg-card border border-border rounded-xl p-6"
          >
            {/* Question Header */}
            <div className="flex items-start justify-between mb-6">
              <div className="flex items-center gap-2">
                <span className={cn(
                  'px-2 py-0.5 rounded text-xs font-medium',
                  currentQuestion.difficulty === 'easy' && 'bg-green-500/10 text-green-500',
                  currentQuestion.difficulty === 'medium' && 'bg-amber-500/10 text-amber-500',
                  currentQuestion.difficulty === 'hard' && 'bg-red-500/10 text-red-500'
                )}>
                  {currentQuestion.difficulty}
                </span>
                {currentQuestion.topic && (
                  <span className="text-xs text-muted-foreground">{currentQuestion.topic}</span>
                )}
              </div>
              <div className="flex items-center gap-1">
                <button
                  onClick={() => toggleBookmark(currentQuestion.id)}
                  className={cn(
                    'p-2 rounded-lg transition-colors',
                    bookmarkedIds.has(currentQuestion.id)
                      ? 'bg-blue-500/10 text-blue-500'
                      : 'hover:bg-muted text-muted-foreground'
                  )}
                  title="Bookmark question"
                >
                  <Bookmark className={cn('w-5 h-5', bookmarkedIds.has(currentQuestion.id) && 'fill-current')} />
                </button>
                <button
                  onClick={toggleFlag}
                  className={cn(
                    'p-2 rounded-lg transition-colors',
                    currentAnswer?.flagged
                      ? 'bg-amber-500/10 text-amber-500'
                      : 'hover:bg-muted text-muted-foreground'
                  )}
                  title="Flag for review"
                >
                  <Flag className="w-5 h-5" />
                </button>
              </div>
            </div>

            {/* Question Text */}
            <p className="text-lg mb-6">{currentQuestion.question}</p>

            {/* Options */}
            {currentQuestion.options && currentQuestion.options.length > 0 ? (
              <div className="space-y-3">
                {currentQuestion.options.map((option, i) => (
                  <button
                    key={i}
                    onClick={() => handleAnswer(option)}
                    className={cn(
                      'w-full flex items-center gap-3 p-4 rounded-xl border text-left transition-all',
                      currentAnswer?.answer === option
                        ? 'border-purple-500 bg-purple-500/10'
                        : 'border-border hover:border-purple-500/50 hover:bg-muted/50'
                    )}
                  >
                    <span className={cn(
                      'w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium',
                      currentAnswer?.answer === option
                        ? 'bg-purple-500 text-white'
                        : 'bg-muted'
                    )}>
                      {String.fromCharCode(65 + i)}
                    </span>
                    <span>{option}</span>
                  </button>
                ))}
              </div>
            ) : (
              <textarea
                value={currentAnswer?.answer || ''}
                onChange={(e) => handleAnswer(e.target.value)}
                placeholder={t('practiceExam.typeAnswerHere')}
                rows={4}
                className="w-full px-4 py-3 bg-background border border-border rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 resize-none"
              />
            )}
          </motion.div>

          {/* Navigation */}
          <div className="flex items-center justify-between mt-6">
            <Button
              variant="outline"
              onClick={() => goToQuestion(currentIndex - 1)}
              disabled={currentIndex === 0}
            >
              <ChevronLeft className="w-4 h-4 mr-1" />
              {t('practiceExam.previous')}
            </Button>

            {/* Question dots */}
            <div className="flex gap-1 flex-wrap justify-center max-w-md">
              {selectedQuestions.map((q, i) => {
                const answer = answers.get(q.id);
                return (
                  <button
                    key={q.id}
                    onClick={() => goToQuestion(i)}
                    className={cn(
                      'w-8 h-8 rounded-lg text-xs font-medium transition-colors',
                      i === currentIndex && 'ring-2 ring-purple-500',
                      answer?.flagged && 'bg-amber-500/20 text-amber-500',
                      answer?.answer && !answer.flagged && 'bg-green-500/20 text-green-500',
                      !answer?.answer && !answer?.flagged && 'bg-muted'
                    )}
                  >
                    {i + 1}
                  </button>
                );
              })}
            </div>

            <Button
              onClick={() => goToQuestion(currentIndex + 1)}
              disabled={currentIndex === selectedQuestions.length - 1}
            >
              {t('practiceExam.next')}
              <ChevronRight className="w-4 h-4 ml-1" />
            </Button>
          </div>
        </div>

        {/* Submit Confirmation */}
        <AnimatePresence>
          {showConfirmSubmit && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
              onClick={() => setShowConfirmSubmit(false)}
            >
              <motion.div
                initial={{ scale: 0.95, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.95, opacity: 0 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-card border border-border rounded-xl p-6 max-w-sm w-full"
              >
                <h3 className="text-lg font-semibold mb-2">{t('practiceExam.submitExamConfirm')}</h3>
                <p className="text-sm text-muted-foreground mb-4">
                  {t('practiceExam.answeredOf', { answered: answeredCount, total: selectedQuestions.length })}
                  {selectedQuestions.length - answeredCount > 0 && (
                    <span className="text-amber-500">
                      {' '}{t('practiceExam.questionsUnanswered', { count: selectedQuestions.length - answeredCount })}
                    </span>
                  )}
                </p>
                <div className="flex justify-end gap-2">
                  <Button variant="outline" onClick={() => setShowConfirmSubmit(false)}>
                    {t('practiceExam.continueExam')}
                  </Button>
                  <Button onClick={handleSubmit} className="bg-purple-500 hover:bg-purple-600">
                    {t('practiceExam.submitExam')}
                  </Button>
                </div>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Exit Confirmation */}
        <AnimatePresence>
          {showConfirmExit && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
              onClick={() => setShowConfirmExit(false)}
            >
              <motion.div
                initial={{ scale: 0.95, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.95, opacity: 0 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-card border border-border rounded-xl p-6 max-w-sm w-full"
              >
                <div className="w-12 h-12 rounded-full bg-amber-500/10 flex items-center justify-center mx-auto mb-4">
                  <AlertCircle className="w-6 h-6 text-amber-500" />
                </div>
                <h3 className="text-lg font-semibold mb-2 text-center">{t('practiceExam.exitExam')}</h3>
                <p className="text-sm text-muted-foreground mb-4 text-center">
                  {t('practiceExam.progressLost', { answered: answeredCount, total: selectedQuestions.length })}
                </p>
                <div className="flex justify-center gap-2">
                  <Button variant="outline" onClick={() => setShowConfirmExit(false)}>
                    {t('practiceExam.continueExam')}
                  </Button>
                  <Button
                    variant="destructive"
                    onClick={() => navigate(`/dashboard/exam-clone/${id}`)}
                  >
                    {t('practiceExam.exit')}
                  </Button>
                </div>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    );
  }

  // Results Screen
  if (examState === 'results') {
    const results = calculateResults();

    return (
      <div className="min-h-screen bg-background">
        <div className="max-w-4xl mx-auto px-4 py-12">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-card border border-border rounded-2xl p-8 text-center mb-8"
          >
            {/* Score */}
            <div className={cn(
              'w-32 h-32 rounded-full flex items-center justify-center mx-auto mb-6',
              results.score >= 80 ? 'bg-green-500/10' : results.score >= 60 ? 'bg-amber-500/10' : 'bg-red-500/10'
            )}>
              <div>
                <p className={cn(
                  'text-4xl font-bold',
                  results.score >= 80 ? 'text-green-500' : results.score >= 60 ? 'text-amber-500' : 'text-red-500'
                )}>
                  {results.score}%
                </p>
                <p className="text-xs text-muted-foreground">{t('practiceExam.score')}</p>
              </div>
            </div>

            <h1 className="text-2xl font-bold mb-2">
              {results.score >= 80 ? t('practiceExam.excellent') : results.score >= 60 ? t('practiceExam.goodJob') : t('practiceExam.keepPracticing')}
            </h1>
            <p className="text-muted-foreground mb-6">
              {t('practiceExam.answeredCorrectly', { correct: results.correct, total: selectedQuestions.length })}
            </p>

            {/* Stats */}
            <div className="grid grid-cols-4 gap-4 mb-8">
              <div className="p-4 bg-green-500/10 rounded-xl">
                <p className="text-2xl font-bold text-green-500">{results.correct}</p>
                <p className="text-xs text-muted-foreground">{t('practiceExam.correct')}</p>
              </div>
              <div className="p-4 bg-red-500/10 rounded-xl">
                <p className="text-2xl font-bold text-red-500">{results.incorrect}</p>
                <p className="text-xs text-muted-foreground">{t('practiceExam.incorrect')}</p>
              </div>
              <div className="p-4 bg-muted rounded-xl">
                <p className="text-2xl font-bold">{results.unanswered}</p>
                <p className="text-xs text-muted-foreground">{t('practiceExam.unanswered')}</p>
              </div>
              <div className="p-4 bg-blue-500/10 rounded-xl">
                <p className="text-2xl font-bold text-blue-500">{formatTime(results.timeTaken)}</p>
                <p className="text-xs text-muted-foreground">{t('practiceExam.timeTaken')}</p>
              </div>
            </div>

            {/* Actions */}
            <div className="flex justify-center gap-3">
              <Button variant="outline" onClick={() => setExamState('review')}>
                <BookOpen className="w-4 h-4 mr-2" />
                {t('practiceExam.reviewAnswers')}
              </Button>
              <Button onClick={() => setExamState('setup')}>
                <RotateCcw className="w-4 h-4 mr-2" />
                {t('practiceExam.tryAgain')}
              </Button>
              <Button
                variant="outline"
                onClick={() => navigate(`/dashboard/exam-clone/${id}`)}
              >
                {t('practiceExam.backToExam')}
              </Button>
            </div>
          </motion.div>
        </div>
      </div>
    );
  }

  // Review Screen
  if (examState === 'review') {
    return (
      <div className="min-h-screen bg-background">
        <div className="sticky top-0 bg-background/95 backdrop-blur border-b border-border z-10">
          <div className="max-w-4xl mx-auto px-4 py-3 flex items-center justify-between">
            <h1 className="font-semibold">{t('practiceExam.answerReview')}</h1>
            <Button variant="outline" size="sm" onClick={() => setExamState('results')}>
              <ArrowLeft className="w-4 h-4 mr-2" />
              {t('practiceExam.backToResults')}
            </Button>
          </div>
        </div>

        <div className="max-w-4xl mx-auto px-4 py-8 space-y-6">
          {selectedQuestions.map((question, index) => {
            const userAnswer = answers.get(question.id);
            const isCorrect = userAnswer?.answer === question.correctAnswer;

            return (
              <motion.div
                key={question.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: index * 0.05 }}
                className={cn(
                  'bg-card border rounded-xl p-6',
                  isCorrect ? 'border-green-500/30' : 'border-red-500/30'
                )}
              >
                <div className="flex items-start gap-4 mb-4">
                  <span className={cn(
                    'w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium flex-shrink-0',
                    isCorrect ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'
                  )}>
                    {isCorrect ? <CheckCircle className="w-5 h-5" /> : <X className="w-5 h-5" />}
                  </span>
                  <div className="flex-1">
                    <p className="font-medium mb-1">{t('practiceExam.question', { number: index + 1 })}</p>
                    <p className="text-muted-foreground">{question.question}</p>
                  </div>
                </div>

                {/* Options with correct/wrong highlighting */}
                {question.options && (
                  <div className="space-y-2 ml-12 mb-4">
                    {question.options.map((opt, i) => (
                      <div
                        key={i}
                        className={cn(
                          'flex items-center gap-2 p-3 rounded-lg text-sm',
                          opt === question.correctAnswer && 'bg-green-500/10 border border-green-500/20',
                          opt === userAnswer?.answer && opt !== question.correctAnswer && 'bg-red-500/10 border border-red-500/20',
                          opt !== question.correctAnswer && opt !== userAnswer?.answer && 'bg-muted/50'
                        )}
                      >
                        <span className="w-6 h-6 rounded-full bg-background flex items-center justify-center text-xs font-medium">
                          {String.fromCharCode(65 + i)}
                        </span>
                        {opt}
                        {opt === question.correctAnswer && (
                          <CheckCircle className="w-4 h-4 text-green-500 ml-auto" />
                        )}
                        {opt === userAnswer?.answer && opt !== question.correctAnswer && (
                          <X className="w-4 h-4 text-red-500 ml-auto" />
                        )}
                      </div>
                    ))}
                  </div>
                )}

                {/* Explanation */}
                {question.explanation && (
                  <div className="ml-12 p-3 bg-blue-500/10 border border-blue-500/20 rounded-lg">
                    <p className="text-xs font-medium text-blue-500 mb-1">{t('examDetail.explanation')}</p>
                    <p className="text-sm">{question.explanation}</p>
                  </div>
                )}
              </motion.div>
            );
          })}
        </div>
      </div>
    );
  }

  return null;
}

import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { DashboardLayout } from '@/layouts/DashboardLayout';
import { Button } from '@/components/ui/button';
import { Spinner } from '@/components/ui/spinner';
import { motion } from 'framer-motion';
import type { QuizQuestion } from '@/services/problemSolver';
import { problemSolverService } from '@/services/problemSolver';
import { ArrowLeft, CheckCircle, XCircle, Trophy, RotateCcw, Zap } from 'lucide-react';

export function PracticeQuizPage() {
  const { t } = useTranslation();
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [questions, setQuestions] = useState<QuizQuestion[]>([]);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [result, setResult] = useState<{ isCorrect: boolean; correctAnswer: string; explanation: string } | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [score, setScore] = useState({ correct: 0, total: 0 });
  const [finished, setFinished] = useState(false);

  useEffect(() => {
    if (!id) return;

    const loadQuiz = async () => {
      setLoading(true);
      try {
        const existing = await problemSolverService.getQuizQuestions(id!);
        if (existing.length > 0) {
          setQuestions(existing);
          const answered = existing.filter(q => q.userAnswer !== null);
          setScore({ correct: answered.filter(q => q.isCorrect).length, total: answered.length });
          if (answered.length === existing.length) setFinished(true);
          else setCurrentIdx(answered.length);
        }
      } catch (err) {
        console.error('Failed to load quiz:', err);
      }
      setLoading(false);
    };

    loadQuiz();
  }, [id]);

  const generateQuiz = async () => {
    setGenerating(true);
    try {
      const qs = await problemSolverService.generatePracticeQuiz(id!, 5);
      setQuestions(qs);
      setCurrentIdx(0);
      setScore({ correct: 0, total: 0 });
      setFinished(false);
    } catch (err) {
      console.error('Failed to generate quiz:', err);
    }
    setGenerating(false);
  };

  const submitAnswer = async () => {
    if (!selectedAnswer || !questions[currentIdx]) return;
    setSubmitting(true);
    try {
      const res = await problemSolverService.submitQuizAnswer(questions[currentIdx].id, selectedAnswer);
      setResult(res);
      setScore(prev => ({
        correct: prev.correct + (res.isCorrect ? 1 : 0),
        total: prev.total + 1,
      }));
    } catch (err) {
      console.error('Failed to submit answer:', err);
    }
    setSubmitting(false);
  };

  const nextQuestion = () => {
    if (currentIdx + 1 >= questions.length) {
      setFinished(true);
    } else {
      setCurrentIdx(prev => prev + 1);
      setSelectedAnswer(null);
      setResult(null);
    }
  };

  const q = questions[currentIdx];
  const diffColor = (d: string) => d === 'easy' ? 'text-green-500 bg-green-500/10' : d === 'hard' ? 'text-red-500 bg-red-500/10' : 'text-amber-500 bg-amber-500/10';

  return (
    <DashboardLayout>
      <div className="max-w-3xl mx-auto">
        <div className="flex items-center gap-3 mb-6">
          <button onClick={() => navigate(`/dashboard/problem-solver/solution/${id}`)} className="p-2 hover:bg-muted rounded-lg">
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-xl font-bold flex items-center gap-2">
              <Zap className="w-5 h-5 text-amber-500" /> {t('practiceQuiz.title')}
            </h1>
            <p className="text-sm text-muted-foreground">{t('practiceQuiz.subtitle')}</p>
          </div>
        </div>

        {loading ? (
          <div className="flex justify-center py-20"><Spinner size="lg" /></div>
        ) : questions.length === 0 ? (
          <div className="bg-card rounded-2xl border p-8 text-center">
            <Zap className="w-12 h-12 text-amber-500 mx-auto mb-4" />
            <h2 className="text-lg font-semibold mb-2">{t('practiceQuiz.generateTitle')}</h2>
            <p className="text-muted-foreground mb-6">{t('practiceQuiz.generateDescription')}</p>
            <Button onClick={generateQuiz} disabled={generating}>
              {generating ? <><Spinner size="sm" className="mr-2" />{t('practiceQuiz.generating')}</> : t('practiceQuiz.generateButton')}
            </Button>
          </div>
        ) : finished ? (
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="bg-card rounded-2xl border p-8 text-center">
            <Trophy className="w-16 h-16 text-amber-500 mx-auto mb-4" />
            <h2 className="text-2xl font-bold mb-2">{t('practiceQuiz.quizComplete')}</h2>
            <p className="text-4xl font-bold text-green-500 mb-2">{score.correct}/{score.total}</p>
            <p className="text-muted-foreground mb-6">
              {score.correct === score.total ? t('practiceQuiz.perfectScore') : score.correct >= score.total * 0.7 ? t('practiceQuiz.greatJob') : t('practiceQuiz.keepPracticing')}
            </p>
            <div className="flex gap-3 justify-center">
              <Button variant="outline" onClick={() => navigate(`/dashboard/problem-solver/solution/${id}`)}>
                {t('practiceQuiz.backToSolution')}
              </Button>
              <Button onClick={() => { setQuestions([]); generateQuiz(); }}>
                <RotateCcw className="w-4 h-4 mr-2" /> {t('practiceQuiz.newQuiz')}
              </Button>
            </div>
          </motion.div>
        ) : q ? (
          <div>
            {/* Progress */}
            <div className="flex items-center gap-3 mb-6">
              <div className="flex-1 h-2 bg-muted rounded-full overflow-hidden">
                <div className="h-full bg-green-500 transition-all" style={{ width: `${((currentIdx + (result ? 1 : 0)) / questions.length) * 100}%` }} />
              </div>
              <span className="text-sm font-medium">{currentIdx + 1}/{questions.length}</span>
              <span className={`text-xs px-2 py-0.5 rounded-full ${diffColor(q.difficulty)}`}>{q.difficulty}</span>
            </div>

            <motion.div key={currentIdx} initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="bg-card rounded-2xl border p-6">
              <p className="text-lg font-medium mb-6">{q.question}</p>

              <div className="space-y-3 mb-6">
                {q.options.map((opt, i) => (
                  <button
                    key={i}
                    onClick={() => !result && setSelectedAnswer(opt)}
                    disabled={!!result}
                    className={`w-full text-left p-4 rounded-xl border transition-all ${
                      result
                        ? opt === result.correctAnswer
                          ? 'border-green-500 bg-green-500/10'
                          : opt === selectedAnswer && !result.isCorrect
                            ? 'border-red-500 bg-red-500/10'
                            : 'border-border opacity-50'
                        : selectedAnswer === opt
                          ? 'border-green-500 bg-green-500/5'
                          : 'border-border hover:border-green-500/50'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <span className="w-8 h-8 rounded-full bg-muted flex items-center justify-center text-sm font-medium shrink-0">
                        {String.fromCharCode(65 + i)}
                      </span>
                      <span className="text-sm">{opt}</span>
                      {result && opt === result.correctAnswer && <CheckCircle className="w-5 h-5 text-green-500 ml-auto" />}
                      {result && opt === selectedAnswer && !result.isCorrect && <XCircle className="w-5 h-5 text-red-500 ml-auto" />}
                    </div>
                  </button>
                ))}
              </div>

              {result && (
                <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className={`p-4 rounded-xl mb-4 ${result.isCorrect ? 'bg-green-500/10 border border-green-500/20' : 'bg-red-500/10 border border-red-500/20'}`}>
                  <p className="text-sm font-medium mb-1">{result.isCorrect ? t('practiceQuiz.correctResult') : t('practiceQuiz.incorrectResult')}</p>
                  <p className="text-sm text-muted-foreground">{result.explanation}</p>
                </motion.div>
              )}

              {!result ? (
                <Button onClick={submitAnswer} disabled={!selectedAnswer || submitting} className="w-full">
                  {submitting ? <><Spinner size="sm" className="mr-2" />{t('practiceQuiz.checking')}</> : t('practiceQuiz.submitAnswer')}
                </Button>
              ) : (
                <Button onClick={nextQuestion} className="w-full">
                  {currentIdx + 1 >= questions.length ? t('practiceQuiz.seeResults') : t('practiceQuiz.nextQuestion')}
                </Button>
              )}
            </motion.div>
          </div>
        ) : null}
      </div>
    </DashboardLayout>
  );
}

export default PracticeQuizPage;

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { DashboardLayout } from '@/layouts/DashboardLayout';
import { Button } from '@/components/ui/button';
import { Spinner } from '@/components/ui/spinner';
import { useProblemSolverStore } from '@/stores/useProblemSolverStore';
import { motion } from 'framer-motion';
import {
  ArrowLeft,
  Search,
  Trash2,
  CheckCircle,
  XCircle,
  Clock,
  Loader2,
  Filter,
  ChevronDown,
  Brain,
} from 'lucide-react';

const SUBJECT_FILTER_KEYS = ['all', 'mathematics', 'physics', 'chemistry', 'biology', 'computerScience', 'other'] as const;

export function ProblemHistoryPage() {
  const navigate = useNavigate();
  const { t } = useTranslation();
  const { sessions, fetchSessions, deleteSession, isLoading, error } =
    useProblemSolverStore();
  const [searchQuery, setSearchQuery] = useState('');
  const [subjectFilter, setSubjectFilter] = useState('all');
  const [showFilter, setShowFilter] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  useEffect(() => {
    fetchSessions();
  }, [fetchSessions]);

  const FILTER_KEY_TO_SUBJECT: Record<string, string> = {
    all: 'All',
    mathematics: 'Mathematics',
    physics: 'Physics',
    chemistry: 'Chemistry',
    biology: 'Biology',
    computerScience: 'Computer Science',
    other: 'Other',
  };

  const filtered = sessions.filter((s) => {
    const matchSearch =
      !searchQuery ||
      s.problem.toLowerCase().includes(searchQuery.toLowerCase()) ||
      s.finalAnswer?.toLowerCase().includes(searchQuery.toLowerCase());
    const matchSubject =
      subjectFilter === 'all' || s.subject === FILTER_KEY_TO_SUBJECT[subjectFilter];
    return matchSearch && matchSubject;
  });

  const handleDelete = async (id: string) => {
    await deleteSession(id);
    setDeleteId(null);
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'completed':
        return <CheckCircle className="w-4 h-4 text-green-500" />;
      case 'failed':
        return <XCircle className="w-4 h-4 text-red-500" />;
      case 'pending':
        return <Clock className="w-4 h-4 text-muted-foreground" />;
      default:
        return <Loader2 className="w-4 h-4 text-amber-500 animate-spin" />;
    }
  };

  const formatDate = (date: string) => {
    const d = new Date(date);
    const now = new Date();
    const diff = now.getTime() - d.getTime();
    const days = Math.floor(diff / 86400000);

    if (days === 0) return t('problemHistory.today');
    if (days === 1) return t('problemHistory.yesterday');
    if (days < 7) return t('problemHistory.daysAgo', { count: days });
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  };

  return (
    <DashboardLayout>
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="mb-6"
        >
          <button
            onClick={() => navigate('/dashboard/problem-solver')}
            className="flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground mb-4 transition-colors"
          >
            <ArrowLeft className="w-4 h-4" />
            {t('problemHistory.backToProblemSolver')}
          </button>

          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold">{t('problemHistory.title')}</h1>
              <p className="text-muted-foreground text-sm">
                {t('problemHistory.problemsSolved', { count: sessions.length })}
              </p>
            </div>
            <Button onClick={() => navigate('/dashboard/problem-solver')}>
              {t('problemHistory.solveNewProblem')}
            </Button>
          </div>
        </motion.div>

        {/* Search & Filter */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.05 }}
          className="flex gap-3 mb-6"
        >
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder={t('problemHistory.searchPlaceholder')}
              className="w-full pl-10 pr-4 py-2.5 bg-card border border-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-green-500/50"
            />
          </div>
          <div className="relative">
            <button
              onClick={() => setShowFilter(!showFilter)}
              className="flex items-center gap-2 px-4 py-2.5 bg-card border border-border rounded-xl text-sm hover:bg-muted transition-colors"
            >
              <Filter className="w-4 h-4" />
              {t(`problemHistory.subjectFilters.${subjectFilter}`)}
              <ChevronDown className="w-3 h-3" />
            </button>
            {showFilter && (
              <>
                <div className="fixed inset-0 z-40" onClick={() => setShowFilter(false)} />
                <div className="absolute right-0 top-full mt-1 bg-card border border-border rounded-lg shadow-lg z-50 py-1 w-48">
                  {SUBJECT_FILTER_KEYS.map((s) => (
                    <button
                      key={s}
                      onClick={() => {
                        setSubjectFilter(s);
                        setShowFilter(false);
                      }}
                      className={`w-full text-left px-3 py-2 text-sm hover:bg-muted ${
                        subjectFilter === s ? 'text-green-500 font-medium' : ''
                      }`}
                    >
                      {t(`problemHistory.subjectFilters.${s}`)}
                    </button>
                  ))}
                </div>
              </>
            )}
          </div>
        </motion.div>

        {/* Error */}
        {error && (
          <div className="mb-4 p-3 bg-red-500/10 border border-red-500/20 rounded-xl text-sm text-red-500">
            {error}
          </div>
        )}

        {/* Loading */}
        {isLoading && (
          <div className="flex justify-center py-12">
            <Spinner size="lg" />
          </div>
        )}

        {/* Empty state */}
        {!isLoading && filtered.length === 0 && (
          <div className="text-center py-16">
            <Brain className="w-12 h-12 text-muted-foreground/30 mx-auto mb-3" />
            <p className="text-muted-foreground font-medium">
              {searchQuery || subjectFilter !== 'all'
                ? t('problemHistory.noProblemsMatch')
                : t('problemHistory.noProblemsYet')}
            </p>
            <p className="text-sm text-muted-foreground mt-1">
              {searchQuery || subjectFilter !== 'all'
                ? t('problemHistory.adjustSearch')
                : t('problemHistory.startFirst')}
            </p>
          </div>
        )}

        {/* Problem List */}
        <div className="space-y-3">
          {filtered.map((session, idx) => (
            <motion.div
              key={session.id}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.03 }}
              className="bg-card border border-border rounded-xl p-4 hover:border-green-500/30 transition-all cursor-pointer group"
              onClick={() => {
                if (session.status === 'completed') {
                  navigate(`/dashboard/problem-solver/solution/${session.id}`);
                } else if (
                  session.status === 'analyzing' ||
                  session.status === 'solving' ||
                  session.status === 'verifying'
                ) {
                  navigate(`/dashboard/problem-solver/solve/${session.id}`);
                }
              }}
            >
              <div className="flex items-start gap-3">
                <div className="mt-0.5">{getStatusIcon(session.status)}</div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium line-clamp-2">{session.problem}</p>
                  {session.finalAnswer && (
                    <p className="text-xs text-muted-foreground mt-1 line-clamp-1">
                      {t('problemHistory.answer')} {session.finalAnswer}
                    </p>
                  )}
                  <div className="flex items-center gap-3 mt-2">
                    {session.subject && (
                      <span className="px-2 py-0.5 bg-purple-500/10 text-purple-500 rounded-full text-xs font-medium">
                        {session.subject}
                      </span>
                    )}
                    <span className="text-xs text-muted-foreground">
                      {formatDate(session.createdAt)}
                    </span>
                  </div>
                </div>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    setDeleteId(session.id);
                  }}
                  className="opacity-0 group-hover:opacity-100 p-1.5 hover:bg-red-500/10 rounded-lg transition-all"
                >
                  <Trash2 className="w-4 h-4 text-red-500" />
                </button>
              </div>
            </motion.div>
          ))}
        </div>

        {/* Delete Confirmation */}
        {deleteId && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
            <div className="bg-card border border-border rounded-2xl p-6 max-w-sm w-full mx-4">
              <h3 className="font-semibold mb-2">{t('problemHistory.deleteProblem')}</h3>
              <p className="text-sm text-muted-foreground mb-4">
                {t('problemHistory.deleteConfirmation')}
              </p>
              <div className="flex gap-3">
                <Button
                  variant="outline"
                  className="flex-1"
                  onClick={() => setDeleteId(null)}
                >
                  {t('common.cancel')}
                </Button>
                <Button
                  variant="destructive"
                  className="flex-1 bg-red-500 hover:bg-red-600"
                  onClick={() => handleDelete(deleteId)}
                >
                  {t('common.delete')}
                </Button>
              </div>
            </div>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

