              )}
              {altLoading && (
                <div className="flex justify-center py-12">
                  <Spinner size="lg" />
                </div>
              )}
              {altMethods.map((method, idx) => (
                <motion.div
                  key={method.id || idx}
                  initial={{ opacity: 0, y: 15 }}
                  animate={{ opacity: 1, y: 0 }}
