  const filterChips: FilterStatus[] = ['All', 'New', 'Learning', 'Review', 'Mastered', 'Due'];

  const sortLabels: Record<SortOption, string> = {
    newest: 'Newest First',
    oldest: 'Oldest First',
    difficulty: 'Difficulty',
