import { create } from 'zustand';
import type {
  Flashcard,
  CreateFlashcardRequest,
  UpdateFlashcardRequest,
  ReviewFlashcardRequest,
} from '@/types';
import { flashcardsService, type FlashcardsListParams } from '@/services/flashcards';
import { isFlashcardDue } from '@/types';

interface FlashcardsState {
  flashcards: Flashcard[];
  currentFlashcard: Flashcard | null;
  isLoading: boolean;
  error: string | null;
  totalPages: number;
  currentPage: number;
  total: number;

  // Study session state
  studyQueue: Flashcard[];
  currentStudyIndex: number;
  isFlipped: boolean;
  sessionStats: {
    reviewed: number;
    correct: number;
    incorrect: number;
  };

  // Actions
  fetchFlashcards: (studySetId: string, params?: FlashcardsListParams) => Promise<void>;
  createFlashcard: (data: CreateFlashcardRequest) => Promise<Flashcard>;
  updateFlashcard: (id: string, data: UpdateFlashcardRequest) => Promise<void>;
  deleteFlashcard: (id: string) => Promise<void>;
  reviewFlashcard: (id: string, data: ReviewFlashcardRequest) => Promise<void>;
  clearError: () => void;

  // Study session actions
  startStudySession: (flashcards: Flashcard[]) => void;
  flipCard: () => void;
  nextCard: () => void;
  prevCard: () => void;
  goToCard: (index: number) => void;
  resetSession: () => void;
}

export const useFlashcardsStore = create<FlashcardsState>((set) => ({
  flashcards: [],
  currentFlashcard: null,
  isLoading: false,
  error: null,
  totalPages: 0,
  currentPage: 1,
  total: 0,

  // Study session state
  studyQueue: [],
  currentStudyIndex: 0,
  isFlipped: false,
  sessionStats: {
    reviewed: 0,
    correct: 0,
    incorrect: 0,
  },

  fetchFlashcards: async (studySetId, params) => {
    set({ isLoading: true, error: null });
    try {
      const response = await flashcardsService.list(studySetId, params);
      set({
        flashcards: response.data,
        totalPages: response.totalPages,
        currentPage: response.page,
        total: response.total,
        isLoading: false,
      });
    } catch (error) {
      set({
        error: error instanceof Error ? error.message : 'Failed to fetch flashcards',
        isLoading: false,
      });
    }
  },

  createFlashcard: async (data) => {
    set({ isLoading: true, error: null });
    try {
      const flashcard = await flashcardsService.create(data);
      set((state) => ({
        flashcards: [...state.flashcards, flashcard],
        isLoading: false,
      }));
      return flashcard;
    } catch (error) {
      set({
        error: error instanceof Error ? error.message : 'Failed to create flashcard',
        isLoading: false,
      });
      throw error;
    }
  },

  updateFlashcard: async (id, data) => {
    set({ isLoading: true, error: null });
    try {
      const updatedFlashcard = await flashcardsService.update(id, data);
      set((state) => ({
        flashcards: state.flashcards.map((f) => (f.id === id ? updatedFlashcard : f)),
        isLoading: false,
      }));
    } catch (error) {
      set({
        error: error instanceof Error ? error.message : 'Failed to update flashcard',
        isLoading: false,
      });
      throw error;
    }
  },

  deleteFlashcard: async (id) => {
    set({ isLoading: true, error: null });
    try {
      await flashcardsService.delete(id);
      set((state) => ({
        flashcards: state.flashcards.filter((f) => f.id !== id),
        isLoading: false,
      }));
    } catch (error) {
      set({
        error: error instanceof Error ? error.message : 'Failed to delete flashcard',
        isLoading: false,
      });
      throw error;
    }
  },

  reviewFlashcard: async (id, data) => {
    set({ isLoading: true, error: null });
    try {
      const isCorrect = data.quality >= 3;
      const updatedFlashcard = await flashcardsService.review(id, data);

      set((state) => ({
        flashcards: state.flashcards.map((f) => (f.id === id ? updatedFlashcard : f)),
        studyQueue: state.studyQueue.map((f) => (f.id === id ? updatedFlashcard : f)),
        sessionStats: {
          reviewed: state.sessionStats.reviewed + 1,
          correct: state.sessionStats.correct + (isCorrect ? 1 : 0),
          incorrect: state.sessionStats.incorrect + (isCorrect ? 0 : 1),
        },
        isLoading: false,
      }));
    } catch (error) {
      set({
        error: error instanceof Error ? error.message : 'Failed to review flashcard',
        isLoading: false,
      });
      throw error;
    }
  },

  clearError: () => set({ error: null }),

  // Study session actions
  startStudySession: (flashcards) => {
    const dueCards = flashcards.filter(isFlashcardDue);
    set({
      studyQueue: dueCards.length > 0 ? dueCards : flashcards,
      currentStudyIndex: 0,
      isFlipped: false,
      sessionStats: { reviewed: 0, correct: 0, incorrect: 0 },
    });
  },

  flipCard: () => set((state) => ({ isFlipped: !state.isFlipped })),

  nextCard: () =>
    set((state) => ({
      currentStudyIndex: Math.min(state.currentStudyIndex + 1, state.studyQueue.length),
      isFlipped: false,
    })),

  prevCard: () =>
    set((state) => ({
      currentStudyIndex: Math.max(state.currentStudyIndex - 1, 0),
      isFlipped: false,
    })),

  goToCard: (index: number) =>
    set((state) => ({
      currentStudyIndex: Math.max(0, Math.min(index, state.studyQueue.length - 1)),
      isFlipped: false,
    })),

  resetSession: () =>
    set({
      studyQueue: [],
      currentStudyIndex: 0,
      isFlipped: false,
      sessionStats: { reviewed: 0, correct: 0, incorrect: 0 },
    }),
}));

import { create } from 'zustand';
import api from '@/services/api';
import { ENDPOINTS } from '@/config/api';
import type { GamificationStats, XPEventType } from '@/types';
import { getLevelFromXP } from '@/types';

const XP_AMOUNTS: Record<XPEventType, number> = {
  card_review: 10,
  quiz_complete: 50,
  perfect_quiz: 100,
  daily_streak: 25,
  daily_goal: 50,
};

interface GamificationState {
  stats: GamificationStats | null;
  recentXpGain: number | null;
  isLoading: boolean;
  fetchGamification: () => Promise<void>;
  addXP: (type: XPEventType) => Promise<number>;
  clearRecentXp: () => void;
}

export const useGamificationStore = create<GamificationState>((set, get) => ({
  stats: null,
  recentXpGain: null,
  isLoading: false,

  fetchGamification: async () => {
    set({ isLoading: true });
    try {
      const res = await api.get(ENDPOINTS.users.gamification);
      set({ stats: res.data, isLoading: false });
    } catch {
      // Fallback to computed stats from user stats
      try {
        const statsRes = await api.get(ENDPOINTS.users.stats);
        const streakDays = statsRes.data.streakDays || 0;
        const totalXp = (statsRes.data.flashcardsCount || 0) * 10 + (statsRes.data.quizzesCompleted || 0) * 50;
        const { level, currentLevelXp, nextLevelXp } = getLevelFromXP(totalXp);
        set({
          stats: {
            totalXp,
            level,
            streakDays,
            dailyXp: 0,
            dailyGoal: 100,
            nextLevelXp,
            currentLevelXp,
          },
          isLoading: false,
        });
      } catch {
        set({ isLoading: false });
      }
    }
  },

  addXP: async (type: XPEventType) => {
    const xp = XP_AMOUNTS[type];
    try {
      await api.post(ENDPOINTS.users.addXp, { type, xp });
    } catch {
      // Continue with optimistic update even if API fails
    }

    const currentStats = get().stats;
    if (currentStats) {
      const newTotalXp = currentStats.totalXp + xp;
      const newDailyXp = currentStats.dailyXp + xp;
      const { level, currentLevelXp, nextLevelXp } = getLevelFromXP(newTotalXp);
      set({
        stats: {
          ...currentStats,
          totalXp: newTotalXp,
          dailyXp: newDailyXp,
          level,
          currentLevelXp,
          nextLevelXp,
        },
        recentXpGain: xp,
      });
    }
    return xp;
  },

  clearRecentXp: () => set({ recentXpGain: null }),
}));

import { create } from 'zustand';
import { io, Socket } from 'socket.io-client';
import { API_CONFIG } from '@/config/api';

interface Player {
  id: string;
  name: string;
  avatarUrl?: string;
  score: number;
  isHost: boolean;
  correctAnswers?: number;
  answers?: number;
}

interface PlayerAnswer {
  playerId: string;
  playerName: string;
  answerIndex: number;
  answerText: string;
  correct: boolean;
  pointsEarned: number;
}

interface LiveQuestion {
  id: string;
  question: string;
  options: string[];
  timeLimit: number;
  index: number;
  total: number;
}

interface QuestionResult {
  questionIndex: number;
  question: string;
  correctIndex: number;
  correctAnswer: string;
  playerAnswers: PlayerAnswer[];
  leaderboard: Player[];
}

type Phase = 'idle' | 'lobby' | 'countdown' | 'question' | 'result' | 'finished';

interface LiveQuizState {
  socket: Socket | null;
  roomCode: string | null;
  players: Player[];
  currentQuestion: LiveQuestion | null;
  questionResult: QuestionResult | null;
  phase: Phase;
  isHost: boolean;
  myAnswer: number | null; // Now stores answerIndex
  myAnswerLocked: boolean;
  timeLeft: number;
  answeredCount: number;
  finalRankings: Player[];
  error: string | null;
  countdownValue: number;

  connect: () => void;
  disconnect: () => void;
  createRoom: (studySetId: string) => void;
  joinRoom: (code: string, name?: string) => void;
  startGame: () => void;
  submitAnswer: (answerIndex: number) => void;
  leaveRoom: () => void;
  reset: () => void;
}

function mapPlayers(players: Array<{ id: string; name: string; avatarUrl?: string; score?: number; correctAnswers?: number; answers?: number }>, hostId: string): Player[] {
  if (!Array.isArray(players)) return [];
  return players.map((p) => ({
    id: p.id,
    name: p.name,
    avatarUrl: p.avatarUrl || undefined,
    score: p.score || 0,
    isHost: p.id === hostId,
    correctAnswers: p.correctAnswers,
    answers: p.answers,
  }));
}

export const useLiveQuizStore = create<LiveQuizState>((set, get) => {
  let timerInterval: ReturnType<typeof setInterval> | null = null;
  let countdownInterval: ReturnType<typeof setInterval> | null = null;
  let roomHostId: string | null = null;

  const clearTimer = () => {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
  };

  const clearCountdown = () => {
    if (countdownInterval) {
      clearInterval(countdownInterval);
      countdownInterval = null;
    }
  };

  return {
    socket: null,
    roomCode: null,
    players: [],
    currentQuestion: null,
    questionResult: null,
    phase: 'idle',
    isHost: false,
    myAnswer: null,
    myAnswerLocked: false,
    timeLeft: 0,
    answeredCount: 0,
    finalRankings: [],
    error: null,
    countdownValue: 0,

    connect: () => {
      const existing = get().socket;
      if (existing?.connected) return;

      const url = new URL(API_CONFIG.baseURL);
      const wsUrl = url.origin + '/live-quiz';
      const token = localStorage.getItem('accessToken');

      console.log('[LiveQuiz] Connecting to:', wsUrl);

      if (!token) {
        console.error('[LiveQuiz] No access token found!');
        set({ error: 'Not authenticated' });
        return;
      }

      const socket = io(wsUrl, {
        path: '/socket.io',
        transports: ['websocket', 'polling'],
        auth: { token },
      });

      socket.on('connect', () => {
        console.log('[LiveQuiz] Socket connected:', socket.id);
        set({ socket, error: null });
      });

      socket.on('connect_error', (err) => {
        console.error('[LiveQuiz] Connection error:', err.message);
        if (!socket.connected) {
          set({ error: `Connection failed: ${err.message}` });
        }
      });

      socket.on('disconnect', (reason) => {
        console.log('[LiveQuiz] Socket disconnected:', reason);
        set({ error: reason === 'io server disconnect' ? 'Disconnected by server' : null });
      });

      // Room events
      socket.on('room:created', (room: { code: string; hostId: string; players?: Array<{ id: string; name: string; avatarUrl?: string; score?: number; correctAnswers?: number; answers?: number }> }) => {
        console.log('[LiveQuiz] room:created:', room);
        roomHostId = room.hostId;
        set({
          roomCode: room.code,
          phase: 'lobby',
          isHost: true,
          players: mapPlayers(room.players || [], room.hostId),
          error: null,
        });
      });

      socket.on('room:joined', (room: { code: string; hostId: string; players?: Array<{ id: string; name: string; avatarUrl?: string; score?: number; correctAnswers?: number; answers?: number }> }) => {
        console.log('[LiveQuiz] room:joined:', room);
        roomHostId = room.hostId;
        set({
          roomCode: room.code,
          phase: 'lobby',
          players: mapPlayers(room.players || [], room.hostId),
          error: null,
        });
      });

      socket.on('room:updated', (room: { hostId?: string; players?: Array<{ id: string; name: string; avatarUrl?: string; score?: number; correctAnswers?: number; answers?: number }> }) => {
        if (room.hostId) roomHostId = room.hostId;
        set({ players: mapPlayers(room.players || [], roomHostId || '') });
      });

      // Game countdown (3 seconds before first question)
      socket.on('game:countdown', (data: { countdown: number }) => {
        console.log('[LiveQuiz] game:countdown:', data);
        set({ phase: 'countdown', countdownValue: data.countdown });
        clearCountdown();
        let count = data.countdown;
        countdownInterval = setInterval(() => {
          count--;
          set({ countdownValue: count });
          if (count <= 0) clearCountdown();
        }, 1000);
      });

      // Question start
      socket.on('question:start', (data: { index: number; question: string; options?: string[]; timeLimit?: number; total: number }) => {
        console.log('[LiveQuiz] question:start:', data);
        clearCountdown();
        clearTimer();

        const question: LiveQuestion = {
          id: `q-${data.index}`,
          question: data.question,
          options: data.options || [],
          timeLimit: data.timeLimit || 20,
          index: data.index,
          total: data.total,
        };

        set({
          currentQuestion: question,
          questionResult: null,
          myAnswer: null,
          myAnswerLocked: false,
          answeredCount: 0,
          phase: 'question',
          timeLeft: question.timeLimit,
        });

        // Client-side timer for UI
        timerInterval = setInterval(() => {
          const current = get().timeLeft;
          if (current <= 1) {
            clearTimer();
            set({ timeLeft: 0 });
          } else {
            set({ timeLeft: current - 1 });
          }
        }, 1000);
      });

      // Answer locked confirmation
      socket.on('answer:locked', (data: { questionIndex: number; answerIndex: number; correct: boolean; score: number }) => {
        console.log('[LiveQuiz] answer:locked:', data);
        set({ myAnswerLocked: true });
      });

      // Answer count update
      socket.on('answers:update', (data: { answeredCount: number; totalPlayers: number }) => {
        set({ answeredCount: data.answeredCount });
      });

      // Question result with all player answers
      socket.on('question:result', (data: QuestionResult) => {
        console.log('[LiveQuiz] question:result:', data);
        clearTimer();
        set({
          questionResult: data,
          phase: 'result',
          players: mapPlayers(data.leaderboard || [], roomHostId || ''),
        });
      });

      // Next question countdown
      socket.on('question:next', (data: { nextIndex: number; countdown: number }) => {
        console.log('[LiveQuiz] question:next:', data);
        set({ countdownValue: data.countdown, phase: 'countdown' });
        clearCountdown();
        let count = data.countdown;
        countdownInterval = setInterval(() => {
          count--;
          set({ countdownValue: count });
          if (count <= 0) clearCountdown();
        }, 1000);
      });

      // Game finished
      socket.on('game:finished', (data: { leaderboard: Array<{ id: string; name: string; avatarUrl?: string; score?: number; correctAnswers?: number; answers?: number }>; totalQuestions: number }) => {
        console.log('[LiveQuiz] game:finished:', data);
        clearTimer();
        clearCountdown();
        const rankings = mapPlayers(data.leaderboard || [], roomHostId || '');
        set({ finalRankings: rankings, phase: 'finished' });
      });

      socket.on('error', (data: string | { message?: string }) => {
        console.error('[LiveQuiz] error:', data);
        const message = typeof data === 'string' ? data : data?.message || 'Unknown error';
        set({ error: message });
      });

      socket.on('room:left', () => {
        clearTimer();
        clearCountdown();
        roomHostId = null;
        set({ roomCode: null, phase: 'idle', players: [], isHost: false });
      });

      set({ socket });
    },

    disconnect: () => {
      clearTimer();
      clearCountdown();
      const socket = get().socket;
      if (socket) {
        socket.disconnect();
        set({ socket: null });
      }
      roomHostId = null;
    },

    createRoom: (studySetId: string) => {
      const socket = get().socket;
      console.log('[LiveQuiz] createRoom:', { connected: socket?.connected, studySetId });
      if (!socket?.connected) {
        set({ error: 'Not connected to server' });
        return;
      }
      socket.emit('create-room', { studySetId });
    },

    joinRoom: (code: string, name?: string) => {
      const socket = get().socket;
      console.log('[LiveQuiz] joinRoom:', { code, name });
      if (!socket?.connected) {
        set({ error: 'Not connected to server' });
        return;
      }
      socket.emit('join-room', { code: code.toUpperCase(), name: name || 'Player' });
    },

    startGame: () => {
      const socket = get().socket;
      const code = get().roomCode;
      if (socket && code) {
        socket.emit('start-game', { code });
      }
    },

    submitAnswer: (answerIndex: number) => {
      const socket = get().socket;
      const code = get().roomCode;
      const question = get().currentQuestion;
      const myAnswer = get().myAnswer;

      // Don't submit if already answered
      if (myAnswer !== null) return;

      if (socket && code && question) {
        socket.emit('submit-answer', {
          code,
          questionIndex: question.index,
          answerIndex,
        });
        set({ myAnswer: answerIndex });
      }
    },

    leaveRoom: () => {
      const socket = get().socket;
      const code = get().roomCode;
      if (socket && code) {
        socket.emit('leave-room', { code });
      }
      clearTimer();
      clearCountdown();
      roomHostId = null;
      set({
        roomCode: null,
        phase: 'idle',
        players: [],
        isHost: false,
        currentQuestion: null,
        myAnswer: null,
        myAnswerLocked: false,
      });
    },

    reset: () => {
      clearTimer();
      clearCountdown();
      roomHostId = null;
      set({
        roomCode: null,
        players: [],
        currentQuestion: null,
        questionResult: null,
        phase: 'idle',
        isHost: false,
        myAnswer: null,
        myAnswerLocked: false,
        timeLeft: 0,
        answeredCount: 0,
        finalRankings: [],
        error: null,
        countdownValue: 0,
      });
    },
  };
});

import { create } from 'zustand';
import { notesService } from '@/services/notes';
import type { Note, CreateNoteRequest, UpdateNoteRequest } from '@/types';

interface NotesState {
  notes: Note[];
  currentNote: Note | null;
  isLoading: boolean;
  error: string | null;

  // Actions
  fetchNotes: (studySetId: string) => Promise<void>;
  fetchNote: (id: string) => Promise<void>;
  createNote: (data: CreateNoteRequest) => Promise<Note>;
  updateNote: (id: string, data: UpdateNoteRequest) => Promise<void>;
  deleteNote: (id: string) => Promise<void>;
  togglePin: (id: string) => Promise<void>;
  setCurrentNote: (note: Note | null) => void;
  clearError: () => void;
  clearNotes: () => void;
}

export const useNotesStore = create<NotesState>((set) => ({
  notes: [],
  currentNote: null,
  isLoading: false,
  error: null,

  fetchNotes: async (studySetId: string) => {
    set({ isLoading: true, error: null });
    try {
      const notes = await notesService.list(studySetId);
      set({ notes, isLoading: false });
    } catch (error) {
      set({
        error: error instanceof Error ? error.message : 'Failed to fetch notes',
        isLoading: false,
      });
    }
  },

  fetchNote: async (id: string) => {
    set({ isLoading: true, error: null });
    try {
      const note = await notesService.get(id);
      set({ currentNote: note, isLoading: false });
    } catch (error) {
      set({
        error: error instanceof Error ? error.message : 'Failed to fetch note',
        isLoading: false,
      });
    }
  },

  createNote: async (data: CreateNoteRequest) => {
    set({ isLoading: true, error: null });
    try {
      const note = await notesService.create(data);
      set((state) => ({
        notes: [note, ...state.notes],
        isLoading: false,
      }));
      return note;
    } catch (error) {
      set({
        error: error instanceof Error ? error.message : 'Failed to create note',
        isLoading: false,
      });
      throw error;
    }
  },

  updateNote: async (id: string, data: UpdateNoteRequest) => {
    set({ isLoading: true, error: null });
    try {
      const updatedNote = await notesService.update(id, data);
      set((state) => ({
        notes: state.notes.map((n) => (n.id === id ? updatedNote : n)),
        currentNote: state.currentNote?.id === id ? updatedNote : state.currentNote,
        isLoading: false,
      }));
    } catch (error) {
      set({
        error: error instanceof Error ? error.message : 'Failed to update note',
        isLoading: false,
      });
      throw error;
    }
  },

  deleteNote: async (id: string) => {
    set({ isLoading: true, error: null });
    try {
      await notesService.delete(id);
      set((state) => ({
        notes: state.notes.filter((n) => n.id !== id),
        currentNote: state.currentNote?.id === id ? null : state.currentNote,
        isLoading: false,
      }));
    } catch (error) {
      set({
        error: error instanceof Error ? error.message : 'Failed to delete note',
        isLoading: false,
      });
      throw error;
    }
  },

  togglePin: async (id: string) => {
    try {
      const updatedNote = await notesService.togglePin(id);
      set((state) => {
        // Re-sort notes: pinned first, then by date
        const updatedNotes = state.notes.map((n) => (n.id === id ? updatedNote : n));
        updatedNotes.sort((a, b) => {
          if (a.isPinned !== b.isPinned) return a.isPinned ? -1 : 1;
          return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
        });
        return {
          notes: updatedNotes,
          currentNote: state.currentNote?.id === id ? updatedNote : state.currentNote,
        };
      });
    } catch (error) {
      set({
        error: error instanceof Error ? error.message : 'Failed to toggle pin',
      });
    }
  },

  setCurrentNote: (note: Note | null) => set({ currentNote: note }),

  clearError: () => set({ error: null }),

  clearNotes: () => set({ notes: [], currentNote: null }),
}));

import { create } from 'zustand';
import api from '@/services/api';
import { ENDPOINTS } from '@/config/api';
import type { Notification, NotificationPreferences, NotificationsResponse } from '@/types';

interface NotificationsState {
  notifications: Notification[];
  unreadCount: number;
  total: number;
  preferences: NotificationPreferences | null;
  isLoading: boolean;
  isOpen: boolean;

  // Actions
  fetchNotifications: (page?: number, limit?: number) => Promise<void>;
  fetchUnreadCount: () => Promise<void>;
  markAsRead: (id: string) => Promise<void>;
  markAllAsRead: () => Promise<void>;
  deleteNotification: (id: string) => Promise<void>;
  deleteAll: () => Promise<void>;
  fetchPreferences: () => Promise<void>;
  updatePreferences: (prefs: Partial<NotificationPreferences>) => Promise<void>;
  addNotification: (notification: Notification) => void;
  setOpen: (open: boolean) => void;
  toggle: () => void;
}

export const useNotificationsStore = create<NotificationsState>((set, get) => ({
  notifications: [],
  unreadCount: 0,
  total: 0,
  preferences: null,
  isLoading: false,
  isOpen: false,

  fetchNotifications: async (page = 1, limit = 20) => {
    set({ isLoading: true });
    try {
      const response = await api.get<NotificationsResponse>(ENDPOINTS.notifications.list, {
        params: { page, limit },
      });
      set({
        notifications: response.data.data,
        total: response.data.total,
        unreadCount: response.data.unreadCount,
        isLoading: false,
      });
    } catch (error) {
      console.error('Failed to fetch notifications:', error);
      set({ isLoading: false });
    }
  },

  fetchUnreadCount: async () => {
    try {
      const response = await api.get<NotificationsResponse>(ENDPOINTS.notifications.list, {
        params: { page: 1, limit: 1 },
      });
      set({ unreadCount: response.data.unreadCount });
    } catch (error) {
      console.error('Failed to fetch unread count:', error);
    }
  },

  markAsRead: async (id: string) => {
    try {
      await api.post(ENDPOINTS.notifications.markAsRead(id));
      set((state) => ({
        notifications: state.notifications.map((n) =>
          n.id === id ? { ...n, isRead: true } : n
        ),
        unreadCount: Math.max(0, state.unreadCount - 1),
      }));
    } catch (error) {
      console.error('Failed to mark notification as read:', error);
    }
  },

  markAllAsRead: async () => {
    try {
      await api.post(ENDPOINTS.notifications.markAllAsRead);
      set((state) => ({
        notifications: state.notifications.map((n) => ({ ...n, isRead: true })),
        unreadCount: 0,
      }));
    } catch (error) {
      console.error('Failed to mark all notifications as read:', error);
    }
  },

  deleteNotification: async (id: string) => {
    try {
      await api.delete(ENDPOINTS.notifications.delete(id));
      const notification = get().notifications.find((n) => n.id === id);
      set((state) => ({
        notifications: state.notifications.filter((n) => n.id !== id),
        total: state.total - 1,
        unreadCount: notification && !notification.isRead ? state.unreadCount - 1 : state.unreadCount,
      }));
    } catch (error) {
      console.error('Failed to delete notification:', error);
    }
  },

  deleteAll: async () => {
    try {
      await api.delete(ENDPOINTS.notifications.deleteAll);
      set({ notifications: [], total: 0, unreadCount: 0 });
    } catch (error) {
      console.error('Failed to delete all notifications:', error);
    }
  },

  fetchPreferences: async () => {
    try {
      const response = await api.get<NotificationPreferences>(ENDPOINTS.notifications.preferences);
      set({ preferences: response.data });
    } catch (error) {
      console.error('Failed to fetch notification preferences:', error);
    }
  },

  updatePreferences: async (prefs: Partial<NotificationPreferences>) => {
    try {
      const response = await api.post<NotificationPreferences>(ENDPOINTS.notifications.preferences, prefs);
      set({ preferences: response.data });
    } catch (error) {
      console.error('Failed to update notification preferences:', error);
    }
  },

  addNotification: (notification: Notification) => {
    set((state) => ({
      notifications: [notification, ...state.notifications],
      total: state.total + 1,
      unreadCount: notification.isRead ? state.unreadCount : state.unreadCount + 1,
    }));
  },

  setOpen: (open: boolean) => set({ isOpen: open }),

  toggle: () => set((state) => ({ isOpen: !state.isOpen })),
}));

import { create } from 'zustand';
import api from '@/services/api';
import { ENDPOINTS } from '@/config/api';
import type { ProblemSession, StreamEvent, ChatMessage, SimilarProblem } from '@/services/problemSolver';

type SolveStage = 'idle' | 'analyzing' | 'solving' | 'verifying' | 'completed' | 'failed';

interface ProblemSolverState {
  // Sessions
  sessions: ProblemSession[];
  currentSession: ProblemSession | null;
  isLoading: boolean;
  error: string | null;

  // Solving progress
  solveStage: SolveStage;
  streamChunks: Record<string, string>;
  stageResults: Record<string, unknown>;

  // Chat
  chatMessages: ChatMessage[];
  isChatLoading: boolean;

  // Similar problems
  similarProblems: SimilarProblem[];

  // Actions
  fetchSessions: () => Promise<void>;
  fetchSession: (id: string) => Promise<void>;
  createAndSolve: (problem: string, subject?: string, imageUrl?: string) => Promise<string>;
  solveWithStream: (sessionId: string) => Promise<void>;
  deleteSession: (id: string) => Promise<void>;
  fetchSimilarProblems: (id: string) => Promise<void>;
  sendChatMessage: (id: string, message: string) => Promise<void>;
  fetchChatMessages: (id: string) => Promise<void>;
  resetSolving: () => void;
  clearError: () => void;
}

export const useProblemSolverStore = create<ProblemSolverState>((set, get) => ({
  sessions: [],
  currentSession: null,
  isLoading: false,
  error: null,
  solveStage: 'idle',
  streamChunks: {},
  stageResults: {},
  chatMessages: [],
  isChatLoading: false,
  similarProblems: [],

  fetchSessions: async () => {
    set({ isLoading: true, error: null });
    try {
      const res = await api.get(ENDPOINTS.problemSolver.list);
      set({ sessions: res.data, isLoading: false });
    } catch {
      set({ error: 'Failed to load problem history', isLoading: false });
    }
  },

  fetchSession: async (id: string) => {
    set({ isLoading: true, error: null });
    try {
      const res = await api.get(ENDPOINTS.problemSolver.get(id));
      set({ currentSession: res.data, isLoading: false });
    } catch {
      set({ error: 'Failed to load session', isLoading: false });
    }
  },

  createAndSolve: async (problem: string, subject?: string, imageUrl?: string) => {
    set({ isLoading: true, error: null, solveStage: 'idle', streamChunks: {}, stageResults: {} });
    try {
      const res = await api.post(ENDPOINTS.problemSolver.create, {
        problem,
        subject: subject || undefined,
        imageUrl: imageUrl || undefined,
      });
      const session = res.data as ProblemSession;
      set({ currentSession: session, isLoading: false });

      // Start solving with stream
      get().solveWithStream(session.id);
      return session.id;
    } catch {
      set({ error: 'Failed to create session', isLoading: false });
      return '';
    }
  },

  solveWithStream: async (sessionId: string) => {
    set({ solveStage: 'analyzing', streamChunks: {}, stageResults: {} });

    try {
      const token = localStorage.getItem('accessToken');
      const res = await fetch(
        `${api.defaults.baseURL}${ENDPOINTS.problemSolver.solveStream(sessionId)}`,
        {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
          },
        },
      );

      if (!res.ok) throw new Error('Stream failed');

      const reader = res.body?.getReader();
      if (!reader) throw new Error('No reader');

      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        for (const line of lines) {
          if (!line.startsWith('data: ')) continue;
          try {
            const event = JSON.parse(line.slice(6)) as StreamEvent;
            const { stage, type, data } = event;

            if (type === 'start') {
              const stageMap: Record<string, SolveStage> = {
                analysis: 'analyzing',
                solving: 'solving',
                verification: 'verifying',
              };
              set({ solveStage: stageMap[stage] || 'analyzing' });
            } else if (type === 'chunk') {
              const chunks = { ...get().streamChunks };
              chunks[stage] = (chunks[stage] || '') + (data as string);
              set({ streamChunks: chunks });
            } else if (type === 'result') {
              const results = { ...get().stageResults };
              results[stage] = data;
              set({ stageResults: results });

              if (stage === 'complete') {
                set({ solveStage: 'completed' });
                // Refetch session for full data
                const sessionRes = await api.get(ENDPOINTS.problemSolver.get(sessionId));
                set({ currentSession: sessionRes.data });
              }
            }
          } catch {
            // skip unparseable lines
          }
        }
      }
    } catch (err) {
      set({
        solveStage: 'failed',
        error: (err as Error).message || 'Solving failed',
      });
    }
  },

  deleteSession: async (id: string) => {
    try {
      await api.delete(ENDPOINTS.problemSolver.delete(id));
      set({ sessions: get().sessions.filter((s) => s.id !== id) });
    } catch {
      set({ error: 'Failed to delete session' });
    }
  },

  fetchSimilarProblems: async (id: string) => {
    try {
      const res = await api.get(ENDPOINTS.problemSolver.similar(id));
      set({ similarProblems: res.data });
    } catch {
      set({ similarProblems: [] });
    }
  },

  sendChatMessage: async (id: string, message: string) => {
    const userMsg: ChatMessage = {
      id: `temp-${Date.now()}`,
      role: 'user',
      message,
      createdAt: new Date().toISOString(),
    };
    set({ chatMessages: [...get().chatMessages, userMsg], isChatLoading: true });

    try {
      const res = await api.post(ENDPOINTS.problemSolver.chat(id), { message });
      set({
        chatMessages: [...get().chatMessages, res.data],
        isChatLoading: false,
      });
    } catch (err) {
      // Show error as a tutor message so user can see it
      const errorMsg: ChatMessage = {
        id: `error-${Date.now()}`,
        role: 'tutor',
        message: `Sorry, I encountered an error: ${(err as { response?: { data?: { message?: string } }; message?: string })?.response?.data?.message || (err as Error)?.message || 'Failed to get response'}. Please try again.`,
        createdAt: new Date().toISOString(),
      };
      set({
        chatMessages: [...get().chatMessages, errorMsg],
        isChatLoading: false,
      });
    }
  },

  fetchChatMessages: async (id: string) => {
    try {
      const res = await api.get(ENDPOINTS.problemSolver.chatMessages(id));
      set({ chatMessages: res.data });
    } catch {
      set({ chatMessages: [] });
    }
  },

  resetSolving: () => {
    set({
      currentSession: null,
      solveStage: 'idle',
      streamChunks: {},
      stageResults: {},
      chatMessages: [],
      similarProblems: [],
      error: null,
    });
  },

  clearError: () => set({ error: null }),
}));

